window.JEE_MCQ_BANK = [{"q": "NVS-03 will operate in which orbital regime?", "options": ["Geosynchronous", "Low-Earth", "Sun-synchronous", "Molniya"], "answer": 0, "explanation": "It takes a geosynchronous slot at 129.55° East, inclination 5.1°.", "topic": "Physics · Gravitation"},{"q": "NVS-03's designated longitude slot is:", "options": ["129.55° East", "83° East", "55° East", "111.75° East"], "answer": 0, "explanation": "Geosynchronous NavIC satellites hold fixed longitudes over the Indian region.", "topic": "Physics · Gravitation"},{"q": "NVS-03's orbital inclination is:", "options": ["5.1°", "28.5°", "51.6°", "97.4°"], "answer": 0, "explanation": "A small inclination keeps it near-geosynchronous over its longitude slot.", "topic": "Physics · Gravitation"},{"q": "NVS-03's mass is 2,232 kg; GSLV Mk II lifts ~2,500 kg to GTO. The mass margin is about:", "options": ["268 kg", "500 kg", "132 kg", "750 kg"], "answer": 0, "explanation": "2,500 − 2,232 = 268 kg of margin for the 15–20 Oct 2026 launch.", "topic": "Physics · Work, Energy & Power"},{"q": "A reverse-stick hockey strike launches the ball at 25 m/s at 30° to the horizontal. The range is about:", "options": ["55.2 m", "63.8 m", "31.9 m", "110.4 m"], "answer": 0, "explanation": "R = v²sin2θ/g = 625×sin60°/9.8 ≈ 55.2 m — the physics behind Lalremsiami's 10th-minute winner.", "topic": "Physics · Projectile Motion"},{"q": "Sujeet Kalkal's decisive takedown came with 11 seconds left in a 6-minute bout — the fraction of the bout remaining was about:", "options": ["3.1%", "1.8%", "5.5%", "0.3%"], "answer": 0, "explanation": "11/360 ≈ 0.0306 = 3.06% — the 10–9 comeback over Kudiev.", "topic": "Maths · Percentage"},{"q": "96.3150 in scientific notation is:", "options": ["9.63150 × 10¹", "9.63150 × 10²", "96.3150 × 10⁻¹", "0.96315 × 10³"], "answer": 0, "explanation": "The rupee's 2 Oct 2026 level per dollar — a two-month low.", "topic": "Maths · Number System"},{"q": "NVS-03's C-band ranging payload fixes position by measuring:", "options": ["Signal travel time", "Doppler shift only", "Signal polarisation", "Antenna temperature"], "answer": 0, "explanation": "Ranging = distance from round-trip/arrival-time measurements, fused with the L1/L5/S navigation signals.", "topic": "Physics · Communication Systems"},{"q": "A satellite in geosynchronous orbit has an orbital period of:", "options": ["24 hours", "12 hours", "365 days", "90 minutes"], "answer": 0, "explanation": "Geosynchronous means matching Earth's rotation — 24 h; NVS-03 heads to such a slot for NavIC.", "topic": "Physics · Gravitation"},{"q": "A 600 HP engine's power in kilowatts is about:", "options": ["447 kW", "600 kW", "746 kW", "380 kW"], "answer": 0, "explanation": "1 HP = 746 W, so 600 HP = 600 × 0.746 ≈ 447 kW — the class of DRDO's new indigenous combat-vehicle engine.", "topic": "Physics · Work, Energy & Power"},{"q": "A 447 kW engine running at 2000 rpm develops a torque of about:", "options": ["2.14 kN·m", "0.89 kN·m", "4.47 kN·m", "1.07 kN·m"], "answer": 0, "explanation": "P = 2πNT/60 ⇒ T = 447000×60/(2π×2000) ≈ 2136 N·m ≈ 2.14 kN·m.", "topic": "Physics · Rotational Mechanics"},{"q": "Ishan Kishan's 80* off 46 balls is a strike rate of:", "options": ["173.9", "156.2", "190.4", "142.8"], "answer": 0, "explanation": "80/46 × 100 ≈ 173.9 — the Asian Games 2026 semifinal knock vs Sri Lanka.", "topic": "Maths · Percentage"},{"q": "24.07 billion in scientific notation is:", "options": ["2.407 × 10¹⁰", "2.407 × 10⁹", "24.07 × 10⁸", "2.407 × 10¹¹"], "answer": 0, "explanation": "24.07 billion = 24.07 × 10⁹ = 2.407 × 10¹⁰ — September 2026's UPI transaction count.", "topic": "Maths · Number System"},{"q": "Rubidium, used in NavIC atomic clocks, has atomic number:", "options": ["37", "55", "19", "87"], "answer": 0, "explanation": "Rb (Z=37); NVS-03 flies a mix of indigenous and imported rubidium atomic clocks, as on NVS-01/02.", "topic": "Chemistry · Periodic Table"},{"q": "The GPS/NavIC L1 band frequency is:", "options": ["1575.42 MHz", "1227.60 MHz", "1176.45 MHz", "2483.5 MHz"], "answer": 0, "explanation": "L1 = 1575.42 MHz — the mass-market band NVS-03 broadcasts in, reaching ordinary phone receivers.", "topic": "Physics · Communication Systems"},{"q": "Savitha Shri won 8 of 9 games at the Chess Olympiad. Her win percentage is:", "options": ["88.9%", "80.0%", "92.3%", "84.6%"], "answer": 0, "explanation": "8/9 × 100 ≈ 88.9% — the 19-year-old was India's only individual gold medallist at Samarkand 2026.", "topic": "Maths · Percentage"},{"q": "The dimensional formula of the universal gravitational constant G is:", "options": ["[ML²T⁻²]", "[M⁻¹L³T⁻²]", "[MLT⁻²]", "[M⁻¹L²T⁻¹]"], "answer": 1, "explanation": "From F = Gm₁m₂/r², [G] = [Fr²/m²] = MLT⁻²·L²/M² = [M⁻¹L³T⁻²].", "topic": "Physics · Units & Measurement"}, {"q": "lim (x→0) (sin 3x)/x equals:", "options": ["0", "1", "3", "∞"], "answer": 2, "explanation": "(sin 3x)/x = 3·(sin 3x)/(3x) → 3 × 1 = 3.", "topic": "Mathematics · Limits"}, {"q": "The pH of 0.001 M NaOH is:", "options": ["3", "11", "7", "13"], "answer": 1, "explanation": "[OH⁻] = 10⁻³ M, so pOH = 3 and pH = 14 − 3 = 11.", "topic": "Chemistry · Equilibrium"}, {"q": "A convex lens of focal length 20 cm forms an image 60 cm from the lens. The object distance is:", "options": ["15 cm", "30 cm", "40 cm", "20 cm"], "answer": 1, "explanation": "1/v − 1/u = 1/f gives 1/60 − 1/u = 1/20, so 1/u = −1/30 and u = −30 cm (30 cm from the lens).", "topic": "Physics · Ray Optics"}, {"q": "The number of σ and π bonds in ethyne (C₂H₂) is:", "options": ["3σ, 2π", "2σ, 3π", "5σ, 0π", "4σ, 1π"], "answer": 0, "explanation": "The triple bond contributes 1σ + 2π and each C–H bond 1σ: 3σ, 2π in total.", "topic": "Chemistry · Chemical Bonding"},{"q": "A particle executes SHM with amplitude 5 cm and angular frequency 2 rad/s. Its maximum speed is:", "options": ["0.1 m/s", "0.03 m/s", "0.2 m/s", "0.05 m/s"], "answer": 0, "explanation": "v_max = Aω = 0.05×2 = 0.1 m/s.", "topic": "Physics – Oscillations"}, {"q": "The area enclosed between the curve y = 4x − x² and the x-axis is:", "options": ["32/3 sq units", "16/3 sq units", "64/3 sq units", "10 sq units"], "answer": 0, "explanation": "Roots at x = 0 and x = 4. Area = ∫₀⁴ (4x − x²) dx = [2x² − x³/3]₀⁴ = 32 − 64/3 = 32/3.", "topic": "Maths – Definite Integrals"}, {"q": "Borax bead test detects:", "options": ["sulphates", "transition metal ions", "halides", "alkali metals"], "answer": 1, "explanation": "Coloured metaborate beads identify transition metal cations.", "topic": "Chemistry – s, p, d & f Block"}, {"q": "The unit of the rate constant for a third-order reaction is:", "options": ["s⁻¹", "L·mol⁻¹·s⁻¹", "L²·mol⁻²·s⁻¹", "mol·L⁻¹·s⁻¹"], "answer": 2, "explanation": "Units of k = (mol/L)^(1−n)·s⁻¹; for n = 3 this is L²·mol⁻²·s⁻¹.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "The IUPAC name of CH3COCH3 is:", "options": ["propanol", "propanone", "ethanone", "propanal"], "answer": 1, "explanation": "Ketone on a 3-carbon chain → propanone (common: acetone).", "topic": "Chemistry – Organic Chemistry"}, {"q": "Given A → B, ΔH = -50 kJ/mol and B → C, ΔH = -150 kJ/mol, ΔH for A → C is:", "options": ["-100 kJ/mol", "-200 kJ/mol", "200 kJ/mol", "100 kJ/mol"], "answer": 1, "explanation": "Hess's law: ΔH = -50 + (-150) = -200 kJ/mol.", "topic": "Chemistry – Thermodynamics"}, {"q": "Two vectors of magnitudes 4 and 4 units act at 90° to each other. The magnitude of their resultant is:", "options": ["8 units", "5.66 units × 2", "0 units", "5.66 units"], "answer": 3, "explanation": "R = √(A² + B² + 2ABcosθ) = √(4²+4²+2×4×4×cos90°) = 5.66 units.", "topic": "Physics – Vectors"}, {"q": "A ball is projected with velocity 20 m/s at 60° above the horizontal. The maximum height reached is (g = 10 m/s²):", "options": ["15 m", "7.5 m", "20 m", "30 m"], "answer": 0, "explanation": "H = u²sin²θ/(2g) = 20²×sin²60°/20 = 15 m.", "topic": "Physics – Projectile Motion"}, {"q": "The centre and radius of x² + y² − 2x − 2y + -14 = 0 are:", "options": ["(1, 1), 8", "(2, 2), 4", "(1, 1), 4", "(-1, -1), 4"], "answer": 2, "explanation": "Centre = (−g, −f) = (1, 1); radius = √(g² + f² − c) = 4.", "topic": "Maths – Circles"}, {"q": "The number of terms in the expansion of (x + y)^6 is:", "options": ["6", "8", "7", "12"], "answer": 2, "explanation": "(x + y)ⁿ expands to n + 1 = 7 terms.", "topic": "Maths – Binomial Theorem"}, {"q": "If P(A) = 0.4 and P(B) = 0.5 with A, B independent, then P(A ∩ B) equals:", "options": ["0.1", "0.9", "0.2", "0.45"], "answer": 2, "explanation": "Independent: P(A∩B) = P(A)·P(B) = 0.4×0.5 = 0.2.", "topic": "Maths – Probability"}, {"q": "A long straight wire carries 10 A. The magnetic field at a perpendicular distance 5 cm from it is:", "options": ["20 μT", "40 μT", "160 μT", "80 μT"], "answer": 1, "explanation": "B = μ₀I/(2πr) = 2×10⁻⁷×10/0.05 = 40 μT.", "topic": "Physics – Magnetism"}, {"q": "For a reaction, ΔH = -100 kJ/mol and ΔS = 200 J/mol·K at 500 K. The reaction is:", "options": ["non-spontaneous", "endothermic and reversible", "spontaneous", "at equilibrium"], "answer": 2, "explanation": "ΔG = ΔH − TΔS = -100 − 500×0.2 = -200 kJ/mol; negative ΔG ⇒ spontaneous.", "topic": "Chemistry – Thermodynamics"}, {"q": "The unit of the rate constant for a first-order reaction is:", "options": ["s⁻¹", "L²·mol⁻²·s⁻¹", "mol·L⁻¹·s⁻¹", "L·mol⁻¹·s⁻¹"], "answer": 0, "explanation": "Units of k = (mol/L)^(1−n)·s⁻¹; for n = 1 this is s⁻¹.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "If n(A) = 2 and n(B) = 2, the number of relations from A to B is:", "options": ["4", "8", "16 × 2", "16"], "answer": 3, "explanation": "Relations = subsets of A×B: 2^(n(A)·n(B)) = 2^4 = 16.", "topic": "Maths – Sets & Functions"}, {"q": "The oxidation number of Fe in Fe3O4 is (average):", "options": ["+3", "+2", "+8/3", "+4"], "answer": 2, "explanation": "3x + 4(−2) = 0 ⇒ x = +8/3 (mixed FeO·Fe2O3).", "topic": "Chemistry – Redox Reactions"}, {"q": "The area of the triangle with vertices (0, 0), (4, 0) and (0, 3) is:", "options": ["12 sq units", "6 sq units", "3 sq units", "7 sq units"], "answer": 1, "explanation": "Area = ½|det [[4, 0], [0, 3]]| = ½ × 12 = 6 sq units.", "topic": "Maths – Matrices & Determinants"}, {"q": "Wurtz reaction of CH3Br with Na gives:", "options": ["propane", "butane", "methane", "ethane"], "answer": 3, "explanation": "2CH3Br + 2Na → CH3CH3 + 2NaBr.", "topic": "Chemistry – Organic Chemistry"}, {"q": "A first-order reaction has k = 0.0693 s⁻¹. Its half-life (in s) is:", "options": ["10 s", "20 s", "5 s", "11 s"], "answer": 0, "explanation": "t½ = 0.693/k = 0.693/0.0693 ≈ 10 s.", "topic": "Chemistry – Chemical Kinetics (numerical)"}, {"q": "100 mL of 0.5 M NaOH is diluted to 500 mL. The molarity of the diluted solution is:", "options": ["0.05 M", "0.1 M", "0.5 M", "0.2 M"], "answer": 1, "explanation": "M₁V₁ = M₂V₂ ⇒ M₂ = 0.5×100/500 = 0.1 M.", "topic": "Chemistry – Solutions"}, {"q": "The degree of (dy/dx)² + y = x is:", "options": ["3", "1", "2", "not defined"], "answer": 2, "explanation": "Degree = power of the highest-order derivative = 2.", "topic": "Maths – Differential Equations"}, {"q": "The bond order of NO+ is:", "options": ["4", "3.5", "3", "2.5"], "answer": 2, "explanation": "Bond order = (bonding − antibonding electrons)/2; for NO+ this equals 3.", "topic": "Chemistry – Chemical Bonding"}, {"q": "A 4 kg mass moves in a circle of radius 5 m with speed 10 m/s. The centripetal force on it is:", "options": ["800 N", "8 N", "80 N", "40 N"], "answer": 2, "explanation": "Centripetal force F = mv²/r = 4×10²/5 = 80 N.", "topic": "Physics – Circular Motion"}, {"q": "Increasing temperature increases reaction rate mainly because:", "options": ["the activation energy decreases", "the equilibrium shifts", "more molecules exceed the activation energy", "collisions become elastic"], "answer": 2, "explanation": "The Boltzmann factor e^(−Ea/RT) rises steeply with T, so far more collisions are fruitful.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "At a height 1R above Earth's surface (R = Earth's radius), the acceleration due to gravity is (g at surface):", "options": ["g/2", "g/4", "g", "g/8"], "answer": 1, "explanation": "g_h = g(R/(R+h))² = g/(1+1)² = g/4.", "topic": "Physics – Gravitation"}, {"q": "The nature of the roots of 2x² + 6x + 3 = 0 is:", "options": ["real and equal", "complex (non-real)", "real and distinct × 2", "real and distinct"], "answer": 3, "explanation": "D = b² − 4ac = 6² − 4×2×3 = 12; sign of D gives real and distinct roots.", "topic": "Maths – Quadratic Equations"}, {"q": "A 5 kg block rests on a smooth incline of 30°. The component of its weight parallel to the incline is (g = 10 m/s²):", "options": ["12.5 N", "43.3 N", "25 N", "50 N"], "answer": 2, "explanation": "Parallel component = mg sinθ = 5×10×sin30° = 25 N.", "topic": "Physics – Laws of Motion"}, {"q": "The value of k for which the points (1, 2), (3, k) and (5, 6) are collinear is:", "options": ["2", "4", "6", "8"], "answer": 1, "explanation": "Collinearity needs det [[1, 2, 1], [3, k, 1], [5, 6, 1]] = 0, i.e. (k − 6) + 4 + (18 − 5k) = 16 − 4k = 0, so k = 4.", "topic": "Maths – Matrices & Determinants"}, {"q": "The energy of the photon emitted when an electron in hydrogen drops from n = 4 to n = 3 is:", "options": ["0.66 eV", "0.33 eV", "1.32 eV", "-0.66 eV"], "answer": 0, "explanation": "ΔE = 13.6(1/n₁² − 1/n₂²) = 13.6(1/3² − 1/4²) = 0.66 eV.", "topic": "Chemistry – Atomic Structure"}, {"q": "The median of the data 7, 3, 9, 1, 5 is:", "options": ["3", "5", "7", "9"], "answer": 1, "explanation": "Sorted: 1, 3, 5, 7, 9. The middle (3rd) value is 5.", "topic": "Maths – Statistics"}, {"q": "The slope of the tangent to the curve y = x² at the point where x = 3 is:", "options": ["3", "6", "9", "12"], "answer": 1, "explanation": "dy/dx = 2x, so at x = 3 the slope is 6.", "topic": "Maths – Differentiation"}, {"q": "The maximum value of y = −2x² + 4x is:", "options": ["1", "3", "2", "4"], "answer": 2, "explanation": "Vertex at x = −B/(2A) = 4/(2×2) = 1; y_max = 2.", "topic": "Maths – Applications of Derivatives"}, {"q": "A convex lens has focal length 25 cm (magnitude). Its power is:", "options": ["-4 D", "0.25 D", "0.04 D", "4 D"], "answer": 3, "explanation": "P = 100/f(cm) = 4 = 4 D.", "topic": "Physics – Ray Optics"}, {"q": "2 mol of an ideal gas expands isothermally at 300 K from V to 2V. The work done by the gas is (R = 8.314 J/mol·K):", "options": ["3457.7 J", "1728.85 J", "1501.66 J", "4988.4 J"], "answer": 0, "explanation": "W = nRT ln(V₂/V₁) = 2×8.314×300×ln2 = 3457.7 J.", "topic": "Physics – Thermodynamics"}, {"q": "In a reversible adiabatic expansion of an ideal gas, the work done by the gas comes from:", "options": ["heat absorbed from the surroundings", "the internal energy of the gas", "work done by an external agent", "the pressure of the surroundings"], "answer": 1, "explanation": "For adiabatic Q = 0, so W = −ΔU; the gas cools as internal energy is spent.", "topic": "Physics – Thermodynamics"}, {"q": "3 mol of ideal gas at 2 atm and 273 K occupies (R = 0.0821 L·atm/mol·K):", "options": ["67.24 L", "16.81 L", "33.62 L", "134.48 L"], "answer": 2, "explanation": "V = nRT/P = 3×0.0821×273/2 = 33.62 L.", "topic": "Chemistry – Gaseous State"}, {"q": "A compound contains 40% C, 6.7% H and 53.3% O by mass. Its empirical formula is:", "options": ["CHO", "C2H4O", "CH4O", "CH2O"], "answer": 3, "explanation": "C: 40/12 = 3.33, H: 6.7/1 = 6.7, O: 53.3/16 = 3.33 ⇒ ratio 1:2:1 ⇒ CH2O.", "topic": "Chemistry – Mole Concept"}, {"q": "The sum of the roots of 3x² − 5x + 2 = 0 is:", "options": ["5/3", "−5/3", "2/3", "5"], "answer": 0, "explanation": "Sum of roots = −b/a = 5/3.", "topic": "Maths – Quadratic Equations"}, {"q": "A wave of frequency 50 Hz has wavelength 0.5 m. Its speed is:", "options": ["25 m/s", "100 m/s", "12.5 m/s", "50 m/s"], "answer": 0, "explanation": "v = fλ = 50×0.5 = 25 m/s.", "topic": "Physics – Waves"}, {"q": "A wire of length 1 m and cross-section 1 mm² is stretched by 2 mm under a force of 100 N. The elastic potential energy stored is:", "options": ["0.2 J", "0.1 J", "0.1 J × 2", "0.05 J"], "answer": 1, "explanation": "U = ½ × force × extension = ½×100×0 = 0.1 J.", "topic": "Physics – Elasticity"}, {"q": "The limit of (x^5 − 3^5)/(x − 3) as x → 3 is:", "options": ["405", "81", "2025", "243"], "answer": 0, "explanation": "Standard form: lim = n·aⁿ⁻¹ = 5×3ⁿ⁻¹ = 405.", "topic": "Maths – Limits"}, {"q": "A satellite orbits very close to Earth's surface. Its orbital period is approximately:", "options": ["12 hours", "24 hours", "30 days", "84 minutes"], "answer": 3, "explanation": "T = 2π√(R/g) ≈ 84 min for a low Earth orbit.", "topic": "Physics – Gravitation"}, {"q": "The direction cosines of the x-axis are:", "options": ["(0, 1, 0)", "(1, 0, 0)", "(1, 1, 1)", "(0, 0, 1)"], "answer": 1, "explanation": "The x-axis makes angles 0°, 90°, 90° with the axes → (1, 0, 0).", "topic": "Maths – 3D Geometry"}, {"q": "The midpoint of the line segment joining (2, 4, 6) and (4, 8, 10) is:", "options": ["(3, 6, 8)", "(2, 4, 6)", "(6, 12, 16)", "(3, 4, 8)"], "answer": 0, "explanation": "Midpoint = ((2+4)/2, (4+8)/2, (6+10)/2) = (3, 6, 8).", "topic": "Maths – 3D Geometry"}, {"q": "If |a + b| = |a − b| for two non-zero vectors a and b, the angle between them is:", "options": ["0°", "60°", "90°", "180°"], "answer": 2, "explanation": "Squaring gives a·b = −a·b, so a·b = 0; the vectors are perpendicular.", "topic": "Physics – Vectors"}, {"q": "Plaster of Paris is:", "options": ["CaSO4·2H2O", "CaSO4·½H2O", "CaCO3", "CaO"], "answer": 1, "explanation": "Gypsum (CaSO4·2H2O) heated to 393 K gives Plaster of Paris.", "topic": "Chemistry – s, p, d & f Block"}, {"q": "The unit vector in the direction of (3, 4, 0) is:", "options": ["(3, 4, 0)", "(3/5, 4/5, 0)", "(1, 1, 0)", "(3/7, 4/7, 0)"], "answer": 1, "explanation": "Divide by |(3, 4, 0)| = 5: (3/5, 4/5, 0).", "topic": "Maths – Vectors"}, {"q": "Two tuning forks of frequencies 512 Hz and 518 Hz are sounded together. The beat frequency heard is:", "options": ["518 Hz", "6 Hz", "3 Hz", "12 Hz"], "answer": 1, "explanation": "Beat frequency = |f₁ − f₂| = 6 Hz.", "topic": "Physics – Waves"}, {"q": "Two dice are thrown. The probability that the sum is 7 is:", "options": ["7/36", "1/36", "1/12", "1/6"], "answer": 3, "explanation": "Favourable: (1,6),(2,5),(3,4),(4,3),(5,2),(6,1) = 6 of 36 = 1/6.", "topic": "Maths – Probability"}, {"q": "The gauge pressure at depth 10 m in a liquid of density 1000 kg/m³ is (g = 10 m/s²):", "options": ["400 kPa", "100 kPa", "50 kPa", "200 kPa"], "answer": 1, "explanation": "P = ρgh = 1000×10×10 = 100000 Pa = 100 kPa.", "topic": "Physics – Fluid Mechanics"}, {"q": "The unit of the rate constant for a zero-order reaction is:", "options": ["L²·mol⁻²·s⁻¹", "s⁻¹", "mol·L⁻¹·s⁻¹", "L·mol⁻¹·s⁻¹"], "answer": 2, "explanation": "Units of k = (mol/L)^(1−n)·s⁻¹; for n = 0 this is mol·L⁻¹·s⁻¹.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "CO2 is linear because carbon is:", "options": ["sp² hybridized", "sp³ hybridized", "unhybridized", "sp hybridized"], "answer": 3, "explanation": "Two double bonds with no lone pairs on C → linear, sp.", "topic": "Chemistry – Chemical Bonding"}, {"q": "The coordination number of Pt in [Pt(NH3)2Cl2] is:", "options": ["2", "3", "6", "4"], "answer": 3, "explanation": "2 NH3 + 2 Cl ligands → coordination number 4.", "topic": "Chemistry – Coordination Compounds"}, {"q": "The bond order of F2 is:", "options": ["1.5", "2", "0.5", "1"], "answer": 3, "explanation": "Bond order = (bonding − antibonding electrons)/2; for F2 this equals 1.", "topic": "Chemistry – Chemical Bonding"}, {"q": "If f(x) = x³, then the value of the second derivative f″(2) is:", "options": ["6", "12", "24", "8"], "answer": 1, "explanation": "f′(x) = 3x² and f″(x) = 6x, so f″(2) = 12.", "topic": "Maths – Differentiation"}, {"q": "For a zero-order reaction with rate constant k, the half-life is proportional to:", "options": ["nothing; it is constant", "the square of the initial concentration", "the initial concentration", "1/(initial concentration)"], "answer": 2, "explanation": "Zero order: t½ = [A]₀/(2k) ∝ [A]₀ = 0.4 M here.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "A 5 kg block on a horizontal surface has coefficient of static friction 0.3. The maximum horizontal force before it slips is (g = 10 m/s²):", "options": ["7.5 N", "50 N", "15 N", "1.5 N"], "answer": 2, "explanation": "Limiting friction f = μN = μ(mg) = 0.3×5×10 = 15 N.", "topic": "Physics – Laws of Motion"}, {"q": "The product i(2 + 3i), where i = √(−1), written in a + ib form is:", "options": ["−3 + 2i", "3 + 2i", "−3 − 2i", "2 + 3i"], "answer": 0, "explanation": "i(2 + 3i) = 2i + 3i² = 2i − 3 = −3 + 2i.", "topic": "Maths – Complex Numbers"}, {"q": "The wavelength of the Hα line (n = 3 → 2 transition) of hydrogen is approximately (R = 1.097×10⁷ m⁻¹):", "options": ["656 nm", "486 nm", "434 nm", "410 nm"], "answer": 0, "explanation": "1/λ = R(1/4 − 1/9) = 5R/36, giving λ ≈ 656 nm.", "topic": "Chemistry – Atomic Structure"}, {"q": "A projectile is fired with speed 30 m/s at 45° to the horizontal (g = 10 m/s²). Its horizontal range is:", "options": ["90 m", "180 m", "45 m", "127.28 m"], "answer": 0, "explanation": "Range R = u²sin2θ/g; at 45°, sin2θ = 1, so R = 30²/10 = 90 m.", "topic": "Physics – Projectile Motion"}, {"q": "The discriminant of the quadratic equation x² + 4x + 4 = 0 equals:", "options": ["16", "0", "−16", "8"], "answer": 1, "explanation": "D = b² − 4ac = 16 − 16 = 0, so the equation has equal real roots.", "topic": "Maths – Quadratic Equations"}, {"q": "For the Ag electrode with E° = 0.8 V (n = 1) and ion activity giving Q = 0.1, the electrode potential at 298 K is:", "options": ["0.86 V", "0.8 V", "1.72 V", "0.74 V"], "answer": 0, "explanation": "E = E° − (0.0591/n)logQ = 0.8 − (0.0591/1)×log(0.1) = 0.86 V.", "topic": "Chemistry – Electrochemistry"}, {"q": "The modulus of the complex number 5 − 12i is:", "options": ["13", "17", "7", "√119"], "answer": 0, "explanation": "|5 − 12i| = √(5² + 12²) = √169 = 13.", "topic": "Maths – Complex Numbers"}, {"q": "The number of ways to choose a committee of 3 from 8 people is:", "options": ["24", "56", "336", "48"], "answer": 1, "explanation": "C(8, 3) = 8!/(3!5!) = 56.", "topic": "Maths – Permutations & Combinations"}, {"q": "If one root of x² − 4x + k = 0 is 1, then the value of k is:", "options": ["3", "−3", "4", "5"], "answer": 0, "explanation": "Substituting x = 1: 1 − 4 + k = 0, so k = 3.", "topic": "Maths – Quadratic Equations"}, {"q": "A process has ΔH = −120 kJ/mol and ΔS = −400 J/mol·K. The temperature above which it becomes non-spontaneous is:", "options": ["300 K", "120 K", "480 K", "33 K"], "answer": 0, "explanation": "ΔG = 0 at T = ΔH/ΔS = 120000/400 = 300 K; with both negative, ΔG > 0 above this T.", "topic": "Chemistry – Thermodynamics"}, {"q": "The speed of sound in air at 0°C is about 332 m/s. At 27°C it is approximately:", "options": ["348 m/s", "332 m/s", "359 m/s", "300 m/s"], "answer": 0, "explanation": "v ∝ √T, so v = 332√(300/273) ≈ 348 m/s.", "topic": "Physics – Waves"}, {"q": "An object is placed 60 cm in front of a concave mirror of focal length 15 cm. The image distance is:", "options": ["20 cm × 2", "12 cm", "20 cm", "30 cm"], "answer": 2, "explanation": "1/v = 1/f − 1/u = 1/15 − 1/60 ⇒ v = 20 cm (real, inverted).", "topic": "Physics – Ray Optics"}, {"q": "A vector of magnitude 10 units makes an angle of 60° with the x-axis. Its x-component is:", "options": ["5 units", "8.66 units", "10 units", "2.5 units"], "answer": 0, "explanation": "x-component = 10 cos 60° = 10 × 0.5 = 5 units.", "topic": "Physics – Vectors"}, {"q": "A bag has 3 red and 2 blue balls. The probability of drawing a red ball is:", "options": ["2/5", "1/3", "3/2", "3/5"], "answer": 3, "explanation": "P(red) = 3/(3+2) = 3/5.", "topic": "Maths – Probability"}, {"q": "A wooden block floats in water with half its volume submerged. The density of the wood is:", "options": ["500 kg/m³", "1000 kg/m³", "250 kg/m³", "2000 kg/m³"], "answer": 0, "explanation": "For floating, ρ_wood/ρ_water = fraction submerged = 1/2, so ρ = 500 kg/m³.", "topic": "Physics – Fluid Mechanics"}, {"q": "Given C + O₂ → CO₂, ΔH = −394 kJ/mol and CO + ½O₂ → CO₂, ΔH = −283 kJ/mol, the enthalpy change for C + ½O₂ → CO is:", "options": ["−677 kJ/mol", "−111 kJ/mol", "+111 kJ/mol", "−283 kJ/mol"], "answer": 1, "explanation": "Reverse the second reaction and add to the first: ΔH = −394 + 283 = −111 kJ/mol (Hess's law).", "topic": "Chemistry – Thermodynamics"}, {"q": "The energy of the electron in the n = 5 shell of He⁺ (Z = 2) is:", "options": ["-1.09 eV", "-0.54 eV", "-0.14 eV", "-2.18 eV"], "answer": 3, "explanation": "Eₙ = −13.6·Z²/n² = −13.6×4/5² = -2.18 eV.", "topic": "Chemistry – Atomic Structure"}, {"q": "The SI unit of the modulus of elasticity is:", "options": ["N/m", "N/m²", "N·m", "kg/m³"], "answer": 1, "explanation": "Modulus = stress/strain has the dimensions of pressure: N/m² (pascal).", "topic": "Physics – Elasticity"}, {"q": "Saponification of fats gives:", "options": ["fatty acid + water", "ethanol + soap", "glycerol + acid", "glycerol + soap"], "answer": 3, "explanation": "Base hydrolysis of triglycerides → glycerol + fatty acid salts (soap).", "topic": "Chemistry – Organic Chemistry"}, {"q": "The hybridization of Xe in XeF4 is:", "options": ["sp³", "sp³d", "dsp²", "sp³d²"], "answer": 3, "explanation": "XeF4 has 4 bond pairs + 2 lone pairs → octahedral electron geometry, sp³d².", "topic": "Chemistry – Chemical Bonding"}, {"q": "For the reaction N2 + 3H2 ⇌ 2NH3 (ΔH negative), increasing temperature:", "options": ["shifts equilibrium to the left", "shifts equilibrium to the right", "has no effect", "doubles Kc"], "answer": 0, "explanation": "Exothermic forward reaction: higher T favours the endothermic (reverse) direction — Le Chatelier.", "topic": "Chemistry – Equilibrium"}, {"q": "The maximum number of electrons in the n = 3 shell is:", "options": ["18", "9", "32", "8"], "answer": 0, "explanation": "Maximum = 2n² = 2×9 = 18.", "topic": "Chemistry – Atomic Structure"}, {"q": "The number of atoms per unit cell in a diamond cubic lattice is:", "options": ["1", "4", "2", "8"], "answer": 3, "explanation": "FCC (4) + 4 interior atoms = 8 atoms.", "topic": "Chemistry – Solid State"}, {"q": "Water flows through a pipe of cross-section 0.02 m² at 2 m/s. The volume flow rate is:", "options": ["0.04 m³/s", "0.01 m³/s", "1 m³/s", "4 m³/s"], "answer": 0, "explanation": "Q = Av = 0.02 × 2 = 0.04 m³/s.", "topic": "Physics – Fluid Mechanics"}, {"q": "A 10 μF capacitor is charged to 500 V. The energy stored in it is:", "options": ["2.5 J", "0.62 J", "1.25 J × 2", "1.25 J"], "answer": 3, "explanation": "U = ½CV² = ½×10×10⁻⁶×500² = 1.25 J.", "topic": "Physics – Capacitors"}, {"q": "Copper is refined by:", "options": ["electrolytic refining", "cupellation", "distillation", "zone refining"], "answer": 0, "explanation": "Blister copper is purified by electrolytic refining.", "topic": "Chemistry – s, p, d & f Block"}, {"q": "The mode of the data 4, 6, 4, 9, 4, 2 is:", "options": ["2", "6", "9", "4"], "answer": 3, "explanation": "4 occurs three times, more than any other value, so the mode is 4.", "topic": "Maths – Statistics"}, {"q": "A car takes a circular turn of radius 50 m at a speed of 10 m/s. Its centripetal acceleration is:", "options": ["2 m/s²", "5 m/s²", "0.2 m/s²", "20 m/s²"], "answer": 0, "explanation": "a = v²/r = 100/50 = 2 m/s², directed towards the centre.", "topic": "Physics – Circular Motion"}, {"q": "A string of length 1 m fixed at both ends vibrates in its fundamental mode with wave speed 200 m/s. Its frequency is:", "options": ["100 Hz", "200 Hz", "50 Hz", "400 Hz"], "answer": 0, "explanation": "Fundamental: f = v/2L = 200/2 = 100 Hz.", "topic": "Physics – Waves"}, {"q": "cos(2x) in terms of sin x is:", "options": ["1 + 2sin²x", "2sin x", "1 − 2sin²x", "2sin²x − 1"], "answer": 2, "explanation": "Double-angle: cos 2x = 1 − 2sin²x.", "topic": "Maths – Trigonometry"}, {"q": "The freezing point depression of a 1 molal aqueous solution of glucose (van't Hoff factor i = 2, Kf = 1.86 K·kg/mol) is:", "options": ["7.44 K", "3.72 K × 2", "3.72 K", "1.86 K"], "answer": 2, "explanation": "ΔTf = i·Kf·m = 2×1.86×1 = 3.72 K.", "topic": "Chemistry – Solutions"}, {"q": "A projectile has the same horizontal range for two different angles of projection. If one angle is 30°, the other is:", "options": ["45°", "60°", "15°", "75°"], "answer": 1, "explanation": "Range is the same for complementary angles θ and 90° − θ, so the other angle is 60°.", "topic": "Physics – Projectile Motion"}, {"q": "A spring of force constant 100 N/m is stretched by 0.5 m. The elastic potential energy stored is:", "options": ["6.25 J", "50 J", "25 J", "12.5 J"], "answer": 3, "explanation": "U = ½kx² = ½×100×0.5² = 12.5 J.", "topic": "Physics – Work, Energy & Power"}, {"q": "A steel wire (Y = 2×10¹¹ N/m²) of length 2 m and cross-section 1 mm² is stretched by 1 mm. The force required is:", "options": ["10⁵ N", "10⁴ N", "2×10⁵ N", "10³ N"], "answer": 0, "explanation": "F = YAΔL/L = 2×10¹¹ × 10⁻⁶ × 10⁻³/2 = 10⁵ N.", "topic": "Physics – Elasticity"}, {"q": "∫₀^π sin(x) dx equals:", "options": ["0", "π", "1", "2"], "answer": 3, "explanation": "[−cos x]₀^π = −cosπ + cos0 = 1 + 1 = 2.", "topic": "Maths – Definite Integrals"}, {"q": "A coil of 200 turns has its flux changed by 0.02 Wb in 0.01 s. The magnitude of induced emf is:", "options": ["400 V", "2 V", "4 V", "200 V"], "answer": 0, "explanation": "|ε| = NΔΦ/Δt = 200×0.02/0.01 = 400 V.", "topic": "Physics – EMI & AC"}, {"q": "For a projectile fired at 45°, the horizontal range R and the maximum height H are related by:", "options": ["R = 4H", "R = 2H", "R = H", "R = 8H"], "answer": 0, "explanation": "R = u²/g and H = u²/4g at 45°, so R = 4H.", "topic": "Physics – Projectile Motion"}, {"q": "An object is placed 60 cm in front of a convex mirror of focal length 20 cm. The image formed is:", "options": ["real and inverted", "virtual, erect and diminished", "real and enlarged", "virtual and enlarged"], "answer": 1, "explanation": "A convex mirror always forms a virtual, erect, diminished image behind the mirror.", "topic": "Physics – Ray Optics"}, {"q": "The standard Gibbs energy of formation of NO₂(g) is +51 kJ/mol. Formation of NO₂ from its elements under standard conditions is:", "options": ["spontaneous", "non-spontaneous", "at equilibrium", "impossible to predict"], "answer": 1, "explanation": "ΔG° > 0 means the formation reaction is non-spontaneous under standard conditions.", "topic": "Chemistry – Thermodynamics"}, {"q": "If a = (2, 1, 0) and b = (1, 1, 0), then a·b equals:", "options": ["3", "3 × 2", "2", "4"], "answer": 0, "explanation": "a·b = 2×1 + 1×1 = 3.", "topic": "Maths – Vectors"}, {"q": "The length of the latus rectum of y² = 12x is:", "options": ["12", "24", "6", "3"], "answer": 0, "explanation": "For y² = 4ax, latus rectum = 4a = 12.", "topic": "Maths – Conic Sections"}, {"q": "The ratio of the radius of the second Bohr orbit to that of the first Bohr orbit of hydrogen is:", "options": ["2 : 1", "4 : 1", "1 : 4", "8 : 1"], "answer": 1, "explanation": "r_n ∝ n², so r₂/r₁ = 4.", "topic": "Chemistry – Atomic Structure"}, {"q": "In a single throw of a die, the probability of getting a number greater than 3 is:", "options": ["1/2", "1/6", "0.67", "0.5"], "answer": 3, "explanation": "Favourable outcomes: 4, …, 6 → 3 of 6 ⇒ 0.5.", "topic": "Maths – Probability"}, {"q": "Two 3 μF capacitors are connected in series. The equivalent capacitance is:", "options": ["1.5 μF", "6 μF", "2 μF", "3 μF"], "answer": 0, "explanation": "Series: 1/C = 1/3 + 1/3 ⇒ C = 1.5 μF.", "topic": "Physics – Capacitors"}, {"q": "The number of atoms per unit cell in an FCC lattice is:", "options": ["2", "6", "4", "1"], "answer": 2, "explanation": "FCC: 8 corners × 1/8 + 6 faces × 1/2 = 4 atoms.", "topic": "Chemistry – Solid State"}, {"q": "The sum of the first 20 terms of the AP 2, 5, 8, … is:", "options": ["610", "590", "620", "600"], "answer": 0, "explanation": "S₂₀ = (20/2)(2×2 + 19×3) = 10 × 61 = 610.", "topic": "Maths – Sequences & Series"}, {"q": "The hybridization of N in NH4⁺ is:", "options": ["dsp³", "sp³", "sp²", "sp"], "answer": 1, "explanation": "NH4⁺ has 4 sigma bonds → tetrahedral, sp³.", "topic": "Chemistry – Chemical Bonding"}, {"q": "The SI unit of magnetic flux is:", "options": ["tesla", "weber", "henry", "farad"], "answer": 1, "explanation": "Magnetic flux is measured in weber (Wb).", "topic": "Physics – EMI & AC"}, {"q": "The median of 3, 7, 9, 12, 15 is:", "options": ["7", "9.4", "12", "9"], "answer": 3, "explanation": "Ordered data has 5 values; the middle (3rd) is 9.", "topic": "Maths – Statistics"}, {"q": "If y = (2x + 1)³, then the value of dy/dx at x = 1 is:", "options": ["54", "27", "36", "18"], "answer": 0, "explanation": "By the chain rule, dy/dx = 3(2x + 1)² × 2 = 6(2x + 1)²; at x = 1 this is 6 × 9 = 54.", "topic": "Maths – Differentiation"}, {"q": "If tan x = 1, then x (in [0, π]) equals:", "options": ["π/2", "π/4", "0", "π/3"], "answer": 1, "explanation": "tan x = 1 ⇒ x = π/4 in [0, π].", "topic": "Maths – Trigonometry"}, {"q": "A particle moves with velocity v(t) = 2t m/s. The distance it travels between t = 0 s and t = 5 s is:", "options": ["10 m", "25 m", "50 m", "12.5 m"], "answer": 1, "explanation": "Distance = ∫₀⁵ 2t dt = [t²]₀⁵ = 25 m.", "topic": "Maths – Definite Integrals"}, {"q": "Which is an ambidentate ligand?", "options": ["en", "NH3", "CN⁻", "H2O"], "answer": 2, "explanation": "CN⁻ can bind through C or N (also NO2⁻ through N or O).", "topic": "Chemistry – Coordination Compounds"}, {"q": "Two point charges 2 μC and 3 μC are 0.5 m apart in vacuum. The electrostatic force between them is:", "options": ["2.16 N", "0.22 N", "0.02 N", "0.11 N"], "answer": 1, "explanation": "F = kq₁q₂/r² = 9×10⁹×2×3×10⁻¹²/0.5² = 0.22 N.", "topic": "Physics – Electrostatics"}, {"q": "A body of mass 5 kg has linear momentum 20 kg·m/s. Its kinetic energy is:", "options": ["80 J", "40 J × 2", "20 J", "40 J"], "answer": 3, "explanation": "KE = p²/(2m) = 20²/(2×5) = 40 J.", "topic": "Physics – Work, Energy & Power"}, {"q": "A 0.5 kg block attached to a horizontal spring of force constant 200 N/m oscillates with amplitude 8 cm. The magnitude of its maximum acceleration is:", "options": ["32 m/s²", "16 m/s²", "3.2 m/s²", "1.6 m/s²"], "answer": 0, "explanation": "ω = √(k/m) = √(200/0.5) = 20 rad/s. a_max = ω²A = 400 × 0.08 = 32 m/s².", "topic": "Physics – Oscillations"}, {"q": "A mass of 1 kg attached to a spring of constant 100 N/m oscillates. Its time period is:", "options": ["0.63 s × 2", "1.26 s", "0.31 s", "0.63 s"], "answer": 3, "explanation": "T = 2π√(m/k) = 2π√(1/100) = 0.63 s.", "topic": "Physics – Oscillations"}, {"q": "The area under y = x from x = 0 to x = 4 (in sq. units) is:", "options": ["8 sq units", "16 sq units", "4 sq units", "9 sq units"], "answer": 0, "explanation": "Area = ∫₀^4 x dx = 4²/2 = 8.", "topic": "Maths – Definite Integrals (numerical)"}, {"q": "The shape of XeF2 is:", "options": ["bent", "T-shaped", "pyramidal", "linear"], "answer": 3, "explanation": "3 lone pairs + 2 bond pairs → linear arrangement of F atoms.", "topic": "Chemistry – s, p, d & f Block"}, {"q": "The number of moles in 79 g of KMnO4 (molar mass 158 g/mol) is:", "options": ["0.5 mol", "12482 mol", "0.25 mol", "1 mol"], "answer": 0, "explanation": "n = mass/molar mass = 79/158 = 0.5 mol.", "topic": "Chemistry – Mole Concept"}, {"q": "The boiling point elevation of a 1 molal aqueous solution of urea (Kb = 0.52 K·kg/mol) is:", "options": ["0.52 K", "1.86 K", "1 K", "0.26 K"], "answer": 0, "explanation": "ΔTb = i·Kb·m = 1 × 0.52 × 1 = 0.52 K.", "topic": "Chemistry – Solutions"}, {"q": "For a particle in uniform circular motion, the angle between its velocity and acceleration vectors is:", "options": ["0°", "45°", "90°", "180°"], "answer": 2, "explanation": "Velocity is tangential and centripetal acceleration is radial, so they are perpendicular.", "topic": "Physics – Circular Motion"}, {"q": "A constant force of 10 N acts on a body at 60° to its displacement of 5 m. The work done is:", "options": ["25 J", "50 J", "12.5 J", "43.3 J"], "answer": 0, "explanation": "W = Fd cosθ = 10×5×cos60° = 25 J.", "topic": "Physics – Work, Energy & Power"}, {"q": "The sum to infinity of the GP 6, 2, 0.67, … is:", "options": ["4.5", "9", "18", "9 × 2"], "answer": 1, "explanation": "S∞ = a/(1 − r) with r = 1/3: 6/(1 − 1/3) = 9.", "topic": "Maths – Sequences & Series"}, {"q": "Sucrose on hydrolysis gives:", "options": ["glucose + galactose", "glucose + fructose", "fructose + fructose", "glucose + glucose"], "answer": 1, "explanation": "Sucrose (a disaccharide) hydrolyses to one glucose and one fructose.", "topic": "Chemistry – Organic Chemistry"}, {"q": "The domain of f(x) = 1/(x − 2) is:", "options": ["all real x except x = 2", "all real numbers", "x > 2", "x ≥ 2"], "answer": 0, "explanation": "The denominator vanishes at x = 2, so x = 2 is excluded.", "topic": "Maths – Sets & Functions"}, {"q": "The range of the data 12, 5, 19, 8, 3 is:", "options": ["14", "16", "22", "11"], "answer": 1, "explanation": "Range = maximum − minimum = 19 − 3 = 16.", "topic": "Maths – Statistics"}, {"q": "The moment of inertia of a solid disc of mass 1 kg and radius 1 m about its central axis is (MR²/2):", "options": ["0.5 kg·m² × 2", "0.25 kg·m²", "1 kg·m²", "0.5 kg·m²"], "answer": 3, "explanation": "I = MR²/2 = 11²/2 = 0.5 kg·m².", "topic": "Physics – Rotational Motion"}, {"q": "Iodoform test is positive for:", "options": ["HCHO", "C6H5COCH2CH3", "CH3CH2CHO", "CH3COCH3"], "answer": 3, "explanation": "Methyl ketones (CH3CO–) give CHI3 with I2/NaOH.", "topic": "Chemistry – Organic Chemistry"}, {"q": "The order of basicity in aqueous solution: NH3, CH3NH2, (CH3)2NH is:", "options": ["CH3NH2 > (CH3)2NH > NH3", "(CH3)2NH > CH3NH2 > NH3", "all equal", "NH3 > CH3NH2 > (CH3)2NH"], "answer": 1, "explanation": "+I effect of methyl groups increases basicity; solvation makes 2° > 1° in water.", "topic": "Chemistry – Organic Chemistry"}, {"q": "Chlorination of methane in sunlight proceeds via:", "options": ["free radical mechanism", "electrophilic substitution", "elimination", "nucleophilic substitution"], "answer": 0, "explanation": "hv generates Cl• radicals — a free-radical chain reaction.", "topic": "Chemistry – Organic Chemistry"}, {"q": "The number of angular nodes in a 3d orbital is:", "options": ["3", "1", "0", "2"], "answer": 3, "explanation": "Angular nodes = l = 2 for a d orbital.", "topic": "Chemistry – Atomic Structure"}, {"q": "For a cell with E° = 0.8 V, n = 1 and reaction quotient Q = 0.1, the cell emf at 298 K is:", "options": ["0.74 V", "0.43 V", "0.8 V", "0.86 V"], "answer": 3, "explanation": "Nernst: E = E° − (0.0591/n)logQ = 0.8 − (0.0591/1)log(0.1) = 0.86 V.", "topic": "Chemistry – Electrochemistry"}, {"q": "The IUPAC name of [Co(NH3)5Cl]Cl2 is:", "options": ["amminechloridocobalt(III) chloride", "pentaamminechloridocobalt(III) chloride", "pentaamminechloridocobalt(II) dichloride", "chloridopentaamminecobalt(II) chloride"], "answer": 1, "explanation": "5 NH3 (ammine) + 1 Cl (chlorido); Co oxidation state +3; two chloride counter ions.", "topic": "Chemistry – Coordination Compounds"}, {"q": "Mass of copper deposited by 2 A for 30 min (Cu²⁺ + 2e⁻ → Cu, M = 63.5) is:", "options": ["0.04 g", "1.18 g", "0.59 g", "2.37 g"], "answer": 1, "explanation": "m = ItM/(nF) = 2×1800×63.5/(2×96500) = 1.18 g.", "topic": "Chemistry – Electrochemistry"}, {"q": "The moment of inertia of a thin ring of mass 1 kg and radius 1 m about its central axis is (MR²):", "options": ["1 kg·m² × 2", "0.5 kg·m²", "1 kg·m²", "2 kg·m²"], "answer": 2, "explanation": "I = MR² = 11² = 1 kg·m².", "topic": "Physics – Rotational Motion"}, {"q": "The number of molecules in 1 mol of CO2 is:", "options": ["602200000000000027262976 atoms", "6.022×10²³", "1×6.022×10²³", "1×6.022×10²²"], "answer": 2, "explanation": "Molecules = n × NA = 1 × 6.022×10²³.", "topic": "Chemistry – Mole Concept"}, {"q": "The electric field at any point inside a hollow charged spherical conductor is:", "options": ["maximum", "zero", "uniform but non-zero", "infinite"], "answer": 1, "explanation": "In electrostatic equilibrium, the field inside a hollow conductor is zero.", "topic": "Physics – Electrostatics"}, {"q": "A radioactive sample has half-life 2 h. The fraction remaining after 4 h is:", "options": ["0.25", "0.5", "0.12", "1.25"], "answer": 0, "explanation": "Fraction = (1/2)^(t/T) = (1/2)^2 = 0.25.", "topic": "Physics – Modern Physics (numerical)"}, {"q": "The time period of a spring–mass system is T. If the attached mass is quadrupled (spring unchanged), the new time period is:", "options": ["2T", "4T", "T/2", "T"], "answer": 0, "explanation": "T = 2π√(m/k) ∝ √m, so 4× mass gives 2× period.", "topic": "Physics – Oscillations"}, {"q": "Using the standard limit lim(x→0) (e^x − 1)/x = 1, the value of lim(x→0) (e^(2x) − 1)/x is:", "options": ["2", "1", "1/2", "0"], "answer": 0, "explanation": "(e^(2x) − 1)/x = 2·(e^(2x) − 1)/(2x) → 2 × 1 = 2.", "topic": "Maths – Limits"}, {"q": "The distance of the point (3, 4, 12) from the origin is:", "options": ["13", "19", "√29", "7"], "answer": 0, "explanation": "d = √(3² + 4² + 12²) = √169 = 13.", "topic": "Maths – 3D Geometry"}, {"q": "The number of ways to arrange 5 distinct books in a row on a shelf is:", "options": ["25", "120", "60", "24"], "answer": 1, "explanation": "Arrangements of 5 distinct objects = 5! = 120.", "topic": "Maths – Permutations & Combinations"}, {"q": "The function f(x) = 2x + 3 is:", "options": ["bijective", "neither", "injective only", "surjective only"], "answer": 0, "explanation": "Linear with nonzero slope: one-one and onto over ℝ → bijective.", "topic": "Maths – Sets & Functions"}, {"q": "A card is drawn from a standard deck. The probability it is an ace is:", "options": ["4/13", "1/4", "1/13", "1/52"], "answer": 2, "explanation": "4 aces in 52 cards: 4/52 = 1/13.", "topic": "Maths – Probability"}, {"q": "The freezing point depression of a 2 molal aqueous solution of urea (van't Hoff factor i = 1, Kf = 1.86 K·kg/mol) is:", "options": ["7.44 K", "3.72 K × 2", "3.72 K", "1.86 K"], "answer": 2, "explanation": "ΔTf = i·Kf·m = 1×1.86×2 = 3.72 K.", "topic": "Chemistry – Solutions"}, {"q": "A transformer has 200 primary and 100 secondary turns. With 110 V applied to the primary, the secondary voltage is:", "options": ["27.5 V", "220 V", "110 V", "55 V"], "answer": 3, "explanation": "V₂/V₁ = N₂/N₁ ⇒ V₂ = 110×100/200 = 55 V.", "topic": "Physics – EMI & AC"}, {"q": "The centre of the ellipse 4x² + 9y² = 36 is:", "options": ["(1, 1)", "(0, 0)", "(4, 9)", "(2, 3)"], "answer": 1, "explanation": "Dividing by 36: x²/9 + y²/4 = 1, centred at the origin.", "topic": "Maths – Conic Sections"}, {"q": "For any cyclic process, the net change in internal energy is:", "options": ["equal to the work done", "zero", "equal to the heat absorbed", "infinite"], "answer": 1, "explanation": "Internal energy is a state function; over a closed cycle it returns to its initial value.", "topic": "Physics – Thermodynamics"}, {"q": "The molarity of a solution containing 4 g of NaOH (molar mass 40 g/mol) in 250 mL of solution is:", "options": ["0.4 M", "0.1 M", "1 M", "0.04 M"], "answer": 0, "explanation": "Moles = 4/40 = 0.1; molarity = 0.1/0.25 = 0.4 M.", "topic": "Chemistry – Solutions"}, {"q": "The sum of the first 20 terms of the AP 3, 5, … is:", "options": ["220", "480", "440", "880"], "answer": 2, "explanation": "Sₙ = n/2×[2a + (n−1)d] = 20/2×[6 + 19×2] = 440.", "topic": "Maths – Sequences & Series"}, {"q": "When a magnet is moved towards a coil, the direction of the induced current is given by:", "options": ["Faraday's law", "Lenz's law", "Ampere's law", "Biot–Savart law"], "answer": 1, "explanation": "Lenz's law gives the direction (opposing the change); Faraday's law gives the magnitude.", "topic": "Physics – EMI & AC"}, {"q": "Light of photon energy 4 eV falls on a metal of work function 2 eV. The maximum kinetic energy of emitted electrons is:", "options": ["-2 eV", "8 eV", "6 eV", "2 eV"], "answer": 3, "explanation": "K_max = hν − φ = 4 − 2 = 2 eV.", "topic": "Physics – Modern Physics"}, {"q": "The limit of sin(x)/x as x → 0 is:", "options": ["does not exist", "∞", "0", "1"], "answer": 3, "explanation": "Standard limit: lim(x→0) sin x/x = 1.", "topic": "Maths – Limits"}, {"q": "The mass of glucose (molar mass 180 g/mol) needed to prepare 500 mL of 0.2 M solution is:", "options": ["18 g", "9 g", "36 g", "1.8 g"], "answer": 0, "explanation": "Moles needed = 0.5 × 0.2 = 0.1; mass = 0.1 × 180 = 18 g.", "topic": "Chemistry – Solutions"}, {"q": "The inert pair effect is most prominent in:", "options": ["Si", "C", "Pb", "Ge"], "answer": 2, "explanation": "In group 14, the ns² electrons become increasingly inert down the group; Pb(II) is very stable.", "topic": "Chemistry – s, p, d & f Block"}, {"q": "For the quadratic equation 2x² − 7x + 3 = 0, the sum of the roots is:", "options": ["7/2", "−7/2", "3/2", "7"], "answer": 0, "explanation": "Sum of roots = −b/a = 7/2.", "topic": "Maths – Quadratic Equations"}, {"q": "Two resistors of 4 Ω each are joined in parallel. The equivalent resistance is:", "options": ["4 Ω", "6 Ω", "8 Ω", "2 Ω"], "answer": 3, "explanation": "Parallel: 1/R = 1/4 + 1/4 ⇒ R = 2 Ω.", "topic": "Physics – Current Electricity"}, {"q": "Tollens' reagent gives a silver mirror with:", "options": ["alcohols", "carboxylic acids", "aldehydes", "ketones"], "answer": 2, "explanation": "Tollens' oxidises aldehydes (not ketones) to carboxylates, depositing Ag.", "topic": "Chemistry – Organic Chemistry"}, {"q": "The shape of NH3 is:", "options": ["linear", "tetrahedral", "planar", "pyramidal"], "answer": 3, "explanation": "NH3 has 3 bond pairs + 1 lone pair → trigonal pyramidal.", "topic": "Chemistry – Chemical Bonding"}, {"q": "Mass of aluminium deposited by 3 A for 30 min (Al³⁺ + 3e⁻ → Al, M = 27) is:", "options": ["1.01 g", "0.25 g", "0.5 g", "0.06 g"], "answer": 2, "explanation": "m = ItM/(nF) = 3×1800×27/(3×96500) = 0.5 g.", "topic": "Chemistry – Electrochemistry"}, {"q": "A 10 kg block is pulled by a 50 N horizontal force on a smooth surface. Its acceleration is:", "options": ["5 m/s²", "2 m/s²", "10 m/s²", "0.5 m/s²"], "answer": 0, "explanation": "a = F/m = 50/10 = 5 m/s².", "topic": "Physics – Laws of Motion"}, {"q": "Hybridization of the carbonyl carbon in aldehydes is:", "options": ["sp³", "dsp²", "sp²", "sp"], "answer": 2, "explanation": "C=O carbon has 3 sigma bonds → trigonal planar, sp².", "topic": "Chemistry – Organic Chemistry"}, {"q": "If A = [[1, 2], [3, 4]] and B = [[5, 6], [7, 8]], then the (1, 2)-entry of the product AB is:", "options": ["19", "22", "43", "50"], "answer": 1, "explanation": "(AB)₁₂ = 1×6 + 2×8 = 6 + 16 = 22.", "topic": "Maths – Matrices & Determinants (numerical)"}, {"q": "The oxidation number of S in H2SO4 is:", "options": ["+6", "+4", "+8", "+2"], "answer": 0, "explanation": "2(+1) + x + 4(−2) = 0 ⇒ x = +6.", "topic": "Chemistry – Redox Reactions"}, {"q": "The density of O2 at STP (M = 32 g/mol) is approximately:", "options": ["1.43 g/L × 2", "2.86 g/L", "0.71 g/L", "1.43 g/L"], "answer": 3, "explanation": "d = PM/(RT) = 1×32/(0.0821×273) = 1.43 g/L.", "topic": "Chemistry – Gaseous State"}, {"q": "A circular loop of radius 0.1 m carries a current of 2 A. The magnetic field at its centre is approximately:", "options": ["12.6 μT", "6.3 μT", "25.1 μT", "1.26 μT"], "answer": 0, "explanation": "B = μ₀I/2r = (4π×10⁻⁷ × 2)/0.2 ≈ 12.6 μT.", "topic": "Physics – Magnetism"}, {"q": "The number of moles present in 88 g of CO₂ (molar mass 44 g/mol) is:", "options": ["1", "2", "4", "0.5"], "answer": 1, "explanation": "n = 88/44 = 2 mol.", "topic": "Chemistry – Mole Concept"}, {"q": "The number of atoms per unit cell in a hexagonal close packing (HCP) lattice is:", "options": ["4", "6", "2", "1"], "answer": 1, "explanation": "12 corners × 1/6 + 2 face centres × 1/2 + 3 interior = 6 atoms.", "topic": "Chemistry – Solid State"}, {"q": "A parallel-plate capacitor has plate area 0.01 m² and plate separation 1 mm. Its capacitance is (ε₀ = 8.85×10⁻¹² F/m):", "options": ["88.5 pF", "8.85 pF", "885 pF", "0.885 pF"], "answer": 0, "explanation": "C = ε₀A/d = 8.85×10⁻¹² × 0.01/0.001 = 8.85×10⁻¹¹ F = 88.5 pF.", "topic": "Physics – Capacitors"}, {"q": "The average value of f(x) = x² + 1 on the interval [0, 2] is:", "options": ["7/3", "8/3", "5/3", "7/2"], "answer": 0, "explanation": "Average = (1/2)∫₀² (x² + 1) dx = (1/2)[x³/3 + x]₀² = (1/2)(8/3 + 2) = 7/3.", "topic": "Maths – Definite Integrals"}, {"q": "An electric dipole placed in a uniform electric field experiences:", "options": ["only a net force", "only a torque", "both a net force and a torque", "neither force nor torque"], "answer": 1, "explanation": "The net force is zero but the two charges form a couple, giving a torque p × E.", "topic": "Physics – Electrostatics"}, {"q": "Two long parallel wires 0.1 m apart carry 2 A each in the same direction. The force per unit length between them is:", "options": ["8×10⁻⁶ N/m, attractive", "8×10⁻⁶ N/m, repulsive", "4×10⁻⁶ N/m, attractive", "2×10⁻⁶ N/m, repulsive"], "answer": 0, "explanation": "F/l = μ₀I₁I₂/2πr = 8×10⁻⁶ N/m; parallel currents attract.", "topic": "Physics – Magnetism"}, {"q": "For the melting of ice at 273 K, ΔH and ΔS are both positive. At 260 K, ΔG for melting is:", "options": ["negative", "zero", "positive", "infinite"], "answer": 2, "explanation": "ΔG = ΔH − TΔS = 0 at 273 K; below that, TΔS < ΔH so ΔG > 0 and melting is non-spontaneous.", "topic": "Chemistry – Thermodynamics"}, {"q": "The 3rd term of an AP is 11 and the 7th term is 27. The common difference is:", "options": ["3", "4", "5", "16"], "answer": 1, "explanation": "a + 6d − (a + 2d) = 4d = 27 − 11 = 16, so d = 4.", "topic": "Maths – Sequences & Series"}, {"q": "If a = (1, 2, 3) and b = (4, 5, 6), then the scalar product a · b equals:", "options": ["32", "28", "36", "30"], "answer": 0, "explanation": "a · b = 1×4 + 2×5 + 3×6 = 4 + 10 + 18 = 32.", "topic": "Maths – Vectors"}, {"q": "The number of ways to arrange the letters of the word LEVEL is:", "options": ["60", "30", "20", "120"], "answer": 1, "explanation": "5 letters with L twice and E twice: 5!/(2!×2!) = 30.", "topic": "Maths – Permutations & Combinations"}, {"q": "Which hydride is ionic?", "options": ["H2O", "NaH", "NH3", "CH4"], "answer": 1, "explanation": "Alkali metals form ionic (saline) hydrides like NaH.", "topic": "Chemistry – s, p, d & f Block"}, {"q": "A reaction has ΔG° = −30 kJ/mol at 300 K. Its equilibrium constant K is approximately (R = 8.314 J/mol·K):", "options": ["1.7×10⁵", "1.2×10⁻⁵", "12", "3.6×10³"], "answer": 0, "explanation": "K = e^(−ΔG°/RT) = e^(30000/(8.314×300)) = e^12.03 ≈ 1.7×10⁵.", "topic": "Chemistry – Thermodynamics"}, {"q": "The number of atoms per unit cell in a simple cubic lattice is:", "options": ["2", "1", "6", "4"], "answer": 1, "explanation": "8 corners × 1/8 = 1 atom.", "topic": "Chemistry – Solid State"}, {"q": "A stone tied to a 1 m string is whirled at 2 revolutions per second. Its speed is approximately:", "options": ["12.6 m/s", "6.3 m/s", "2 m/s", "4 m/s"], "answer": 0, "explanation": "v = 2πr/T = 2π × 1 × 2 = 4π ≈ 12.6 m/s.", "topic": "Physics – Circular Motion"}, {"q": "Which of the following is the dimensional formula of energy is?", "options": ["[ML²T⁻¹]", "[ML²T⁻²]", "[MLT⁻²]", "[ML³T⁻²]"], "answer": 1, "explanation": "Work = force × distance gives [MLT⁻²][L] = [ML²T⁻²].", "topic": "Physics – Units & Dimensions"}, {"q": "The limit of (1 − cos x)/x² as x → 0 is:", "options": ["1/2", "1", "0", "2"], "answer": 0, "explanation": "1 − cos x ≈ x²/2 for small x, so the limit is 1/2.", "topic": "Maths – Limits"}, {"q": "A solenoid with 500 turns per metre carries a current of 2 A. The magnetic field inside it is approximately:", "options": ["1.26 mT", "0.63 mT", "2.51 mT", "12.6 mT"], "answer": 0, "explanation": "B = μ₀nI = 4π×10⁻⁷ × 500 × 2 ≈ 1.26×10⁻³ T.", "topic": "Physics – Magnetism"}, {"q": "A wire experiences a stress of 2×10⁸ N/m² and a strain of 0. Its Young's modulus is:", "options": ["200 GPa", "0.2 GPa", "400 GPa", "100 GPa"], "answer": 0, "explanation": "Y = stress/strain = 200000000/0 = 200000000000 Pa = 200 GPa.", "topic": "Physics – Elasticity"}, {"q": "The dimensional formula of Young's modulus is:", "options": ["[ML⁻¹T⁻²]", "[MLT⁻²]", "[ML²T⁻²]", "[MT⁻²]"], "answer": 0, "explanation": "Modulus has the dimensions of stress: force/area = [MLT⁻²]/[L²] = [ML⁻¹T⁻²].", "topic": "Physics – Elasticity"}, {"q": "Using average bond enthalpies, formation of H2 from 2H atoms is:", "options": ["endothermic (ΔH positive)", "exothermic (ΔH negative)", "athermic", "impossible to predict"], "answer": 1, "explanation": "Bond formation releases energy: ΔH = −(bond enthalpy of H–H) < 0.", "topic": "Chemistry – Thermodynamics"}, {"q": "Aldol condensation of acetaldehyde gives:", "options": ["2-butanol", "crotonaldehyde directly", "butanal", "3-hydroxybutanal"], "answer": 3, "explanation": "Two ethanal molecules form 3-hydroxybutanal (aldol), which can dehydrate to crotonaldehyde.", "topic": "Chemistry – Organic Chemistry"}, {"q": "The oxidation state of Fe in K4[Fe(CN)6] is:", "options": ["+4", "0", "+2", "+3"], "answer": 2, "explanation": "4(+1) + x + 6(−1) = 0 ⇒ x = +2.", "topic": "Chemistry – Coordination Compounds"}, {"q": "Second ionization energy is exceptionally high for:", "options": ["Si", "Al", "Na", "Mg"], "answer": 2, "explanation": "Removing a second electron from Na breaks into the stable noble-gas core (Na⁺ is [Ne]).", "topic": "Chemistry – Periodic Table"}, {"q": "If the mean of the four observations 5, 7, x, 11 is 8, then x equals:", "options": ["6", "9", "10", "8"], "answer": 1, "explanation": "(5 + 7 + x + 11)/4 = 8 gives 23 + x = 32, so x = 9.", "topic": "Maths – Statistics"}, {"q": "A particle executing SHM has a maximum speed of 0.4 m/s and a maximum acceleration of 8 m/s². Its angular frequency is:", "options": ["20 rad/s", "5 rad/s", "0.05 rad/s", "3.2 rad/s"], "answer": 0, "explanation": "v_max = Aω and a_max = Aω², so ω = a_max/v_max = 8/0.4 = 20 rad/s.", "topic": "Physics – Oscillations"}, {"q": "The common difference of the arithmetic progression 7, 3, −1, … is:", "options": ["4", "−4", "10", "−10"], "answer": 1, "explanation": "d = 3 − 7 = −4.", "topic": "Maths – Sequences & Series"}, {"q": "If |a| = 3, |b| = 4 and a·b = 6, the angle between vectors a and b is:", "options": ["30°", "45°", "60°", "90°"], "answer": 2, "explanation": "cos θ = (a·b)/(|a||b|) = 6/12 = 1/2, so θ = 60°.", "topic": "Maths – Vectors"}, {"q": "For the decomposition 2H₂O₂(l) → 2H₂O(l) + O₂(g), the sign of ΔS is:", "options": ["negative", "zero", "positive", "cannot be determined"], "answer": 2, "explanation": "A gas is produced from liquids, increasing disorder, so ΔS > 0.", "topic": "Chemistry – Thermodynamics"}, {"q": "A 2 kg block slides down a smooth incline of vertical height 5 m. Its speed at the bottom is (g = 10 m/s²):", "options": ["10 m/s", "5 m/s", "20 m/s", "7.07 m/s"], "answer": 0, "explanation": "Loss of potential energy = gain of KE: v = √(2gh) = √100 = 10 m/s.", "topic": "Physics – Work, Energy & Power"}, {"q": "The projection of the vector (3, 4) onto the x-axis (vector (1, 0)) is:", "options": ["(3, 0)", "(0, 4)", "(3, 4)", "(1, 0)"], "answer": 0, "explanation": "The x-component is 3, so the projection is (3, 0).", "topic": "Maths – Vectors"}, {"q": "At STP, the volume occupied by 0.5 mol of an ideal gas is:", "options": ["11.2 L", "22.4 L", "5.6 L", "2.24 L"], "answer": 0, "explanation": "1 mol occupies 22.4 L at STP, so 0.5 mol occupies 11.2 L.", "topic": "Chemistry – Gaseous State"}, {"q": "If the absolute temperature of a gas is increased 2-fold, its rms molecular speed becomes:", "options": ["√2 times", "2 times", "unchanged", "2² times"], "answer": 0, "explanation": "v_rms = √(3RT/M) ∝ √T ⇒ increases by √2.", "topic": "Physics – Kinetic Theory"}, {"q": "A 5 kg body is released from rest at a height of 20 m (g = 10 m/s²). Its kinetic energy just before hitting the ground is:", "options": ["1000 J", "100 J", "2000 J", "500 J"], "answer": 0, "explanation": "KE = loss in PE = mgh = 5 × 10 × 20 = 1000 J.", "topic": "Physics – Work, Energy & Power"}, {"q": "Using integration by parts, ∫ x·eˣ dx equals:", "options": ["eˣ(x − 1) + C", "xeˣ + eˣ + C", "eˣ(x + 1) + C", "x²eˣ/2 + C"], "answer": 0, "explanation": "Take u = x, dv = eˣ dx: ∫x·eˣ dx = xeˣ − ∫eˣ dx = xeˣ − eˣ + C = eˣ(x − 1) + C.", "topic": "Maths – Indefinite Integrals"}, {"q": "An electron (charge 1.6×10⁻¹⁹ C) enters a magnetic field of 1 T perpendicularly with speed 1×10⁶ m/s. The magnetic force on it is:", "options": ["0 N × 3", "0 N", "0 N × 2", "0 N × 4"], "answer": 1, "explanation": "F = qvB sin90° = 1.6×10⁻¹⁹×1×10⁶×1 = 0 N.", "topic": "Physics – Magnetism"}, {"q": "Which of the following is the dimensional formula of angular momentum is?", "options": ["[ML³T⁻¹]", "[ML²T⁻²]", "[MLT⁻¹]", "[ML²T⁻¹]"], "answer": 3, "explanation": "L = r × p gives [L][MLT⁻¹] = [ML²T⁻¹].", "topic": "Physics – Units & Dimensions"}, {"q": "A variable force F(x) = 6x newtons acts along the x-axis. The work done in moving a body from x = 1 m to x = 3 m is:", "options": ["12 J", "24 J", "18 J", "27 J"], "answer": 1, "explanation": "W = ∫₁³ 6x dx = [3x²]₁³ = 27 − 3 = 24 J.", "topic": "Maths – Definite Integrals"}, {"q": "Using Cramer's rule on the system x + 2y = 5 and 3x + y = 4, the value of x is:", "options": ["3/5", "−3/5", "1", "2"], "answer": 0, "explanation": "D = 1×1 − 2×3 = −5, Dx = 5×1 − 2×4 = −3, so x = Dx/D = 3/5.", "topic": "Maths – Matrices & Determinants"}, {"q": "The electric potential at a point 0.2 m from a point charge of 4 μC is (k = 9×10⁹ N·m²/C²):", "options": ["1.8×10⁵ V", "9×10⁴ V", "3.6×10⁵ V", "1.8×10⁴ V"], "answer": 0, "explanation": "V = kq/r = 9×10⁹ × 4×10⁻⁶/0.2 = 1.8×10⁵ V.", "topic": "Physics – Electrostatics"}, {"q": "The number of moles in 40 g of NaOH (molar mass 40 g/mol) is:", "options": ["0.5 mol", "1600 mol", "1 mol", "2 mol"], "answer": 2, "explanation": "n = mass/molar mass = 40/40 = 1 mol.", "topic": "Chemistry – Mole Concept"}, {"q": "A student scores 80 with weight 2, 70 with weight 3 and 90 with weight 5. The weighted mean is:", "options": ["80", "82", "85", "78"], "answer": 1, "explanation": "(80×2 + 70×3 + 90×5)/(2 + 3 + 5) = 820/10 = 82.", "topic": "Maths – Statistics"}, {"q": "The eccentricity of a hyperbola is always:", "options": ["equal to 0", "greater than 1", "equal to 1", "less than 1"], "answer": 1, "explanation": "For hyperbolas e > 1 (e = 1 is a parabola, e < 1 an ellipse).", "topic": "Maths – Conic Sections"}, {"q": "A 2 kg object moving at 10 m/s is brought to rest by a constant force in 5 s. The magnitude of the force is:", "options": ["4 N", "10 N", "20 N", "2 N"], "answer": 0, "explanation": "F = mΔv/t = 2 × 10/5 = 4 N.", "topic": "Physics – Laws of Motion"}, {"q": "The number of radial nodes in a 3p orbital is:", "options": ["1", "2", "0", "3"], "answer": 0, "explanation": "Radial nodes = n − l − 1 = 3 − 1 − 1 = 1.", "topic": "Chemistry – Atomic Structure"}, {"q": "A Carnot engine operates between 600 K and 200 K. Its efficiency is:", "options": ["33.33%", "66.67% × 2", "-200%", "66.67%"], "answer": 3, "explanation": "η = 1 − T₂/T₁ = 1 − 200/600 = 66.67%.", "topic": "Physics – Thermodynamics"}, {"q": "The oxidation number of Cl in HClO4 is:", "options": ["+7", "−1", "+5", "+1"], "answer": 0, "explanation": "+1 + x + 4(−2) = 0 ⇒ x = +7.", "topic": "Chemistry – Redox Reactions"}, {"q": "The limit of eˣ as x → −∞ is:", "options": ["0", "1", "∞", "−∞"], "answer": 0, "explanation": "eˣ → 0 as x → −∞.", "topic": "Maths – Limits"}, {"q": "At the highest point of a projectile's trajectory, which of the following is true?", "options": ["velocity is zero", "acceleration is zero", "velocity is horizontal and acceleration is vertically downward", "both velocity and acceleration are horizontal"], "answer": 2, "explanation": "At the top, the vertical velocity component is zero but the horizontal component remains; acceleration is g downward throughout.", "topic": "Physics – Projectile Motion"}, {"q": "The maximum number of electrons that can be accommodated in the n = 3 shell is:", "options": ["8", "18", "32", "9"], "answer": 1, "explanation": "Maximum = 2n² = 18.", "topic": "Chemistry – Atomic Structure"}, {"q": "An engine exerts a constant force of 200 N to keep a vehicle moving at 10 m/s. The power delivered is:", "options": ["2000 W", "4000 W", "3000 W", "1000 W"], "answer": 0, "explanation": "P = F·v = 200×10 = 2000 W.", "topic": "Physics – Work, Energy & Power"}, {"q": "If z = 4 − 3i, then the product z·z̄ equals:", "options": ["7", "25", "−7", "1"], "answer": 1, "explanation": "z·z̄ = |z|² = 4² + 3² = 25.", "topic": "Maths – Complex Numbers"}, {"q": "The ratio of rates of effusion of H2 to CH4 is:", "options": ["0.35", "1.41", "2.83", "8"], "answer": 2, "explanation": "Graham's law: r₁/r₂ = √(M₂/M₁) = √(16/2) = 2.83.", "topic": "Chemistry – Gaseous State"}, {"q": "The ratio of rates of effusion of H2 to CO2 is:", "options": ["22", "2.35", "4.69", "0.21"], "answer": 2, "explanation": "Graham's law: r₁/r₂ = √(M₂/M₁) = √(44/2) = 4.69.", "topic": "Chemistry – Gaseous State"}, {"q": "In the reaction Zn + CuSO4 → ZnSO4 + Cu, the oxidising agent is:", "options": ["Zn", "ZnSO4", "Cu", "CuSO4"], "answer": 3, "explanation": "Cu²⁺ gains electrons (reduced to Cu), so CuSO4 is the oxidising agent.", "topic": "Chemistry – Redox Reactions"}, {"q": "A charged particle moves exactly parallel to a uniform magnetic field. The magnetic force on it is:", "options": ["qvB", "zero", "qvB/2", "2qvB"], "answer": 1, "explanation": "F = qvB sin θ with θ = 0°, so the force is zero.", "topic": "Physics – Magnetism"}, {"q": "For A + B ⇌ C at equilibrium, [A] = 1 M, [B] = 0.5 M, [C] = 1 M. Kc equals:", "options": ["2", "1", "4", "0.5"], "answer": 0, "explanation": "Kc = [C]/([A][B]) = 1/(1×0.5) = 2.", "topic": "Chemistry – Equilibrium"}, {"q": "The density of an ideal gas at 2 atm and 300 K with molar mass 40 g/mol is (R = 0.0821 L·atm/mol·K):", "options": ["3.25 g/L", "1.62 g/L", "6.5 g/L", "0.325 g/L"], "answer": 0, "explanation": "d = PM/RT = (2 × 40)/(0.0821 × 300) ≈ 3.25 g/L.", "topic": "Chemistry – Gaseous State"}, {"q": "The spin-only magnetic moment of [Mn(H2O)6]²⁺ (in BM) is:", "options": ["1.73", "4.90", "3.87", "5.92"], "answer": 3, "explanation": "High-spin d⁵: n = 5 ⇒ μ = √(5×7) = √35 ≈ 5.92 BM.", "topic": "Chemistry – Coordination Compounds"}, {"q": "[Ni(CO)4] has tetrahedral geometry and Ni is in oxidation state:", "options": ["0", "−2", "+4", "+2"], "answer": 0, "explanation": "CO is neutral ⇒ Ni(0), d¹⁰, tetrahedral, diamagnetic.", "topic": "Chemistry – Coordination Compounds"}, {"q": "If det A = 3 and det B = −2 for square matrices A and B, then det(AB) equals:", "options": ["1", "−6", "6", "5"], "answer": 1, "explanation": "det(AB) = (det A)(det B) = 3 × (−2) = −6.", "topic": "Maths – Matrices & Determinants"}, {"q": "Which species acts as both oxidising and reducing agent?", "options": ["K2Cr2O7", "H2O2", "KMnO4", "O3"], "answer": 1, "explanation": "O in H2O2 is −1, midway between 0 and −2, so it can be oxidised or reduced.", "topic": "Chemistry – Redox Reactions"}, {"q": "Which set of quantum numbers is NOT allowed?", "options": ["n = 1, l = 0, m = 0", "n = 2, l = 1, m = 0", "n = 3, l = 2, m = −2", "n = 2, l = 2, m = 0"], "answer": 3, "explanation": "l must be less than n; l = 2 is not allowed when n = 2.", "topic": "Chemistry – Atomic Structure"}, {"q": "The pH of a 0.01 M NaOH solution is:", "options": ["16", "2", "3", "12"], "answer": 3, "explanation": "[OH⁻] = 0.01 M ⇒ pOH = 2 ⇒ pH = 14 − 2 = 12.", "topic": "Chemistry – Equilibrium"}, {"q": "If z = 1 + i, then arg(z²) equals:", "options": ["π/4", "π/2", "π", "0"], "answer": 1, "explanation": "z² = (1 + i)² = 2i, which lies on the positive imaginary axis, so arg(z²) = π/2.", "topic": "Maths – Complex Numbers"}, {"q": "The time period of a conical pendulum depends on:", "options": ["the mass of the bob only", "the length and the acceleration due to gravity", "the amplitude only", "the tension only"], "answer": 1, "explanation": "T = 2π√(l cos θ/g); it depends on length l, angle θ and g, not on the mass.", "topic": "Physics – Circular Motion"}, {"q": "If A = {1, 2, 3}, the number of subsets of A is:", "options": ["8", "9", "6", "7"], "answer": 0, "explanation": "An n-element set has 2ⁿ subsets: 2³ = 8.", "topic": "Maths – Sets & Functions"}, {"q": "The limit of (e^x − 1)/x as x → 0 is:", "options": ["0", "∞", "1", "e"], "answer": 2, "explanation": "Standard limit: lim(x→0)(e^x − 1)/x = 1.", "topic": "Maths – Limits"}, {"q": "The moment of inertia of a solid sphere of mass 3 kg and radius 1 m about its central axis is (2MR²/5):", "options": ["0.6 kg·m²", "3 kg·m²", "2.4 kg·m²", "1.2 kg·m²"], "answer": 3, "explanation": "I = 2MR²/5 = 231²/5 = 1.2 kg·m².", "topic": "Physics – Rotational Motion"}, {"q": "The minimum value of y = x² − 6x + 5 is:", "options": ["−4", "4", "5", "−5"], "answer": 0, "explanation": "y = (x − 3)² − 4, minimum −4 at x = 3.", "topic": "Maths – Applications of Derivatives"}, {"q": "One mole of a monatomic ideal gas is heated at constant volume from 300 K to 400 K. The heat absorbed is (Cv = 3R/2, R = 8.314 J/mol·K):", "options": ["1247 J", "831 J", "2078 J", "4157 J"], "answer": 0, "explanation": "Q = nCvΔT = 1 × (3/2)(8.314) × 100 = 1247 J.", "topic": "Physics – Thermodynamics"}, {"q": "A 220 V, 968 W-rated bulb has resistance 50 Ω. The power it consumes at 220 V is:", "options": ["968 W", "1936 W", "484 W", "968 W × 2"], "answer": 0, "explanation": "P = V²/R = 220²/50 = 968 W.", "topic": "Physics – Current Electricity"}, {"q": "The sum of the first 5 terms of the GP 2, 6, 18, … is:", "options": ["242", "486", "162", "240"], "answer": 0, "explanation": "S₅ = 2(3⁵ − 1)/(3 − 1) = 2 × 242/2 = 242.", "topic": "Maths – Sequences & Series"}, {"q": "If A is a 3×3 matrix with det(A) = 2, then det(2A) equals:", "options": ["6", "4", "16", "8"], "answer": 2, "explanation": "det(kA) = kⁿ·det(A) for n×n A: 2³×2 = 16.", "topic": "Maths – Matrices & Determinants"}, {"q": "If a × b = 0 for two non-zero vectors a and b, then a and b are:", "options": ["perpendicular", "parallel", "equal", "both zero"], "answer": 1, "explanation": "|a × b| = |a||b| sin θ = 0 gives θ = 0° or 180°; the vectors are parallel.", "topic": "Maths – Vectors"}, {"q": "The moment of inertia of a hollow sphere of mass 2 kg and radius 2 m about its central axis is (2MR²/3):", "options": ["8 kg·m²", "5.33 kg·m²", "2.67 kg·m²", "10.67 kg·m²"], "answer": 1, "explanation": "I = 2MR²/3 = 222²/3 = 5.33 kg·m².", "topic": "Physics – Rotational Motion"}, {"q": "A constant force of 20 N acts on a 5 kg body initially at rest for 4 s. The kinetic energy gained by the body is:", "options": ["640 J", "320 J", "1280 J", "160 J"], "answer": 0, "explanation": "a = 4 m/s², v = 16 m/s, KE = ½ × 5 × 256 = 640 J.", "topic": "Physics – Work, Energy & Power"}, {"q": "A simple pendulum of length 0.25 m oscillates with small amplitude (g = 10 m/s²). Its time period is:", "options": ["0.5 s", "0.99 s", "1.4 s", "1.99 s"], "answer": 1, "explanation": "T = 2π√(l/g) = 2π√(0.25/10) = 0.99 s.", "topic": "Physics – Oscillations"}, {"q": "The sum of all binomial coefficients in (1 + x)^5 is:", "options": ["25", "10", "15", "32"], "answer": 3, "explanation": "Put x = 1: sum = (1+1)ⁿ = 2ⁿ = 32.", "topic": "Maths – Binomial Theorem"}, {"q": "The most abundant metal in Earth's crust is:", "options": ["Al", "Fe", "Ca", "Na"], "answer": 0, "explanation": "Aluminium (~8%) is the most abundant metal in the crust.", "topic": "Chemistry – s, p, d & f Block"}, {"q": "A spring of force constant k is cut into two equal halves. The force constant of each half is:", "options": ["k", "2k", "k/2", "4k"], "answer": 1, "explanation": "k ∝ 1/length; halving the length doubles the stiffness to 2k.", "topic": "Physics – Elasticity"}, {"q": "The wavelength of the photon emitted in the hydrogen transition n = 3 → 1 lies in the:", "options": ["ultraviolet region", "infrared region", "microwave region", "visible region"], "answer": 0, "explanation": "λ = 1240/ΔE nm ≈ 102.6 nm — the Lyman series.", "topic": "Chemistry – Atomic Structure"}, {"q": "The probability that a leap year has 53 Sundays is:", "options": ["1/7", "3/7", "2/7", "53/366"], "answer": 2, "explanation": "A leap year has 366 days = 52 weeks + 2 extra days; P(both extra days include a Sunday) = 2/7.", "topic": "Maths – Probability"}, {"q": "In NaCl, each Na⁺ is surrounded by how many Cl⁻ ions?", "options": ["8", "6", "4", "12"], "answer": 1, "explanation": "Rock-salt structure: octahedral coordination, each ion has 6 nearest neighbours.", "topic": "Chemistry – Solid State"}, {"q": "An AC mains supply is rated 220 V rms. Its peak voltage is approximately:", "options": ["220 V", "311 V", "155 V", "440 V"], "answer": 1, "explanation": "V_peak = √2 × V_rms = 1.414 × 220 ≈ 311 V.", "topic": "Physics – EMI & AC"}, {"q": "The most electronegative element is:", "options": ["O", "F", "N", "Cl"], "answer": 1, "explanation": "Electronegativity increases across a period and decreases down a group; F tops the scale at 4.0.", "topic": "Chemistry – Periodic Table"}, {"q": "First ionization energy is generally highest for:", "options": ["K", "He", "Li", "Na"], "answer": 1, "explanation": "Ionization energy decreases down a group and increases across a period; He (noble gas, small) is highest among these.", "topic": "Chemistry – Periodic Table"}, {"q": "For the set B = {a, e, i, o, u}, the number of proper subsets is:", "options": ["31", "32", "30", "25"], "answer": 0, "explanation": "Total subsets = 2⁵ = 32; proper subsets exclude B itself: 31.", "topic": "Maths – Sets & Functions"}, {"q": "For a normal distribution, mean = median = mode is located at the:", "options": ["cannot be determined", "right tail", "centre of symmetry", "left tail"], "answer": 2, "explanation": "A normal curve is symmetric; mean = median = mode at the centre.", "topic": "Maths – Statistics"}, {"q": "The standard hydrogen electrode (SHE) is assigned an electrode potential of:", "options": ["1 V", "0 V", "−1 V", "0.76 V"], "answer": 1, "explanation": "By convention, E°(SHE) = 0 V at all temperatures.", "topic": "Chemistry – Electrochemistry"}, {"q": "A first-order reaction has rate constant k = 0.0693 min⁻¹. The time required for 75% completion is:", "options": ["20 min", "10 min", "40 min", "13.86 min"], "answer": 0, "explanation": "t = (2.303/k)·log(100/25) = (2.303/0.0693)·log 4 ≈ 20 min.", "topic": "Chemistry – Chemical Kinetics (numerical)"}, {"q": "The coefficient of x³ in the expansion of (1 + x)^5 is:", "options": ["10", "5", "20", "15"], "answer": 0, "explanation": "The coefficient is C(5, 3) = 10.", "topic": "Maths – Binomial Theorem"}, {"q": "The hybridization of boron in BF3 is:", "options": ["sp", "sp³d", "sp²", "sp³"], "answer": 2, "explanation": "BF3 has 3 bond pairs, no lone pairs → trigonal planar, sp².", "topic": "Chemistry – Chemical Bonding"}, {"q": "A buffer has [salt]/[acid] = 2 and pKa = 9.25. Its pH is:", "options": ["8.55", "10.55", "9.25", "9.55"], "answer": 3, "explanation": "pH = pKa + log([salt]/[acid]) = 9.25 + log(2) = 9.55.", "topic": "Chemistry – Equilibrium"}, {"q": "If Earth's radius were 4 times larger with the same mass, surface gravity would be:", "options": ["g/16", "g/4", "g", "4g"], "answer": 0, "explanation": "g = GM/R² ∝ 1/R² ⇒ g' = g/4² = g/16.", "topic": "Physics – Gravitation"}, {"q": "A lift accelerates upward at 2 m/s². The apparent weight of a 50 kg person inside it is (g = 10 m/s²):", "options": ["600 N", "500 N", "400 N", "1000 N"], "answer": 0, "explanation": "N = m(g + a) = 50 × 12 = 600 N.", "topic": "Physics – Laws of Motion"}, {"q": "Two 2 μF capacitors are connected in parallel. The equivalent capacitance is:", "options": ["2 μF", "4 μF", "3 μF", "1 μF"], "answer": 1, "explanation": "Parallel: C = 2 + 2 = 4 μF.", "topic": "Physics – Capacitors"}, {"q": "If A is a 2×2 matrix with det A = 4, then det(A⁻¹) equals:", "options": ["4", "1/4", "−4", "2"], "answer": 1, "explanation": "det(A⁻¹) = 1/det A = 1/4.", "topic": "Maths – Matrices & Determinants"}, {"q": "The SI unit of dynamic viscosity is:", "options": ["Pa·s", "N/m", "kg/m²", "m²/s"], "answer": 0, "explanation": "Viscosity is measured in pascal-second (poiseuille).", "topic": "Physics – Fluid Mechanics"}, {"q": "A potentiometer is preferred over a voltmeter for measuring emf because:", "options": ["it draws no current from the cell", "it is more portable", "it has higher resistance", "it is cheaper"], "answer": 0, "explanation": "At null point no current flows through the cell, so it measures true emf, not terminal voltage.", "topic": "Physics – Current Electricity"}, {"q": "In a stationary wave, the distance between two consecutive nodes is:", "options": ["λ", "λ/2", "λ/4", "2λ"], "answer": 1, "explanation": "Nodes are spaced half a wavelength apart.", "topic": "Physics – Waves"}, {"q": "∫ e^x dx equals:", "options": ["e^x + C", "1 + C", "xe^x + C", "e^(2x)/2 + C"], "answer": 0, "explanation": "The exponential is its own antiderivative: ∫ e^x dx = e^x + C.", "topic": "Maths – Indefinite Integrals"}, {"q": "The trace of the matrix [[4, 7], [2, 5]] is:", "options": ["20", "9", "11", "13"], "answer": 1, "explanation": "Trace = sum of diagonal entries = 4 + 5 = 9.", "topic": "Maths – Matrices & Determinants (numerical)"}, {"q": "The value of ∫ 2x(x² + 1)³ dx is:", "options": ["(x² + 1)⁴/4 + C", "(x² + 1)³/3 + C", "2(x² + 1)⁴ + C", "(x² + 1)⁴ + C"], "answer": 0, "explanation": "Substituting u = x² + 1 gives ∫u³ du = u⁴/4 + C = (x² + 1)⁴/4 + C.", "topic": "Maths – Indefinite Integrals"}, {"q": "The molality of a solution containing 1 mol of solute dissolved in 500 g of solvent is:", "options": ["2 m", "0.5 m", "1 m", "5 m"], "answer": 0, "explanation": "Molality = moles of solute per kg of solvent = 1/0.5 = 2 m.", "topic": "Chemistry – Solutions"}, {"q": "∫₋ₐ^a x³ dx (a > 0) equals:", "options": ["a⁴/4", "2a⁴", "0", "a⁴/2"], "answer": 2, "explanation": "x³ is an odd function over a symmetric interval, so the integral is 0.", "topic": "Maths – Definite Integrals"}, {"q": "The equation of the circle with centre (2, −3) and radius 5 is:", "options": ["x² + y² − 4x + 6y − 12 = 0", "x² + y² + 4x − 6y − 12 = 0", "x² + y² − 4x + 6y + 38 = 0", "x² + y² − 2x + 3y − 12 = 0"], "answer": 0, "explanation": "(x − 2)² + (y + 3)² = 25 expands to x² + y² − 4x + 6y − 12 = 0.", "topic": "Maths – Circles"}, {"q": "Which of the following is the dimensional formula of surface tension is?", "options": ["[MT⁻²]", "[ML²T⁻²]", "[MLT⁻²]", "[MT⁻¹]"], "answer": 0, "explanation": "Surface tension = force/length gives [MLT⁻²]/[L] = [MT⁻²].", "topic": "Physics – Units & Dimensions"}, {"q": "The middle term in the expansion of (1 + x)^6 is:", "options": ["20x^3", "15x^3", "20x^4", "6x^3"], "answer": 0, "explanation": "n = 6 (even): middle term is T_(4) = C(6,3)x^3 = 20x^3.", "topic": "Maths – Binomial Theorem"}, {"q": "The sum of the first n natural numbers is:", "options": ["n(n + 1)/2", "n²", "n(n − 1)/2", "2n(n + 1)"], "answer": 0, "explanation": "1 + 2 + … + n = n(n + 1)/2.", "topic": "Maths – Sequences & Series"}, {"q": "The moment of inertia of a uniform rod about its centre of mass 2 kg and radius 1 m about its central axis is (ML²/12):", "options": ["0.17 kg·m²", "0.08 kg·m²", "2 kg·m²", "0.33 kg·m²"], "answer": 0, "explanation": "I = ML²/12 = 2L²/12 = 0.17 kg·m².", "topic": "Physics – Rotational Motion"}, {"q": "A car moving at 20 m/s brakes with deceleration μg where μ = 0.5 (g = 10 m/s²). The stopping distance is (in m):", "options": ["40 m", "80 m", "20 m", "41 m"], "answer": 0, "explanation": "v² = u² − 2as with a = μg: s = 20²/(2×0.5×10) = 40 m.", "topic": "Physics – Kinematics (numerical)"}, {"q": "Which has the largest atomic radius?", "options": ["Li", "Na", "K", "Cs"], "answer": 3, "explanation": "Atomic radius increases down a group; Cs is the largest of these alkali metals.", "topic": "Chemistry – Periodic Table"}, {"q": "According to Newton's third law, action and reaction forces act on:", "options": ["the same body", "different bodies", "only in static situations", "the centre of mass"], "answer": 1, "explanation": "Action and reaction are mutual forces between two interacting bodies, so they act on different bodies.", "topic": "Physics – Laws of Motion"}, {"q": "The energy of an electron in the n = 3 orbit of a hydrogen atom is:", "options": ["-1.51 eV", "-3.02 eV", "1.51 eV", "-0.76 eV"], "answer": 0, "explanation": "Eₙ = −13.6/n² = −13.6/3² = -1.51 eV.", "topic": "Physics – Modern Physics"}, {"q": "Two masses 2 kg and 3 kg are connected by a light string passing over a smooth pulley. The tension in the string is (g = 10 m/s²):", "options": ["24 N", "20 N", "30 N", "12 N"], "answer": 0, "explanation": "T = 2m₁m₂g/(m₁ + m₂) = 2×2×3×10/5 = 24 N.", "topic": "Physics – Laws of Motion"}, {"q": "For the reaction N₂ + 3H₂ ⇌ 2NH₃, the equilibrium constant Kc is expressed as:", "options": ["[NH₃]/([N₂][H₂])", "[NH₃]²/([N₂][H₂]³)", "[N₂][H₂]³/[NH₃]²", "[NH₃]²[N₂]/[H₂]³"], "answer": 1, "explanation": "Kc = [products]^coeff/[reactants]^coeff = [NH₃]²/([N₂][H₂]³).", "topic": "Chemistry – Equilibrium"}, {"q": "The critical angle for a glass–air interface with refractive index 1.5 is approximately:", "options": ["20.9°", "41.8°", "83.6°", "48.2°"], "answer": 1, "explanation": "sin C = 1/n = 1/1.5 ⇒ C ≈ 41.8°.", "topic": "Physics – Ray Optics"}, {"q": "The number of atoms per unit cell in a body-centred cubic (BCC) lattice is:", "options": ["2", "1", "4", "6"], "answer": 0, "explanation": "8 corners × 1/8 + 1 body centre = 2 atoms.", "topic": "Chemistry – Solid State"}, {"q": "The volume occupied by 1 mol of an ideal gas at 2 atm and 300 K is (R = 0.0821 L·atm/mol·K):", "options": ["6.16 L", "12.32 L", "24.63 L", "49.26 L"], "answer": 1, "explanation": "V = nRT/P = 1×0.0821×300/2 = 12.32 L.", "topic": "Chemistry – Gaseous State"}, {"q": "The terminal velocity of a small sphere falling in a viscous liquid is proportional to:", "options": ["independent of radius", "the cube of its radius", "the square of its radius", "its radius"], "answer": 2, "explanation": "Stokes' law: v_t = 2r²g(ρ − σ)/(9η) ∝ r².", "topic": "Physics – Fluid Mechanics"}, {"q": "The area of the parallelogram with adjacent sides a = (1, 0, 0) and b = (0, 2, 0) is:", "options": ["2", "1", "3", "0"], "answer": 0, "explanation": "Area = |a × b| = |(0, 0, 2)| = 2 square units.", "topic": "Maths – Vectors"}, {"q": "For a process with ΔH = 0, spontaneity is decided by:", "options": ["ΔS being positive", "the pressure", "the sign of ΔH", "temperature alone"], "answer": 0, "explanation": "With ΔH = 0, ΔG = −TΔS, so the process is spontaneous only if ΔS > 0.", "topic": "Chemistry – Thermodynamics"}, {"q": "If sin θ = 3/5 with θ acute, then tan θ equals:", "options": ["4/3", "3/4", "5/3", "5/4"], "answer": 1, "explanation": "cos θ = √(1 − 9/25) = 4/5, so tan θ = sin θ/cos θ = 3/4.", "topic": "Maths – Trigonometry"}, {"q": "SN1 reactivity order is:", "options": ["1° > 2° > 3°", "2° > 3° > 1°", "3° > 2° > 1°", "3° > 1° > 2°"], "answer": 2, "explanation": "SN1 rate depends on carbocation stability: 3° > 2° > 1°.", "topic": "Chemistry – Organic Chemistry"}, {"q": "The volume occupied by 1 mol of oxygen gas at STP is:", "options": ["22.4 L", "11.2 L", "44.8 L", "2.24 L"], "answer": 0, "explanation": "1 mol of any ideal gas occupies 22.4 L at STP.", "topic": "Chemistry – Mole Concept"}, {"q": "The angle between the vectors (1, 0, 0) and (0, 1, 0) is:", "options": ["0°", "45°", "90°", "180°"], "answer": 2, "explanation": "Their dot product is 0, so the vectors are perpendicular: 90°.", "topic": "Maths – Vectors"}, {"q": "The eccentricity of the ellipse x²/25 + y²/16 = 1 is:", "options": ["5/3", "4/5", "1/2", "3/5"], "answer": 3, "explanation": "a² = 25, b² = 16: e = √(1 − b²/a²) = √(1 − 16/25) = 3/5.", "topic": "Maths – Conic Sections"}, {"q": "A wire of resistance 12 Ω is cut into 3 equal parts. The resistance of each part is:", "options": ["4 Ω", "12 Ω", "36 Ω", "3 Ω"], "answer": 0, "explanation": "R ∝ length; each third has 12/3 = 4 Ω.", "topic": "Physics – Current Electricity"}, {"q": "If α and β are roots of x² − 7x + 8 = 0, then α² + β² equals:", "options": ["16", "65", "33", "41"], "answer": 2, "explanation": "α² + β² = (α+β)² − 2αβ = 7² − 2×8 = 33.", "topic": "Maths – Quadratic Equations"}, {"q": "The point dividing the join of (1, 2, 3) and (4, 5, 6) in the ratio 1 : 2 internally is:", "options": ["(2, 3, 4)", "(3, 4, 5)", "(1, 2, 3)", "(5/2, 7/2, 9/2)"], "answer": 0, "explanation": "Section formula: ((1×4 + 2×1)/3, (1×5 + 2×2)/3, (1×6 + 2×3)/3) = (2, 3, 4).", "topic": "Maths – 3D Geometry"}, {"q": "The (population) variance of the data 2, 4, 6 is:", "options": ["2", "8/3", "4", "3"], "answer": 1, "explanation": "Mean = 4. Variance = ((2−4)² + (4−4)² + (6−4)²)/3 = 8/3.", "topic": "Maths – Statistics"}, {"q": "The general solution of dy/dx = 2x is:", "options": ["y = 2x + C", "y = x² + C", "y = x²/2 + C", "y = 2"], "answer": 1, "explanation": "Integrate: y = ∫ 2x dx = x² + C.", "topic": "Maths – Differential Equations"}, {"q": "The oxidation number of Mn in KMnO4 is:", "options": ["+4", "+2", "+6", "+7"], "answer": 3, "explanation": "+1 + x + 4(−2) = 0 ⇒ x = +7.", "topic": "Chemistry – Redox Reactions"}, {"q": "The derivative of sin(4x) with respect to x is:", "options": ["4cos(4x)", "−4cos(4x)", "cos(4x)", "4sin(4x)"], "answer": 0, "explanation": "Chain rule: d/dx[sin(4x)] = 4cos(4x).", "topic": "Maths – Differentiation"}, {"q": "The density of N2 at STP (M = 28 g/mol) is approximately:", "options": ["0.62 g/L", "1.25 g/L", "2.5 g/L", "1.25 g/L × 2"], "answer": 1, "explanation": "d = PM/(RT) = 1×28/(0.0821×273) = 1.25 g/L.", "topic": "Chemistry – Gaseous State"}, {"q": "Compared to an electron moving with the same momentum, a proton's de Broglie wavelength is:", "options": ["1836 times larger", "1836 times smaller", "the same", "zero"], "answer": 2, "explanation": "λ = h/p depends only on momentum, which is the same for both.", "topic": "Physics – Modern Physics"}, {"q": "Mass of zinc deposited by 3 A for 96.5 min (Zn²⁺ + 2e⁻ → Zn, M = 65.4) is:", "options": ["11.77 g", "0.18 g", "5.89 g", "2.94 g"], "answer": 2, "explanation": "m = ItM/(nF) = 3×5790×65.4/(2×96500) = 5.89 g.", "topic": "Chemistry – Electrochemistry"}, {"q": "The general term (r + 1)th term in the binomial expansion of (1 + x)^n is:", "options": ["C(n, r)x^r", "C(n, r)x^(n−r)", "nCr", "x^n"], "answer": 0, "explanation": "T_(r+1) = C(n, r)·1^(n−r)·x^r = C(n, r)x^r.", "topic": "Maths – Binomial Theorem"}, {"q": "The threshold wavelength for photoelectric emission from a metal of work function 2 eV is (hc = 1240 eV·nm):", "options": ["620 nm", "310 nm", "1240 nm", "2480 nm"], "answer": 0, "explanation": "λ₀ = hc/φ = 1240/2 = 620 nm.", "topic": "Physics – Modern Physics"}, {"q": "The pH of a 0 M HCl solution is:", "options": ["2", "11", "4", "3"], "answer": 3, "explanation": "HCl is a strong acid: [H⁺] = 0 M ⇒ pH = −log0 = 3.", "topic": "Chemistry – Equilibrium"}, {"q": "Two capacitors of 4 μF and 6 μF are connected in series. The equivalent capacitance is:", "options": ["10 μF", "2.4 μF", "24 μF", "1 μF"], "answer": 1, "explanation": "1/C = 1/4 + 1/6 = 5/12, so C = 12/5 = 2.4 μF.", "topic": "Physics – Capacitors"}, {"q": "H2O has a bent shape due to:", "options": ["2 lone pairs on oxygen", "hydrogen bonding", "sp hybridization", "polar bonds only"], "answer": 0, "explanation": "Two lone pairs compress the tetrahedral angle to ~104.5°.", "topic": "Chemistry – Chemical Bonding"}, {"q": "Class A of 30 students has mean score 70 and class B of 20 students has mean score 80. The combined mean is:", "options": ["75", "74", "76", "73"], "answer": 1, "explanation": "Combined mean = (30×70 + 20×80)/50 = 3700/50 = 74.", "topic": "Maths – Statistics"}, {"q": "The power factor of a purely resistive AC circuit is:", "options": ["0", "1", "0.5", "infinite"], "answer": 1, "explanation": "Voltage and current are in phase, so cos φ = 1.", "topic": "Physics – EMI & AC"}, {"q": "The derivative of e^(2x) with respect to x is:", "options": ["e^(x)", "e^(2x)", "2e^(2x)", "2xe^(2x)"], "answer": 2, "explanation": "Chain rule: d/dx[e^(2x)] = 2e^(2x).", "topic": "Maths – Differentiation"}, {"q": "The value of the universal gas constant R in SI units is:", "options": ["8.314 J/mol·K", "0.0821 J/mol·K", "22.4 J/mol·K", "1.38×10⁻²³ J/mol·K"], "answer": 0, "explanation": "R = 8.314 J/mol·K in SI units.", "topic": "Chemistry – Gaseous State"}, {"q": "Three 6 μF capacitors are connected in series. The equivalent capacitance is:", "options": ["18 μF", "2 μF", "6 μF", "12 μF"], "answer": 1, "explanation": "1/C = 3/6 gives C = 2 μF.", "topic": "Physics – Capacitors"}, {"q": "Given vectors a = 3i + 4j and b = −3i + 4j, the magnitude of a + b is:", "options": ["8 units", "10 units", "6 units", "14 units"], "answer": 0, "explanation": "a + b = 8j, whose magnitude is 8 units.", "topic": "Physics – Vectors"}, {"q": "A capacitor stores 0.5 J of energy when charged to 100 V. Its capacitance is:", "options": ["100 μF", "50 μF", "10 μF", "1000 μF"], "answer": 0, "explanation": "U = ½CV² gives C = 2U/V² = 1/10000 = 100 μF.", "topic": "Physics – Capacitors"}, {"q": "The number of atoms per unit cell in a face-centred cubic (FCC) lattice is:", "options": ["6", "4", "2", "1"], "answer": 1, "explanation": "8 corners × 1/8 + 6 faces × 1/2 = 4 atoms.", "topic": "Chemistry – Solid State"}, {"q": "The Lyman series of the hydrogen spectrum lies in the:", "options": ["visible region", "ultraviolet region", "infrared region", "microwave region"], "answer": 1, "explanation": "Lyman transitions end at n = 1 with large energy gaps: ultraviolet.", "topic": "Chemistry – Atomic Structure"}, {"q": "The solution of dy/dx = ky (k = 3) with y(0) = 1 is:", "options": ["y = 3x + 1", "y = e^x + 3", "y = e^(3x)", "y = 3e^x"], "answer": 2, "explanation": "dy/y = 3dx ⇒ ln y = 3x + C; y(0) = 1 gives y = e^(3x).", "topic": "Maths – Differential Equations"}, {"q": "[CoF6]³⁻ is paramagnetic with 4 unpaired electrons because F⁻ is a:", "options": ["strong field ligand", "weak field ligand", "ambidentate ligand", "chelating ligand"], "answer": 1, "explanation": "Weak field F⁻ gives high-spin d⁶ Co(III): t2g⁴ eg², 4 unpaired electrons.", "topic": "Chemistry – Coordination Compounds"}, {"q": "Light travels from glass of refractive index 1.5 to air. The critical angle C satisfies:", "options": ["sin C = 1.5", "sin C = 1/1.5", "tan C = 1.5", "cos C = 1.5"], "answer": 1, "explanation": "sin C = 1/μ = 1/1.5 for the glass–air interface.", "topic": "Physics – Ray Optics"}, {"q": "A small sphere attains a terminal velocity of 0.02 m/s in a viscous liquid. If an identical-material sphere of double the radius is dropped, its terminal velocity (Stokes' law) is:", "options": ["0.08 m/s", "0.04 m/s", "0.01 m/s", "0.16 m/s"], "answer": 0, "explanation": "Stokes' terminal velocity ∝ r², so doubling r quadruples v to 0.08 m/s.", "topic": "Physics – Fluid Mechanics"}, {"q": "The value of (1 + i)⁴, where i = √(−1), is:", "options": ["4", "−4", "4i", "−4i"], "answer": 1, "explanation": "(1 + i)² = 2i, so (1 + i)⁴ = (2i)² = −4.", "topic": "Maths – Complex Numbers"}, {"q": "The quantity of electricity required to deposit 1 mol of silver (Ag⁺ + e⁻ → Ag) is:", "options": ["96500 C", "48250 C", "193000 C", "9650 C"], "answer": 0, "explanation": "1 mol of electrons carries 1 faraday = 96500 C.", "topic": "Chemistry – Electrochemistry"}, {"q": "The shape of PCl5 is:", "options": ["octahedral", "trigonal bipyramidal", "square pyramidal", "tetrahedral"], "answer": 1, "explanation": "PCl5 has 5 bond pairs → trigonal bipyramidal.", "topic": "Chemistry – Chemical Bonding"}, {"q": "The product of the roots of 2x² + 3x − 5 = 0 is:", "options": ["−5/2", "5/2", "−3/2", "3/2"], "answer": 0, "explanation": "Product = c/a = −5/2.", "topic": "Maths – Quadratic Equations"}, {"q": "If P(A) = 1/3 and P(B) = 1/4 are mutually exclusive, P(A ∪ B) equals:", "options": ["1/2", "1/7", "1/12", "7/12"], "answer": 3, "explanation": "Mutually exclusive: P(A∪B) = P(A) + P(B) = 1/3 + 1/4 = 7/12.", "topic": "Maths – Probability"}, {"q": "The element with the highest second electron affinity (most endothermic) trend belongs to:", "options": ["Te", "O", "S", "Se"], "answer": 1, "explanation": "Adding a second electron to O⁻ is strongly endothermic due to repulsion; the value is positive (energy absorbed).", "topic": "Chemistry – Periodic Table"}, {"q": "The energy of a photon of wavelength 500 nm is approximately (hc = 1240 eV·nm):", "options": ["2.48 eV", "1.24 eV", "4.96 eV", "620 eV"], "answer": 0, "explanation": "E = hc/λ = 1240/500 = 2.48 eV.", "topic": "Physics – Modern Physics"}, {"q": "The acceleration due to gravity at the centre of Earth is:", "options": ["g", "zero", "2g", "infinite"], "answer": 1, "explanation": "g ∝ r inside Earth (uniform density); at r = 0, g = 0.", "topic": "Physics – Gravitation"}, {"q": "The number of moles in 58.5 g of NaCl (molar mass 58.5 g/mol) is:", "options": ["3422.25 mol", "1 mol", "2 mol", "0.5 mol"], "answer": 1, "explanation": "n = mass/molar mass = 58.5/58.5 = 1 mol.", "topic": "Chemistry – Mole Concept"}, {"q": "The moment of inertia of a solid sphere of mass M and radius R about its diameter is:", "options": ["MR²", "(2/5)MR²", "(1/2)MR²", "(2/3)MR²"], "answer": 1, "explanation": "For a solid sphere, I = (2/5)MR² about any diameter.", "topic": "Physics – Rotational Motion"}, {"q": "The speed of a transverse wave on a stretched string depends on:", "options": ["the amplitude only", "the tension and the linear mass density", "the frequency only", "the wavelength only"], "answer": 1, "explanation": "v = √(T/μ), where T is tension and μ is mass per unit length.", "topic": "Physics – Waves"}, {"q": "In CsCl, the coordination number of each ion is:", "options": ["12", "8", "6", "4"], "answer": 1, "explanation": "CsCl: simple cubic Cl⁻ with Cs⁺ at the body centre → 8:8 coordination.", "topic": "Chemistry – Solid State"}, {"q": "The root-mean-square speed of the molecules of an ideal gas depends on:", "options": ["the pressure only", "the temperature and the molar mass", "the volume only", "the number of moles only"], "answer": 1, "explanation": "v_rms = √(3RT/M), so it depends on T and M.", "topic": "Physics – Kinetic Theory"}, {"q": "By De Moivre's theorem, (cos θ + i sin θ)³ equals:", "options": ["cos 3θ + i sin 3θ", "cos³θ + i sin³θ", "3cos θ + 3i sin θ", "cos θ³ + i sin θ³"], "answer": 0, "explanation": "De Moivre's theorem: (cos θ + i sin θ)ⁿ = cos nθ + i sin nθ, here n = 3.", "topic": "Maths – Complex Numbers"}, {"q": "If the tension in a vibrating string is quadrupled while its mass per unit length stays the same, the wave speed becomes:", "options": ["doubled", "quadrupled", "halved", "unchanged"], "answer": 0, "explanation": "v = √(T/μ), so 4× tension gives 2× speed.", "topic": "Physics – Waves"}, {"q": "The radius of the circle x² + y² + 6x − 8y = 0 is:", "options": ["5", "10", "25", "√7"], "answer": 0, "explanation": "Centre (−3, 4); radius = √(9 + 16 − 0) = 5.", "topic": "Maths – Circles"}, {"q": "The discriminant of the quadratic equation x² + 4x + 4 = 0 is:", "options": ["0", "16", "−16", "8"], "answer": 0, "explanation": "D = 16 − 16 = 0 (a perfect square).", "topic": "Maths – Quadratic Equations"}, {"q": "The degree of the differential equation (dy/dx)² + y = x is:", "options": ["2", "1", "3", "not defined"], "answer": 0, "explanation": "The highest-order derivative dy/dx appears to the power 2, so the degree is 2.", "topic": "Maths – Differential Equations"}, {"q": "Using the odd–even property ∫₋ₐ^ₐ f(x) dx, the value of ∫₋₂^₂ (x³ + 5x²) dx is:", "options": ["0", "80/3", "40/3", "16"], "answer": 1, "explanation": "The odd part x³ integrates to zero over [−2, 2]. ∫₋₂² 5x² dx = 5[x³/3]₋₂² = 5 × 16/3 = 80/3.", "topic": "Maths – Definite Integrals"}, {"q": "Which of the following is the dimensional formula of the gas constant R is?", "options": ["[ML²T⁻¹K⁻¹]", "[ML²T⁻²K⁻²]", "[ML²T⁻²K⁻¹]", "[MLT⁻²K⁻¹]"], "answer": 2, "explanation": "R = PV/(nT) gives [ML²T⁻²]/[K] per mole = [ML²T⁻²K⁻¹].", "topic": "Physics – Units & Dimensions"}, {"q": "For a fixed amount of ideal gas at constant temperature, the plot of PV against P is:", "options": ["a straight line through the origin", "a horizontal line", "a hyperbola", "an exponential curve"], "answer": 1, "explanation": "By Boyle's law PV = constant at fixed T, so the graph is horizontal.", "topic": "Chemistry – Gaseous State"}, {"q": "An electron is accelerated through 100 V. Its de Broglie wavelength is approximately:", "options": ["0.12 nm", "12 nm", "1.2 nm", "0.012 nm"], "answer": 0, "explanation": "λ = h/√p(2meV) ≈ 1.227/√V nm = 1.227/10 ≈ 0.12 nm.", "topic": "Physics – Modern Physics"}, {"q": "A system absorbs 200 J of heat and does 60 J of work on the surroundings. The change in internal energy is:", "options": ["140 J", "260 J", "-140 J", "200 J"], "answer": 0, "explanation": "First law: ΔU = q − w (work done BY system) = 200 − 60 = 140 J.", "topic": "Chemistry – Thermodynamics"}, {"q": "The focus of the parabola y² = 12x is:", "options": ["(6, 0)", "(3, 0)", "(-3, 0)", "(0, 3)"], "answer": 1, "explanation": "y² = 4ax → focus at (a, 0) = (3, 0).", "topic": "Maths – Conic Sections"}, {"q": "A line has direction ratios 2, 3, 6. Its direction cosines are:", "options": ["(2/7, 3/7, 6/7)", "(2, 3, 6)", "(1/2, 1/3, 1/6)", "(2/9, 3/9, 6/9)"], "answer": 0, "explanation": "Divide by √(2² + 3² + 6²) = 7: (2/7, 3/7, 6/7).", "topic": "Maths – 3D Geometry"}, {"q": "The period of sin(3x) is:", "options": ["2π", "π/3", "2π/3", "π"], "answer": 2, "explanation": "Period of sin(kx) is 2π/k = 2π/3.", "topic": "Maths – Trigonometry"}, {"q": "One kilowatt-hour (1 kWh) is equal to:", "options": ["3.6×10⁶ J", "3.6×10³ J", "1000 J", "360 J"], "answer": 0, "explanation": "1 kWh = 1000 W × 3600 s = 3.6×10⁶ J.", "topic": "Physics – Work, Energy & Power"}, {"q": "The centroid of the triangle with vertices (1, 2, 3), (4, 5, 6) and (7, 8, 9) is:", "options": ["(4, 5, 6)", "(3, 4, 5)", "(12, 15, 18)", "(2, 3, 4)"], "answer": 0, "explanation": "Centroid = average of vertices = ((1+4+7)/3, (2+5+8)/3, (3+6+9)/3) = (4, 5, 6).", "topic": "Maths – 3D Geometry"}, {"q": "The rms speed of oxygen molecules at 300 K (M = 32 g/mol) is approximately:", "options": ["240 m/s", "483 m/s", "960 m/s", "1200 m/s"], "answer": 1, "explanation": "v_rms = √(3RT/M) = √(3×8.314×300/0.032) ≈ 483 m/s.", "topic": "Physics – Kinetic Theory"}, {"q": "The distance between the parallel planes x + 2y + 2z = 5 and x + 2y + 2z = 11 is:", "options": ["6", "3", "2", "1"], "answer": 2, "explanation": "Distance = |11 − 5|/√(1² + 2² + 2²) = 6/3 = 2.", "topic": "Maths – 3D Geometry"}, {"q": "The number of σ and π bonds in ethyne (C2H2) is:", "options": ["5σ, 0π", "3σ, 2π", "2σ, 3π", "3σ, 1π"], "answer": 1, "explanation": "C≡C: 1σ + 2π between carbons, plus 2 C–H σ = 3σ, 2π.", "topic": "Chemistry – Organic Chemistry"}, {"q": "The foot of the perpendicular drawn from the point (1, 2, 3) to the xy-plane is:", "options": ["(1, 2, 0)", "(0, 0, 3)", "(1, 0, 0)", "(1, 2, 3)"], "answer": 0, "explanation": "Dropping perpendicularly to the xy-plane sets z = 0, giving (1, 2, 0).", "topic": "Maths – 3D Geometry"}, {"q": "A sonometer wire of length 0.5 m vibrates with frequency 200 Hz at a given tension. If the vibrating length is halved with the same tension, the new frequency is:", "options": ["400 Hz", "200 Hz", "100 Hz", "800 Hz"], "answer": 0, "explanation": "f ∝ 1/L, so halving the length doubles the frequency.", "topic": "Physics – Waves"}, {"q": "The shape of SF4 is:", "options": ["trigonal bipyramidal", "tetrahedral", "see-saw", "square planar"], "answer": 2, "explanation": "SF4 has 4 bond pairs + 1 lone pair → see-saw geometry.", "topic": "Chemistry – Chemical Bonding"}, {"q": "A ball is dropped from rest from a height of 45 m (g = 10 m/s²). The time taken to reach the ground is:", "options": ["3 s", "4.5 s", "9 s", "2 s"], "answer": 0, "explanation": "h = ½gt² gives t = √(2×45/10) = 3 s.", "topic": "Physics – Kinematics (numerical)"}, {"q": "If |z₁| = 2 and |z₂| = 5, then |z₁z₂| equals:", "options": ["7", "10", "25", "3"], "answer": 1, "explanation": "The modulus of a product is the product of the moduli: 2 × 5 = 10.", "topic": "Maths – Complex Numbers"}, {"q": "The left-hand limit of the greatest integer function [x] as x approaches 2 is:", "options": ["1", "2", "0", "does not exist"], "answer": 0, "explanation": "Just left of 2, [x] = 1, so the left-hand limit is 1.", "topic": "Maths – Limits"}, {"q": "If the average density of Earth were doubled while its radius stayed the same, the acceleration due to gravity at its surface would become:", "options": ["2g", "g", "4g", "g/2"], "answer": 0, "explanation": "g = (4/3)πGρR, so g is directly proportional to density ρ.", "topic": "Physics – Gravitation"}, {"q": "The geometric mean of 4 and 9 is:", "options": ["6.5", "6", "13", "36"], "answer": 1, "explanation": "GM = √(4 × 9) = √36 = 6.", "topic": "Maths – Sequences & Series"}, {"q": "cos²x + sin²x equals:", "options": ["2", "0", "1", "cos 2x"], "answer": 2, "explanation": "The fundamental Pythagorean identity: cos²x + sin²x = 1.", "topic": "Maths – Trigonometry"}, {"q": "A particle starts from rest and moves with constant acceleration 2 m/s². Its speed after travelling 25 m is:", "options": ["20 m/s", "10 m/s", "5 m/s", "10 m/s × 2"], "answer": 1, "explanation": "Use v² = u² + 2as with u = 0: v = √(2×2×25) = 10 m/s.", "topic": "Physics – Kinematics"}, {"q": "A circular arc of radius r subtending an angle θ at its centre carries current I. The magnetic field at the centre is:", "options": ["μ₀Iθ/4πr", "μ₀I/2r", "μ₀Iθ/2πr", "μ₀Ir/4πθ"], "answer": 0, "explanation": "The arc is a fraction θ/2π of a full loop: B = (θ/2π)(μ₀I/2r) = μ₀Iθ/4πr.", "topic": "Physics – Magnetism"}, {"q": "For a gaseous reaction with Δn_g = 2, the relation between Kp and Kc is:", "options": ["Kp = Kc(RT)^-2", "Kp = Kc(RT)^2", "Kc = Kp(RT)^2", "Kp = Kc"], "answer": 1, "explanation": "Kp = Kc(RT)^Δn_g = Kc(RT)^2.", "topic": "Chemistry – Equilibrium"}, {"q": "In an LCR series circuit, L = 10 mH and C = 10 μF. The resonant frequency is:", "options": ["251.65 Hz", "160.2 Hz", "1006.58 Hz", "503.29 Hz"], "answer": 3, "explanation": "f₀ = 1/(2π√(LC)) = 1/(2π√(0.01×0)) = 503.29 Hz.", "topic": "Physics – EMI & AC"}, {"q": "A radioactive sample has an activity of 800 Bq. After two half-lives, its activity becomes:", "options": ["200 Bq", "400 Bq", "100 Bq", "0 Bq"], "answer": 0, "explanation": "Each half-life halves the activity: 800 → 400 → 200 Bq.", "topic": "Physics – Modern Physics (numerical)"}, {"q": "A simple pendulum has length 1 m (g = 10 m/s²). Its frequency of small oscillations is approximately:", "options": ["0.5 Hz", "1 Hz", "2 Hz", "0.25 Hz"], "answer": 0, "explanation": "T = 2π√(l/g) = 2π√0.1 ≈ 2 s, so f = 1/T ≈ 0.5 Hz.", "topic": "Physics – Oscillations"}, {"q": "The freezing point depression of a 1 molal aqueous solution of NaCl (van't Hoff factor i = 3, Kf = 1.86 K·kg/mol) is:", "options": ["2.79 K", "11.16 K", "1.86 K", "5.58 K"], "answer": 3, "explanation": "ΔTf = i·Kf·m = 3×1.86×1 = 5.58 K.", "topic": "Chemistry – Solutions"}, {"q": "For a 2×2 matrix A with det A = 5, the determinant of adj A equals:", "options": ["25", "5", "10", "1/5"], "answer": 1, "explanation": "For order 2, det(adj A) = (det A)^(2−1) = 5.", "topic": "Maths – Matrices & Determinants"}, {"q": "By Graham's law, the ratio of the rates of diffusion of H₂ and O₂ under identical conditions is:", "options": ["4 : 1", "1 : 4", "16 : 1", "2 : 1"], "answer": 0, "explanation": "Rate ∝ 1/√M, so r(H₂)/r(O₂) = √(32/2) = 4.", "topic": "Chemistry – Gaseous State"}, {"q": "Two vectors are perpendicular if and only if their dot product is:", "options": ["equal to the product of magnitudes", "0", "1", "−1"], "answer": 1, "explanation": "a·b = |a||b|cosθ = 0 when θ = 90°.", "topic": "Maths – Vectors"}, {"q": "∫ sin(5x) dx equals:", "options": ["cos(5x)/5 + C", "−cos(5x)/5 + C", "−5cos(5x) + C", "sin(5x)/5 + C"], "answer": 1, "explanation": "∫sin(5x)dx = −cos(5x)/5 + C by the chain rule in reverse.", "topic": "Maths – Indefinite Integrals"}, {"q": "For the gaseous reaction H₂ + I₂ ⇌ 2HI, the relation between Kp and Kc is:", "options": ["Kp = Kc(RT)", "Kp = Kc", "Kp = Kc/(RT)", "Kp = Kc(RT)²"], "answer": 1, "explanation": "Δn_g = 0, so Kp = Kc(RT)^0 = Kc.", "topic": "Chemistry – Equilibrium"}, {"q": "The oxidation number of P in H3PO4 is:", "options": ["+1", "+3", "+5", "+7"], "answer": 2, "explanation": "3(+1) + x + 4(−2) = 0 ⇒ x = +5.", "topic": "Chemistry – Redox Reactions"}, {"q": "The mole fraction of solute in a solution containing 1 mol of solute and 4 mol of solvent is:", "options": ["0.2", "0.25", "0.8", "4"], "answer": 0, "explanation": "Mole fraction = 1/(1 + 4) = 0.2.", "topic": "Chemistry – Solutions"}, {"q": "For an ideal gas, Cp − Cv equals:", "options": ["0", "R", "γR", "2R"], "answer": 1, "explanation": "Mayer's relation: Cp − Cv = R per mole of ideal gas.", "topic": "Chemistry – Thermodynamics"}, {"q": "Photoelectric emission from a metal surface occurs only if the incident light's:", "options": ["intensity is very high", "frequency exceeds the threshold frequency", "wavelength is long", "speed is high"], "answer": 1, "explanation": "Each photon needs energy hν ≥ φ; intensity only changes the number of photons.", "topic": "Physics – Modern Physics"}, {"q": "When a solution is diluted by adding more solvent, which quantity remains unchanged?", "options": ["molarity", "number of moles of solute", "volume of solution", "mass of solvent"], "answer": 1, "explanation": "Dilution adds only solvent; the moles of solute stay the same (M₁V₁ = M₂V₂).", "topic": "Chemistry – Solutions"}, {"q": "Within the elastic limit, stress is directly proportional to strain. This statement is:", "options": ["Hooke's law", "Newton's law", "Pascal's law", "Stokes' law"], "answer": 0, "explanation": "Hooke's law: stress ∝ strain within the elastic limit.", "topic": "Physics – Elasticity"}, {"q": "During the electrolysis of concentrated brine, the gas liberated at the anode is:", "options": ["hydrogen", "chlorine", "oxygen", "sodium"], "answer": 1, "explanation": "Cl⁻ is oxidised at the anode: 2Cl⁻ → Cl₂ + 2e⁻.", "topic": "Chemistry – Electrochemistry"}, {"q": "∫ e⁴ˣ dx equals:", "options": ["4e⁴ˣ + C", "e⁴ˣ/4 + C", "e⁴ˣ + C", "e⁴ˣ/2 + C"], "answer": 1, "explanation": "∫e⁴ˣ dx = e⁴ˣ/4 + C.", "topic": "Maths – Indefinite Integrals"}, {"q": "Total internal reflection can occur when light travels:", "options": ["from a rarer to a denser medium", "from a denser to a rarer medium at an angle greater than the critical angle", "at any angle between media", "only in vacuum"], "answer": 1, "explanation": "TIR needs denser → rarer with incidence angle exceeding the critical angle.", "topic": "Physics – Ray Optics"}, {"q": "The ratio Cp/Cv (γ) for a diatomic gas at room temperature is:", "options": ["1.67", "1.4", "1.33", "1"], "answer": 1, "explanation": "For a diatomic gas with 5 degrees of freedom, γ = 7/5 = 1.4.", "topic": "Physics – Thermodynamics"}, {"q": "For vectors 2i + 3j + k and i − j + 2k, if θ is the angle between them, cos θ equals:", "options": ["1/√84", "1/√14", "0", "1/2"], "answer": 0, "explanation": "Dot product = 2 − 3 + 2 = 1; magnitudes √14 and √6, so cos θ = 1/(√14·√6) = 1/√84.", "topic": "Physics – Vectors"}, {"q": "Mass of nickel deposited by 2 A for 96.5 min (Ni²⁺ + 2e⁻ → Ni, M = 58.7) is:", "options": ["7.04 g", "1.76 g", "0.12 g", "3.52 g"], "answer": 3, "explanation": "m = ItM/(nF) = 2×5790×58.7/(2×96500) = 3.52 g.", "topic": "Chemistry – Electrochemistry"}, {"q": "The minimum value of x + 1/x for x > 0 is:", "options": ["2", "0", "1", "∞"], "answer": 0, "explanation": "By AM ≥ GM, x + 1/x ≥ 2√(x·1/x) = 2, equality at x = 1.", "topic": "Maths – Applications of Derivatives"}, {"q": "If |z| = 1, then z·z̅ equals:", "options": ["1", "0", "2", "z²"], "answer": 0, "explanation": "z·z̅ = |z|² = 1.", "topic": "Maths – Complex Numbers"}, {"q": "An object is placed 60 cm in front of a concave mirror of focal length 20 cm (magnitudes). The object distance satisfying the mirror formula gives an image at 60 cm when the object is at:", "options": ["30 cm", "40 cm", "15 cm", "60 cm"], "answer": 0, "explanation": "1/u = 1/f − 1/v = 1/20 − 1/60 = 2/60, so u = 30 cm.", "topic": "Physics – Ray Optics"}, {"q": "The single arithmetic mean inserted between 4 and 16 is:", "options": ["8", "12", "10", "20"], "answer": 2, "explanation": "The AM between two numbers is their average: (4 + 16)/2 = 10.", "topic": "Maths – Sequences & Series"}, {"q": "The derivative of x³ with respect to x² is:", "options": ["3x/2", "3x²", "2x", "3x"], "answer": 0, "explanation": "d(x³)/d(x²) = 3x²/(2x) = 3x/2.", "topic": "Maths – Differentiation"}, {"q": "Poisson's ratio for most metals lies in the range:", "options": ["0 to 0.5", "−1 to 0", "0.5 to 1", "1 to 2"], "answer": 0, "explanation": "For isotropic elastic solids Poisson's ratio lies between 0 and 0.5 (typically ~0.3 for metals).", "topic": "Physics – Elasticity"}, {"q": "The number of terms in the expansion of (x + y + z)^n is:", "options": ["n + 1", "(n + 1)(n + 2)/2", "2n", "n²"], "answer": 1, "explanation": "Terms are x^a y^b z^c with a + b + c = n: C(n+2, 2) = (n+1)(n+2)/2.", "topic": "Maths – Binomial Theorem"}, {"q": "Two identical point charges repel each other with force F when distance d apart. If the distance is halved, the force becomes:", "options": ["2F", "4F", "F/2", "F/4"], "answer": 1, "explanation": "F ∝ 1/r², so halving r multiplies F by 4.", "topic": "Physics – Electrostatics"}, {"q": "A seconds pendulum is defined as a simple pendulum whose time period is:", "options": ["1 s", "2 s", "0.5 s", "4 s"], "answer": 1, "explanation": "A seconds pendulum takes one second per swing, i.e. period 2 s.", "topic": "Physics – Oscillations"}, {"q": "The maximum stress a wire can bear before breaking is called its:", "options": ["yield point", "tensile strength", "elastic limit", "fatigue limit"], "answer": 1, "explanation": "Breaking (ultimate) stress is the tensile strength of the material.", "topic": "Physics – Elasticity"}, {"q": "A 2 M solution is diluted 4-fold with water. The molarity of the diluted solution is:", "options": ["0.5 M", "8 M", "2 M", "0.25 M"], "answer": 0, "explanation": "M₂ = M₁/4 = 2/4 = 0.5 M.", "topic": "Chemistry – Solutions"}, {"q": "The solubility of Ag2CrO4-type salt MX2 is s = 0.00001 mol/L. Its Ksp is:", "options": ["0.000000000000001", "0.0000000001", "0.000000000000004", "0.000000000000002"], "answer": 2, "explanation": "MX2 ⇌ M²⁺ + 2X⁻: Ksp = [M²⁺][X⁻]² = s×(2s)² = 4s³ = 0.000000000000004.", "topic": "Chemistry – Equilibrium"}, {"q": "The bond order of CO is:", "options": ["3.5", "2.5", "3", "4"], "answer": 2, "explanation": "Bond order = (bonding − antibonding electrons)/2; for CO this equals 3.", "topic": "Chemistry – Chemical Bonding"}, {"q": "If Kc = 100 for the reaction A ⇌ B, then Kc for the reaction 2A ⇌ 2B is:", "options": ["200", "10000", "100", "10"], "answer": 1, "explanation": "Doubling the stoichiometric coefficients squares K: 100² = 10000.", "topic": "Chemistry – Equilibrium"}, {"q": "If the roots of ax² + bx + c = 0 are real and equal, then:", "options": ["b² = 4ac", "b² > 4ac", "b² < 4ac", "a = b = c"], "answer": 0, "explanation": "Equal roots ⟺ discriminant zero: b² − 4ac = 0.", "topic": "Maths – Quadratic Equations"}, {"q": "A proton enters a uniform magnetic field perpendicularly. The path it follows is a:", "options": ["straight line", "circle", "parabola", "helix"], "answer": 1, "explanation": "With v ⊥ B, the magnetic force provides centripetal force: circular motion.", "topic": "Physics – Magnetism"}, {"q": "In the expansion of (1 + x)^10, the coefficient of x^5 is:", "options": ["252", "210", "120", "10"], "answer": 0, "explanation": "C(10, 5) = 252.", "topic": "Maths – Binomial Theorem"}, {"q": "Washing soda is:", "options": ["Na2CO3·10H2O", "NaHCO3", "NaOH", "Na2CO3 (anhydrous)"], "answer": 0, "explanation": "Washing soda is sodium carbonate decahydrate.", "topic": "Chemistry – s, p, d & f Block"}, {"q": "If y = x·eˣ, then dy/dx equals:", "options": ["eˣ", "xeˣ", "eˣ(1 + x)", "2xeˣ"], "answer": 2, "explanation": "By the product rule: dy/dx = 1·eˣ + x·eˣ = eˣ(1 + x).", "topic": "Maths – Differentiation"}, {"q": "The roots of the equation x² + x + 1 = 0 are:", "options": ["real and equal", "real and distinct", "complex conjugates", "rational"], "answer": 2, "explanation": "D = 1 − 4 = −3 < 0, so the roots are a pair of complex conjugates.", "topic": "Maths – Quadratic Equations"}, {"q": "The distance between the two foci of the ellipse x²/25 + y²/9 = 1 is:", "options": ["8", "10", "6", "4"], "answer": 0, "explanation": "a = 5, b = 3, c = √(25−9) = 4; focal distance = 2c = 8.", "topic": "Maths – Conic Sections"}, {"q": "The value of sin 30° + cos 60° is:", "options": ["√3/2", "1", "0", "1/2"], "answer": 1, "explanation": "sin 30° = 1/2 and cos 60° = 1/2, so the sum is 1.", "topic": "Maths – Trigonometry"}, {"q": "In a BCC unit cell, the relation between edge length a and atomic radius r is:", "options": ["a = 4r", "a = 2r", "√3·a = 4r", "√2·a = 4r"], "answer": 2, "explanation": "Body diagonal = √3·a = 4r in BCC.", "topic": "Chemistry – Solid State"}, {"q": "The ratio of the radius of the n = 3 orbit to the n = 2 orbit of hydrogen is:", "options": ["2.25", "1.5", "3.38", "0.44"], "answer": 0, "explanation": "r ∝ n², so r₂/r₁ = (3/2)² = 2.25.", "topic": "Physics – Modern Physics"}, {"q": "The de Broglie wavelength of an electron accelerated through 100 V is approximately:", "options": ["0.123 nm", "1.23 nm", "12.3 nm", "0.0123 nm"], "answer": 0, "explanation": "λ = 12.27/√V Å = 1.227 Å = 0.123 nm.", "topic": "Chemistry – Atomic Structure"}, {"q": "A solution that obeys Raoult's law at all concentrations is called:", "options": ["ideal", "real", "dilute", "concentrated"], "answer": 0, "explanation": "Ideal solutions follow Raoult's law exactly over the whole range.", "topic": "Chemistry – Solutions"}, {"q": "A first-order reaction has rate constant k = 0.0693 min⁻¹. Its half-life is:", "options": ["10 min", "20 min", "5 min", "14.43 min"], "answer": 0, "explanation": "First order: t½ = 0.693/k = 0.693/0.0693 = 10 min.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "Bleaching powder is:", "options": ["NaOCl", "CaCl2", "Ca(OCl)2", "CaOCl2"], "answer": 3, "explanation": "Bleaching powder: CaOCl2 (calcium oxychloride).", "topic": "Chemistry – s, p, d & f Block"}, {"q": "The focal length of a lens depends on all of the following EXCEPT:", "options": ["refractive index of the material", "the object distance", "wavelength of light used", "radii of curvature"], "answer": 1, "explanation": "Lensmaker's formula 1/f = (μ−1)(1/R₁ − 1/R₂) involves μ, R₁, R₂ — not object distance.", "topic": "Physics – Ray Optics"}, {"q": "A 10 μF capacitor is connected across a 12 V battery. The charge stored on it is:", "options": ["120 μC", "12 μC", "1.2 μC", "1200 μC"], "answer": 0, "explanation": "Q = CV = 10 × 12 = 120 μC.", "topic": "Physics – Capacitors"}, {"q": "The slope of the line y = 3x + 4 is:", "options": ["0.3333333333333333", "3", "4", "-3"], "answer": 1, "explanation": "In y = mx + c, the slope is m = 3.", "topic": "Maths – Straight Lines"}, {"q": "EDTA is a:", "options": ["bidentate ligand", "hexadentate ligand", "monodentate ligand", "tridentate ligand"], "answer": 1, "explanation": "EDTA donates through 2 N and 4 O atoms → hexadentate.", "topic": "Chemistry – Coordination Compounds"}, {"q": "In an ideal step-up transformer, compared with the primary coil the secondary coil has:", "options": ["higher voltage and lower current", "lower voltage and higher current", "the same voltage and current", "higher voltage and higher current"], "answer": 0, "explanation": "Voltage is stepped up and, for ideal power conservation, current steps down.", "topic": "Physics – EMI & AC"}, {"q": "A dielectric slab of constant K = 4 is inserted into an isolated (disconnected) charged parallel-plate capacitor. The voltage across the plates becomes:", "options": ["4 times the original", "one-fourth the original", "unchanged", "zero"], "answer": 1, "explanation": "Q is fixed; C becomes 4C, so V = Q/C falls to one-fourth.", "topic": "Physics – Capacitors"}, {"q": "A machine does 500 J of work in 10 s. Its power output is:", "options": ["50 W", "5000 W", "5 W", "500 W"], "answer": 0, "explanation": "P = W/t = 500/10 = 50 W.", "topic": "Physics – Work, Energy & Power"}, {"q": "The standard enthalpies of formation of H₂O(g) and H₂O(l) are −242 kJ/mol and −286 kJ/mol. The enthalpy of vaporisation of water is:", "options": ["+44 kJ/mol", "−44 kJ/mol", "−528 kJ/mol", "+528 kJ/mol"], "answer": 0, "explanation": "ΔH_vap = ΔHf(H₂O,g) − ΔHf(H₂O,l) = −242 − (−286) = +44 kJ/mol.", "topic": "Chemistry – Thermodynamics"}, {"q": "A ball is thrown horizontally from the top of a 20 m tower (g = 10 m/s²). The time it takes to hit the ground is:", "options": ["2 s", "1 s", "4 s", "√2 s"], "answer": 0, "explanation": "Vertical motion: t = √(2h/g) = √(40/10) = 2 s; horizontal velocity does not affect fall time.", "topic": "Physics – Projectile Motion"}, {"q": "Which of the following is the dimensional formula of Planck's constant is?", "options": ["[ML²T⁻²]", "[MLT⁻¹]", "[ML³T⁻¹]", "[ML²T⁻¹]"], "answer": 3, "explanation": "h = E/ν gives [ML²T⁻²]/[T⁻¹] = [ML²T⁻¹].", "topic": "Physics – Units & Dimensions"}, {"q": "The standard enthalpies of formation of CO₂(g) and H₂O(l) are −394 and −286 kJ/mol. For CH₄ + 2O₂ → CO₂ + 2H₂O, ΔH_comb = −890 kJ/mol. The standard enthalpy of formation of CH₄ is:", "options": ["−76 kJ/mol", "−890 kJ/mol", "+76 kJ/mol", "−966 kJ/mol"], "answer": 0, "explanation": "−890 = (−394 − 572) − ΔHf(CH₄), so ΔHf(CH₄) = −966 + 890 = −76 kJ/mol.", "topic": "Chemistry – Thermodynamics"}, {"q": "Faraday's first law of electrolysis states that the mass of substance deposited is proportional to:", "options": ["the current only", "the quantity of electricity passed", "the time only", "the applied voltage"], "answer": 1, "explanation": "w = ZQ: mass deposited ∝ quantity of electricity Q = It.", "topic": "Chemistry – Electrochemistry"}, {"q": "Boyle's law (PV = constant) holds for a fixed mass of gas at:", "options": ["constant pressure", "constant temperature", "constant volume", "constant density"], "answer": 1, "explanation": "Boyle's law is the constant-temperature relation.", "topic": "Chemistry – Gaseous State"}, {"q": "A boat sails 3 km due east and then 4 km due north. The magnitude of its displacement from the start is:", "options": ["7 km", "5 km", "1 km", "25 km"], "answer": 1, "explanation": "Displacement = √(3² + 4²) = 5 km.", "topic": "Physics – Vectors"}, {"q": "The centre of the circle passing through (0, 0), (4, 0) and (0, 6) is:", "options": ["(2, 3)", "(4, 6)", "(0, 0)", "(3, 2)"], "answer": 0, "explanation": "The perpendicular bisectors of the chords give x = 2 and y = 3, so the centre is (2, 3).", "topic": "Maths – Circles"}, {"q": "The eccentricity of any parabola is:", "options": ["1", "0", "2", "1/2"], "answer": 0, "explanation": "By definition, a parabola has eccentricity 1.", "topic": "Maths – Conic Sections"}, {"q": "The principal argument of the complex number −i is:", "options": ["π/2", "−π/2", "π", "0"], "answer": 1, "explanation": "−i lies on the negative imaginary axis, so its principal argument is −π/2.", "topic": "Maths – Complex Numbers"}, {"q": "For l = 3, the number of orbitals is:", "options": ["5", "9", "3", "7"], "answer": 3, "explanation": "Number of orbitals = 2l + 1 = 7 (f subshell).", "topic": "Chemistry – Atomic Structure"}, {"q": "The statement that no heat engine can be more efficient than a reversible Carnot engine operating between the same two temperatures follows from the:", "options": ["first law of thermodynamics", "second law of thermodynamics", "zeroth law of thermodynamics", "third law of thermodynamics"], "answer": 1, "explanation": "This is Carnot's theorem, a consequence of the second law.", "topic": "Physics – Thermodynamics"}, {"q": "The 10th term of the arithmetic progression 5, 8, 11, … is:", "options": ["32", "35", "29", "30"], "answer": 0, "explanation": "a₁₀ = 5 + 9×3 = 32.", "topic": "Maths – Sequences & Series"}, {"q": "A 1000 kg car rounds a curve of radius 100 m. If the maximum static friction available is 5000 N, the maximum safe speed is:", "options": ["22.4 m/s", "50 m/s", "10 m/s", "5 m/s"], "answer": 0, "explanation": "v_max = √(fR/m) = √(5000×100/1000) = √500 ≈ 22.4 m/s.", "topic": "Physics – Circular Motion"}, {"q": "The number of unpaired electrons in [Fe(CN)6]³⁻ is:", "options": ["3", "0", "1", "5"], "answer": 2, "explanation": "Strong field CN⁻: low-spin d⁵ → t2g⁵, one unpaired electron.", "topic": "Chemistry – Coordination Compounds"}, {"q": "sin(2x) equals:", "options": ["cos²x − sin²x only", "2 sin²x", "sin²x + cos²x", "2 sin x cos x"], "answer": 3, "explanation": "Double-angle formula: sin 2x = 2 sin x cos x.", "topic": "Maths – Trigonometry"}, {"q": "The IUPAC name of K3[Fe(CN)6] is:", "options": ["potassium hexacyanidoferrate(III)", "tripotassium hexacyanidoferrate(III)", "potassium hexacyanoferrate(II)", "potassium hexacyanide ferrate(III)"], "answer": 0, "explanation": "Anionic complex: hexacyanido + ferrate; Fe is +3.", "topic": "Chemistry – Coordination Compounds"}, {"q": "Which ion is smallest?", "options": ["Ne", "Na⁺", "Mg²⁺", "Al³⁺"], "answer": 3, "explanation": "Among isoelectronic species, the one with the most protons (Al³⁺) is smallest.", "topic": "Chemistry – Periodic Table"}, {"q": "If z = 3 − 4i, then |z| equals:", "options": ["5", "7", "1", "25"], "answer": 0, "explanation": "|z| = √(3² + (−4)²) = √25 = 5.", "topic": "Maths – Complex Numbers"}, {"q": "The number of moles in 120 g of urea CO(NH2)2 (molar mass 60 g/mol) is:", "options": ["7200 mol", "1 mol", "2 mol", "4 mol"], "answer": 2, "explanation": "n = mass/molar mass = 120/60 = 2 mol.", "topic": "Chemistry – Mole Concept"}, {"q": "The number of tangents that can be drawn from the point (5, 5) to the circle x² + y² = 9 is:", "options": ["0", "1", "2", "infinitely many"], "answer": 2, "explanation": "The point lies outside the circle (25 + 25 > 9), so two tangents can be drawn.", "topic": "Maths – Circles"}, {"q": "The relative lowering of vapour pressure of a solution is equal to:", "options": ["the molality of the solution", "the mole fraction of the solute", "the molarity of the solution", "the mass fraction of the solvent"], "answer": 1, "explanation": "Δp/p° = x_solute (Raoult's law for non-volatile solute).", "topic": "Chemistry – Solutions"}, {"q": "An ice cube floating in water melts completely. The water level:", "options": ["rises", "falls", "first rises then falls", "remains unchanged"], "answer": 3, "explanation": "The floating ice displaces water equal to its own weight; melted water exactly fills that volume.", "topic": "Physics – Fluid Mechanics"}, {"q": "Acidity order: HCOOH, CH3COOH, ClCH2COOH is:", "options": ["HCOOH > ClCH2COOH > CH3COOH", "ClCH2COOH > HCOOH > CH3COOH", "all equal", "CH3COOH > HCOOH > ClCH2COOH"], "answer": 1, "explanation": "–I of Cl strengthens the acid; +I of CH3 weakens it relative to formic acid.", "topic": "Chemistry – Organic Chemistry"}, {"q": "The refractive index of a medium is √3. The Brewster (polarising) angle for it is:", "options": ["30°", "45°", "60°", "90°"], "answer": 2, "explanation": "tan θ_B = μ = √3 gives θ_B = 60°.", "topic": "Physics – Ray Optics"}, {"q": "The bond order of O2 is:", "options": ["3", "1.5", "2.5", "2"], "answer": 3, "explanation": "Bond order = (bonding − antibonding electrons)/2; for O2 this equals 2.", "topic": "Chemistry – Chemical Bonding"}, {"q": "In simple harmonic motion, the total mechanical energy of the oscillator is proportional to:", "options": ["the amplitude", "the square of the amplitude", "the frequency", "the mass"], "answer": 1, "explanation": "E = ½mω²A², so E ∝ A².", "topic": "Physics – Oscillations"}, {"q": "An acidic buffer solution is prepared from:", "options": ["a strong acid and a strong base", "a weak acid and its salt", "a weak base and its salt", "a strong acid and a weak base"], "answer": 1, "explanation": "An acidic buffer is a weak acid plus its conjugate-base salt.", "topic": "Chemistry – Equilibrium"}, {"q": "The function f(x) = x³ − 3x is strictly increasing for:", "options": ["|x| > 1", "|x| < 1", "x > 0", "all real x"], "answer": 0, "explanation": "f′(x) = 3x² − 3 > 0 gives x² > 1, i.e. |x| > 1.", "topic": "Maths – Applications of Derivatives"}, {"q": "Two resistors of 4 Ω each are joined in series. The equivalent resistance is:", "options": ["8 Ω", "2 Ω", "4 Ω", "6 Ω"], "answer": 0, "explanation": "Series: R = 4 + 4 = 8 Ω.", "topic": "Physics – Current Electricity"}, {"q": "A square matrix A satisfies A² = A. Such a matrix is called:", "options": ["orthogonal", "idempotent", "nilpotent", "involutory"], "answer": 1, "explanation": "A² = A defines an idempotent matrix (A² = 0 is nilpotent, A² = I is involutory).", "topic": "Maths – Matrices & Determinants"}, {"q": "The directrix of the parabola y² = 8x is:", "options": ["x = −2", "y = 2", "x = 2", "y = −2"], "answer": 0, "explanation": "y² = 4ax with 4a = 8 ⇒ a = 2; directrix x = −a = −2.", "topic": "Maths – Conic Sections"}, {"q": "A 100 W, 220 V bulb is operated at 110 V (filament resistance assumed constant). The power consumed is approximately:", "options": ["25 W", "50 W", "100 W", "200 W"], "answer": 0, "explanation": "P = V²/R, so halving V quarters P: 100/4 = 25 W.", "topic": "Physics – Current Electricity"}, {"q": "∫ sec²(3x) dx equals:", "options": ["tan(3x)/3 + C", "3tan(3x) + C", "sec(3x)tan(3x)/3 + C", "tan²(3x)/3 + C"], "answer": 0, "explanation": "∫sec²(3x)dx = tan(3x)/3 + C by the chain rule in reverse.", "topic": "Maths – Indefinite Integrals"}, {"q": "Esterification of a carboxylic acid with an alcohol needs:", "options": ["conc. H2SO4 catalyst", "no catalyst", "NaOH catalyst", "Pt catalyst"], "answer": 0, "explanation": "Fischer esterification is acid-catalysed.", "topic": "Chemistry – Organic Chemistry"}, {"q": "The limit of (tan x)/x as x → 0 is:", "options": ["1", "0", "∞", "−1"], "answer": 0, "explanation": "tan x ≈ x for small x, so the limit is 1.", "topic": "Maths – Limits"}, {"q": "A projectile's time of flight is 4 s (g = 10 m/s²). The vertical component of its initial velocity is:", "options": ["20 m/s", "40 m/s", "10 m/s", "5 m/s"], "answer": 0, "explanation": "T = 2u_y/g gives u_y = gT/2 = 20 m/s.", "topic": "Physics – Projectile Motion"}, {"q": "The scalar projection of a = (2, 3, 0) onto b = (1, 0, 0) is:", "options": ["3", "2", "√13", "5"], "answer": 1, "explanation": "Scalar projection = (a · b)/|b| = 2/1 = 2.", "topic": "Maths – Vectors"}, {"q": "A train starts from rest and accelerates uniformly at 2 m/s² for 10 s. The distance covered is:", "options": ["100 m", "200 m", "20 m", "50 m"], "answer": 0, "explanation": "s = ½at² = ½ × 2 × 100 = 100 m.", "topic": "Physics – Kinematics (numerical)"}, {"q": "The number of terms in the AP 3, 8, 13, …, 98 is:", "options": ["19", "20", "21", "18"], "answer": 1, "explanation": "98 = 3 + (n − 1)×5 gives n − 1 = 19, so n = 20.", "topic": "Maths – Sequences & Series"}, {"q": "The determinant of the upper-triangular matrix [[2, 7, 1], [0, 3, 4], [0, 0, 5]] is:", "options": ["30", "10", "6", "0"], "answer": 0, "explanation": "The determinant of a triangular matrix is the product of its diagonal entries: 2 × 3 × 5 = 30.", "topic": "Maths – Matrices & Determinants"}, {"q": "The phase difference between two points 0.25 m apart on a wave of wavelength 1 m is:", "options": ["π/2", "π", "π/4", "2π"], "answer": 0, "explanation": "Phase difference = (2π/λ)·Δx = 2π × 0.25 = π/2.", "topic": "Physics – Waves"}, {"q": "The value of λ for which the vectors (2, 4, 6) and (1, 2, λ) are parallel is:", "options": ["6", "2", "3", "4"], "answer": 2, "explanation": "Parallel vectors have proportional components: 2/1 = 4/2 = 6/λ, so λ = 3.", "topic": "Maths – Vectors"}, {"q": "Kepler's third law states that for planetary orbits:", "options": ["T ∝ r²", "T² ∝ r²", "T² ∝ r³", "T ∝ r³"], "answer": 2, "explanation": "Kepler's third law: the square of the orbital period is proportional to the cube of the semi-major axis.", "topic": "Physics – Gravitation"}, {"q": "The value of ∫₀² 3x² dx is:", "options": ["8", "12", "4", "6"], "answer": 0, "explanation": "∫3x² dx = x³; evaluated 0 to 2 gives 8.", "topic": "Maths – Definite Integrals (numerical)"}, {"q": "The average kinetic energy of 1 mol of an ideal gas at 300 K is (R = 8.314 J/mol·K):", "options": ["3741 J", "2494 J", "8314 J", "1247 J"], "answer": 0, "explanation": "KE = (3/2)RT = 1.5 × 8.314 × 300 = 3741 J.", "topic": "Chemistry – Gaseous State"}, {"q": "Which of the following sets of quantum numbers is NOT allowed?", "options": ["n = 2, l = 1, m = 0", "n = 3, l = 2, m = −2", "n = 2, l = 2, m = 0", "n = 1, l = 0, m = 0"], "answer": 2, "explanation": "l must be less than n; l = 2 is not allowed for n = 2.", "topic": "Chemistry – Atomic Structure"}, {"q": "If 10 people each shake hands exactly once with everyone else, the total number of handshakes is:", "options": ["90", "45", "100", "50"], "answer": 1, "explanation": "Each handshake is an unordered pair: C(10, 2) = 45.", "topic": "Maths – Permutations & Combinations"}, {"q": "A car travels 60 km at 30 km/h and returns the same distance at 60 km/h. Its average speed for the whole trip is:", "options": ["45 km/h", "40 km/h", "50 km/h", "30 km/h"], "answer": 1, "explanation": "Average speed = 2v₁v₂/(v₁+v₂) = 2×30×60/90 = 40 km/h.", "topic": "Physics – Kinematics"}, {"q": "NaCl has which type of crystal structure?", "options": ["simple cubic", "HCP", "BCC", "FCC (rock salt)"], "answer": 3, "explanation": "NaCl: Cl⁻ forms FCC with Na⁺ in all octahedral voids — rock-salt structure.", "topic": "Chemistry – Solid State"}, {"q": "If det A = 6 for a 2×2 matrix A, then det(3A) equals:", "options": ["18", "54", "108", "9"], "answer": 1, "explanation": "det(3A) = 3² × det A = 9 × 6 = 54.", "topic": "Maths – Matrices & Determinants"}, {"q": "Mass of silver deposited by 1 A for 120 min (Ag⁺ + e⁻ → Ag, M = 108) is:", "options": ["8.06 g", "4.03 g", "16.12 g", "0.07 g"], "answer": 0, "explanation": "m = ItM/(nF) = 1×7200×108/(1×96500) = 8.06 g.", "topic": "Chemistry – Electrochemistry"}, {"q": "Given 2SO₂ + O₂ → 2SO₃, ΔH = −198 kJ/mol and S + O₂ → SO₂, ΔH = −297 kJ/mol, the enthalpy change for S + 3/2O₂ → SO₃ is:", "options": ["−396 kJ/mol", "−495 kJ/mol", "−198 kJ/mol", "+396 kJ/mol"], "answer": 0, "explanation": "Add half of the first reaction (−99 kJ/mol) to the second: −297 − 99 = −396 kJ/mol.", "topic": "Chemistry – Thermodynamics"}, {"q": "The energy density (energy per unit volume) in an electric field E in vacuum is:", "options": ["ε₀E²", "½ε₀E²", "2ε₀E²", "ε₀E²/4"], "answer": 1, "explanation": "u = ½ε₀E².", "topic": "Physics – Capacitors"}, {"q": "The matrix [[2, 4], [1, 2]] is singular because its determinant equals:", "options": ["4", "0", "8", "−4"], "answer": 1, "explanation": "det = 2×2 − 4×1 = 0, and a square matrix is singular exactly when its determinant is zero.", "topic": "Maths – Matrices & Determinants"}, {"q": "A Carnot engine operates between a source at 800 K and a sink at 400 K. Its efficiency is:", "options": ["25%", "50%", "75%", "100%"], "answer": 1, "explanation": "η = 1 − T₂/T₁ = 1 − 400/800 = 0.5 = 50%.", "topic": "Physics – Thermodynamics"}, {"q": "A rocket ejects burnt gas at a speed of 1000 m/s relative to itself at the rate of 20 kg/s. The thrust on the rocket is:", "options": ["20000 N", "2000 N", "50000 N", "1000 N"], "answer": 0, "explanation": "Thrust = v·(dm/dt) = 1000 × 20 = 20000 N.", "topic": "Physics – Laws of Motion"}, {"q": "The number of moles in 360 g of glucose C6H12O6 (molar mass 180 g/mol) is:", "options": ["2 mol", "64800 mol", "4 mol", "1 mol"], "answer": 0, "explanation": "n = mass/molar mass = 360/180 = 2 mol.", "topic": "Chemistry – Mole Concept"}, {"q": "The x-intercept of the line 2x + 3y = 6 is:", "options": ["3", "2", "6", "−3"], "answer": 0, "explanation": "Set y = 0: 2x = 6, so x = 3.", "topic": "Maths – Straight Lines"}, {"q": "Ohm's law (V = IR with constant R) is valid for:", "options": ["all materials", "metallic conductors at constant temperature", "semiconductors under all conditions", "electrolytes always"], "answer": 1, "explanation": "Ohm's law holds for ohmic (metallic) conductors at fixed temperature.", "topic": "Physics – Current Electricity"}, {"q": "The slope of the line perpendicular to y = 2x + 1 is:", "options": ["2", "−1/2", "1/2", "−2"], "answer": 1, "explanation": "Perpendicular slopes multiply to −1: m = −1/2.", "topic": "Maths – Straight Lines"}, {"q": "If s is the molar solubility of AgCl, its solubility product Ksp equals:", "options": ["s", "s²", "4s³", "2s"], "answer": 1, "explanation": "AgCl ⇌ Ag⁺ + Cl⁻: Ksp = [Ag⁺][Cl⁻] = s·s = s².", "topic": "Chemistry – Equilibrium"}, {"q": "Given that ∫₀¹ (x + x²) dx = 5/6, the value of ∫₀¹ ((1 − x) + (1 − x)²) dx is:", "options": ["1/6", "5/6", "1", "0"], "answer": 1, "explanation": "Substituting u = 1 − x reverses the limits, and ∫₀ᵃ f(x) dx = ∫₀ᵃ f(a − x) dx, so the integral equals 5/6.", "topic": "Maths – Definite Integrals"}, {"q": "The value of lim(x→∞) (3x² + 2)/(x² + 1) is:", "options": ["3", "2", "∞", "0"], "answer": 0, "explanation": "Divide by x²: (3 + 2/x²)/(1 + 1/x²) → 3.", "topic": "Maths – Limits"}, {"q": "The number of ways to award gold, silver and bronze medals to 8 athletes is:", "options": ["24", "56", "336", "512"], "answer": 2, "explanation": "Ordered selection of 3 from 8: P(8, 3) = 8×7×6 = 336.", "topic": "Maths – Permutations & Combinations"}, {"q": "The number of diagonals of a hexagon is:", "options": ["6", "12", "9", "15"], "answer": 2, "explanation": "Diagonals = C(6, 2) − 6 = 15 − 6 = 9.", "topic": "Maths – Permutations & Combinations"}, {"q": "The unit of the rate constant for a second-order reaction is:", "options": ["mol·L⁻¹·s⁻¹", "L·mol⁻¹·s⁻¹", "L²·mol⁻²·s⁻¹", "s⁻¹"], "answer": 1, "explanation": "Units of k = (mol/L)^(1−n)·s⁻¹; for n = 2 this is L·mol⁻¹·s⁻¹.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "Total nodes in a 4s orbital:", "options": ["5", "4", "2", "3"], "answer": 3, "explanation": "Total nodes = n − 1 = 3 (all radial for s).", "topic": "Chemistry – Atomic Structure"}, {"q": "The number of functions from {1, 2} to {a, b, c} is:", "options": ["6", "5", "9", "8"], "answer": 2, "explanation": "Each of the 2 domain elements has 3 choices, giving 3² = 9 functions.", "topic": "Maths – Sets & Functions"}, {"q": "The magnetic field at a distance r from a long straight current-carrying wire varies with r as:", "options": ["1/r", "1/r²", "r", "r²"], "answer": 0, "explanation": "B = μ₀I/2πr ∝ 1/r.", "topic": "Physics – Magnetism"}, {"q": "The distance of the point (1, 2, 3) from the plane 2x + y + 2z = 10 is:", "options": ["0", "1", "10/3", "2"], "answer": 0, "explanation": "|2(1) + 2 + 2(3) − 10|/√(4 + 1 + 4) = 0/3 = 0; the point lies on the plane.", "topic": "Maths – 3D Geometry"}, {"q": "The quadratic equation whose roots are 2 and −3 is:", "options": ["x² + x − 6 = 0", "x² − x − 6 = 0", "x² + 5x + 6 = 0", "x² − 5x + 6 = 0"], "answer": 0, "explanation": "Sum = −1, product = −6, so x² − (sum)x + product = x² + x − 6 = 0.", "topic": "Maths – Quadratic Equations"}, {"q": "The linear momentum of a 0.5 kg ball moving at 20 m/s is:", "options": ["10 kg·m/s", "40 kg·m/s", "0.025 kg·m/s", "20 kg·m/s"], "answer": 0, "explanation": "p = mv = 0.5 × 20 = 10 kg·m/s.", "topic": "Physics – Laws of Motion"}, {"q": "The magnitude of the vector i + j + k is:", "options": ["3", "√3", "1", "9"], "answer": 1, "explanation": "|i + j + k| = √(1 + 1 + 1) = √3.", "topic": "Maths – Vectors"}, {"q": "The standard hydrogen electrode is primarily used as:", "options": ["a source of electric power", "a reference electrode", "a pH indicator", "a salt bridge"], "answer": 1, "explanation": "SHE is the universal reference electrode (E° = 0).", "topic": "Chemistry – Electrochemistry"}, {"q": "The number of moles in 100 g of CaCO3 (molar mass 100 g/mol) is:", "options": ["10000 mol", "1 mol", "0.5 mol", "2 mol"], "answer": 1, "explanation": "n = mass/molar mass = 100/100 = 1 mol.", "topic": "Chemistry – Mole Concept"}, {"q": "The power of a concave lens of focal length 50 cm is:", "options": ["+2 D", "−2 D", "+0.5 D", "−0.5 D"], "answer": 1, "explanation": "P = 1/f = 1/(−0.5 m) = −2 D.", "topic": "Physics – Ray Optics"}, {"q": "The 2nd term of a GP is 12 and the 4th term is 48. The (positive) common ratio is:", "options": ["4", "2", "3", "6"], "answer": 1, "explanation": "ar³/ar = r² = 48/12 = 4, so r = 2.", "topic": "Maths – Sequences & Series"}, {"q": "The electric field at a distance 0.1 m from a point charge of 2 μC is:", "options": ["1800000 N/C", "900000 N/C", "3600000 N/C", "180000 N/C"], "answer": 0, "explanation": "E = kq/r² = 9×10⁹×2×10⁻⁶/0.1² = 1800000 N/C.", "topic": "Physics – Electrostatics"}, {"q": "When 5 is added to every observation of a dataset whose mean is 12, the new mean becomes:", "options": ["12", "17", "7", "60"], "answer": 1, "explanation": "Adding a constant c to every observation shifts the mean by c: 12 + 5 = 17.", "topic": "Maths – Statistics"}, {"q": "The length of the tangent drawn from (4, 3) to the circle x² + y² = 16 is:", "options": ["3", "5", "9", "7"], "answer": 0, "explanation": "Tangent length = √(S₁) = √(16 + 9 − 16) = 3.", "topic": "Maths – Circles"}, {"q": "In a Wheatstone bridge, P = 4 Ω, Q = 4 Ω, R = 3 Ω. The unknown resistance S for balance is:", "options": ["3 Ω × 2", "11 Ω", "1.5 Ω", "3 Ω"], "answer": 3, "explanation": "Balance: P/Q = R/S ⇒ S = QR/P = 4×3/4 = 3 Ω.", "topic": "Physics – Current Electricity"}, {"q": "The density of CO2 at STP (M = 44 g/mol) is approximately:", "options": ["0.98 g/L", "1.96 g/L", "1.96 g/L × 2", "3.93 g/L"], "answer": 1, "explanation": "d = PM/(RT) = 1×44/(0.0821×273) = 1.96 g/L.", "topic": "Chemistry – Gaseous State"}, {"q": "The capacitance of a parallel-plate capacitor increases if:", "options": ["the plate separation increases", "the plate area increases", "the applied voltage increases", "the stored charge increases"], "answer": 1, "explanation": "C = ε₀A/d: larger area (or smaller separation) raises C.", "topic": "Physics – Electrostatics"}, {"q": "The equivalent weight of copper deposited during CuSO₄ electrolysis (atomic mass 63.5) is:", "options": ["63.5", "31.75", "127", "15.9"], "answer": 1, "explanation": "Cu²⁺ + 2e⁻ → Cu, so equivalent weight = 63.5/2 = 31.75.", "topic": "Chemistry – Electrochemistry"}, {"q": "The slope of a velocity–time graph gives:", "options": ["displacement", "acceleration", "force", "momentum"], "answer": 1, "explanation": "Slope = dv/dt = acceleration.", "topic": "Physics – Kinematics"}, {"q": "The polar form of the complex number √3 + i is:", "options": ["2(cos π/6 + i sin π/6)", "2(cos π/3 + i sin π/3)", "4(cos π/6 + i sin π/6)", "(cos π/6 + i sin π/6)"], "answer": 0, "explanation": "r = √(3 + 1) = 2 and θ = tan⁻¹(1/√3) = π/6, so z = 2(cos π/6 + i sin π/6).", "topic": "Maths – Complex Numbers"}, {"q": "The rms value of a sinusoidal alternating current with peak value 10 A is:", "options": ["7.07 A", "10 A", "5 A", "14.14 A"], "answer": 0, "explanation": "I_rms = I_peak/√2 = 10/1.414 ≈ 7.07 A.", "topic": "Physics – EMI & AC"}, {"q": "The distance of the point (3, 4) from the origin is:", "options": ["5", "7", "25", "1"], "answer": 0, "explanation": "d = √(9 + 16) = 5.", "topic": "Maths – Straight Lines"}, {"q": "In the electrolysis of acidulated water, the ratio of the volumes of H₂ and O₂ liberated is:", "options": ["1 : 1", "2 : 1", "1 : 2", "3 : 1"], "answer": 1, "explanation": "2H₂O → 2H₂ + O₂, so H₂ : O₂ = 2 : 1 by moles and by volume.", "topic": "Chemistry – Electrochemistry"}, {"q": "Which of the following is the dimensional formula of magnetic field B is?", "options": ["[MT⁻¹A⁻¹]", "[ML²T⁻²A⁻¹]", "[MT⁻²A⁻¹]", "[MLT⁻²A⁻¹]"], "answer": 2, "explanation": "F = qvB gives B = F/(qv) = [MLT⁻²]/([AT][LT⁻¹]) = [MT⁻²A⁻¹].", "topic": "Physics – Units & Dimensions"}, {"q": "For H₂ + Cl₂ → 2HCl, ΔH = −184 kJ/mol. Given bond enthalpies H–H = 436 kJ/mol and Cl–Cl = 242 kJ/mol, the H–Cl bond enthalpy is:", "options": ["431 kJ/mol", "862 kJ/mol", "339 kJ/mol", "215 kJ/mol"], "answer": 0, "explanation": "ΔH = (436 + 242) − 2×BE(HCl) = −184, so 2×BE = 862 and BE(HCl) = 431 kJ/mol.", "topic": "Chemistry – Thermodynamics"}, {"q": "The point of inflection of the curve y = x³ is:", "options": ["(0, 0)", "(1, 1)", "does not exist", "(−1, −1)"], "answer": 0, "explanation": "y″ = 6x changes sign at x = 0, so (0, 0) is the inflection point.", "topic": "Maths – Applications of Derivatives"}, {"q": "In the steady state, a capacitor blocks:", "options": ["AC only", "DC", "both AC and DC", "neither AC nor DC"], "answer": 1, "explanation": "Once charged, no steady DC current flows; AC passes continuously.", "topic": "Physics – EMI & AC"}, {"q": "For the Al electrode with E° = -1.66 V (n = 3) and ion activity giving Q = 10, the electrode potential at 298 K is:", "options": ["-1.66 V", "-1.64 V", "-1.68 V", "-3.36 V"], "answer": 2, "explanation": "E = E° − (0.0591/n)logQ = -1.66 − (0.0591/3)×log(10) = -1.68 V.", "topic": "Chemistry – Electrochemistry"}, {"q": "The bond order of CN- is:", "options": ["4", "3", "2.5", "3.5"], "answer": 1, "explanation": "Bond order = (bonding − antibonding electrons)/2; for CN- this equals 3.", "topic": "Chemistry – Chemical Bonding"}, {"q": "tan 45° equals:", "options": ["1", "0", "√3", "∞"], "answer": 0, "explanation": "tan 45° = sin45°/cos45° = 1.", "topic": "Maths – Trigonometry"}, {"q": "The number of moles of HCl present in 250 mL of 0.4 M hydrochloric acid is:", "options": ["0.1 mol", "1 mol", "0.4 mol", "0.025 mol"], "answer": 0, "explanation": "Moles = 0.25 L × 0.4 mol/L = 0.1 mol.", "topic": "Chemistry – Solutions"}, {"q": "The radius of a sphere increases at 2 cm/s. The rate of increase of its volume when r = 10 cm is:", "options": ["800π cm³/s", "400π cm³/s", "40π cm³/s", "80π cm³/s"], "answer": 0, "explanation": "dV/dt = 4πr²·dr/dt = 4π × 100 × 2 = 800π cm³/s.", "topic": "Maths – Applications of Derivatives"}, {"q": "Two capacitors of 2 μF and 3 μF are connected in parallel across 100 V. The total charge stored is:", "options": ["500 μC", "120 μC", "250 μC", "1000 μC"], "answer": 0, "explanation": "C_eq = 5 μF; Q = CV = 5 × 100 = 500 μC.", "topic": "Physics – Capacitors"}, {"q": "The moment of inertia of a uniform rod of mass M and length L about an axis through its centre perpendicular to its length is:", "options": ["ML²/12", "ML²/3", "ML²/2", "2ML²/3"], "answer": 0, "explanation": "Standard result: I_centre = ML²/12.", "topic": "Physics – Rotational Motion"}, {"q": "The value of ∫₀^π sin x dx is:", "options": ["2", "0", "1", "π"], "answer": 0, "explanation": "∫sin x dx = −cos x; evaluated 0 to π: (−cos π) − (−cos 0) = 1 + 1 = 2.", "topic": "Maths – Definite Integrals (numerical)"}, {"q": "If |z| = 7 for a complex number z, then |z̄| equals:", "options": ["−7", "7", "49", "1/7"], "answer": 1, "explanation": "A complex number and its conjugate have the same modulus, so |z̄| = 7.", "topic": "Maths – Complex Numbers"}, {"q": "If one root of x² − 5x + 6 = 0 is 2, then the other root is:", "options": ["4", "3", "−2", "1"], "answer": 1, "explanation": "The sum of the roots is 5, so the other root is 5 − 2 = 3.", "topic": "Maths – Quadratic Equations"}, {"q": "The number of moles in 49 g of H2SO4 (molar mass 98 g/mol) is:", "options": ["0.5 mol", "1 mol", "4802 mol", "0.25 mol"], "answer": 0, "explanation": "n = mass/molar mass = 49/98 = 0.5 mol.", "topic": "Chemistry – Mole Concept"}, {"q": "The coefficient of x⁵ in the expansion of (2x − 3)⁸ is:", "options": ["48384", "−16128", "−48384", "24192"], "answer": 2, "explanation": "T_(r+1) = C(8, r)(2x)^(8−r)(−3)^r. For x⁵, 8−r = 5 gives r = 3. Coefficient = C(8,3)·2⁵·(−3)³ = 56 × 32 × (−27) = −48384.", "topic": "Maths – Binomial Theorem"}, {"q": "The work done in moving a point charge slowly around any closed loop in an electrostatic field is:", "options": ["qV", "zero", "infinite", "2qV"], "answer": 1, "explanation": "The electrostatic field is conservative, so work over a closed path is zero.", "topic": "Physics – Electrostatics"}, {"q": "The eccentricity of the rectangular hyperbola x² − y² = 25 is:", "options": ["2", "1/√2", "1", "√2"], "answer": 3, "explanation": "For x²/a² − y²/b² = 1 with a = b, e = √(1 + b²/a²) = √2.", "topic": "Maths – Conic Sections"}, {"q": "The total angular momentum of a system is conserved when:", "options": ["the net external force is zero", "the net external torque is zero", "the total energy is conserved", "always, without exception"], "answer": 1, "explanation": "dL/dt = τ_ext, so L is conserved when τ_ext = 0.", "topic": "Physics – Rotational Motion"}, {"q": "If y = x·e^x, then dy/dx equals:", "options": ["(1 + x)", "e^x", "e^x(1 + x)", "xe^x"], "answer": 2, "explanation": "Product rule: dy/dx = e^x + xe^x = e^x(1 + x).", "topic": "Maths – Differentiation"}, {"q": "If the net external force acting on a system is zero, which quantity is conserved?", "options": ["kinetic energy", "linear momentum", "potential energy", "angular displacement"], "answer": 1, "explanation": "With F_ext = 0, dp/dt = 0, so total linear momentum is conserved.", "topic": "Physics – Laws of Motion"}, {"q": "The average kinetic energy of one molecule of an ideal gas at temperature T is:", "options": ["(3/2)kT", "3RT", "kT", "(3/2)RT"], "answer": 0, "explanation": "Equipartition: (3/2)kT per molecule ((3/2)RT per mole).", "topic": "Physics – Kinetic Theory"}, {"q": "The de Broglie wavelength of a 1 kg ball moving at 1 m/s is (h = 6.63×10⁻³⁴ J·s):", "options": ["6.63×10⁻³⁴ m", "6.63×10⁻³⁴ nm", "1 m", "3×10⁸ m"], "answer": 0, "explanation": "λ = h/mv = 6.63×10⁻³⁴/1 = 6.63×10⁻³⁴ m — negligibly small for macroscopic objects.", "topic": "Physics – Modern Physics"}, {"q": "Human blood pH (~7.4) is maintained mainly by the:", "options": ["phosphate buffer", "bicarbonate buffer", "acetate buffer", "ammonia buffer"], "answer": 1, "explanation": "The H₂CO₃/HCO₃⁻ (bicarbonate) system is the chief blood buffer.", "topic": "Chemistry – Equilibrium"}, {"q": "Kirchhoff's current law (sum of currents at a junction = 0) is a consequence of conservation of:", "options": ["energy", "charge", "momentum", "mass"], "answer": 1, "explanation": "Charge cannot accumulate at a junction, so inflow = outflow.", "topic": "Physics – Current Electricity"}, {"q": "The derivative of (x² + 1)/x with respect to x is:", "options": ["2x", "1 − 1/x²", "2x/x²", "(x² + 1)/x²"], "answer": 1, "explanation": "(x² + 1)/x = x + x⁻¹, whose derivative is 1 − x⁻² = 1 − 1/x².", "topic": "Maths – Differentiation"}, {"q": "For the reaction H₂ + I₂ ⇌ 2HI, if the reaction quotient Qc is less than Kc, the reaction proceeds:", "options": ["in the backward direction", "in the forward direction", "stays at equilibrium", "stops completely"], "answer": 1, "explanation": "Qc < Kc means more products must form to reach equilibrium.", "topic": "Chemistry – Equilibrium"}, {"q": "Carbon-14 has a half-life of 5730 years. Its decay constant is approximately:", "options": ["1.21×10⁻⁴ yr⁻¹", "3.96×10³ yr⁻¹", "0.693 yr⁻¹", "8.27×10³ yr⁻¹"], "answer": 0, "explanation": "λ = 0.693/t½ = 0.693/5730 ≈ 1.21×10⁻⁴ yr⁻¹.", "topic": "Physics – Modern Physics (numerical)"}, {"q": "A source of sound approaches a stationary observer. The observed frequency:", "options": ["increases", "becomes zero", "decreases", "remains unchanged"], "answer": 0, "explanation": "Approaching source compresses wavefronts: f' = f·v/(v − v_s) > f.", "topic": "Physics – Waves"}, {"q": "Haematite is an ore of:", "options": ["copper", "iron", "zinc", "aluminium"], "answer": 1, "explanation": "Haematite Fe2O3 is a major iron ore.", "topic": "Chemistry – s, p, d & f Block"}, {"q": "Which of the following is the dimensional formula of gravitational constant G is?", "options": ["[ML³T⁻²]", "[M⁻¹L³T⁻¹]", "[M⁻¹L²T⁻²]", "[M⁻¹L³T⁻²]"], "answer": 3, "explanation": "G = Fr²/m² gives [MLT⁻²][L²]/[M²] = [M⁻¹L³T⁻²].", "topic": "Physics – Units & Dimensions"}, {"q": "The bond angle in BF3 is:", "options": ["180°", "90°", "109.5°", "120°"], "answer": 3, "explanation": "Trigonal planar geometry gives 120° bond angles.", "topic": "Chemistry – Chemical Bonding"}, {"q": "In non-uniform circular motion, the tangential component of acceleration arises due to:", "options": ["change in direction", "change in speed", "the centripetal force", "friction always"], "answer": 1, "explanation": "Tangential acceleration equals the rate of change of speed; the radial component changes direction.", "topic": "Physics – Circular Motion"}, {"q": "The hybridization of sulphur in SF6 is:", "options": ["sp³", "sp³d²", "d²sp³ (inner)", "sp³d"], "answer": 1, "explanation": "SF6 has 6 bond pairs → octahedral, sp³d².", "topic": "Chemistry – Chemical Bonding"}, {"q": "A wire of original length L is stretched until its length becomes 2L. The longitudinal strain is:", "options": ["1", "2", "0.5", "4"], "answer": 0, "explanation": "Strain = ΔL/L = L/L = 1.", "topic": "Physics – Elasticity"}, {"q": "The oxidation number of O in H2O2 is:", "options": ["+1", "−2", "−1", "0"], "answer": 2, "explanation": "2(+1) + 2x = 0 ⇒ x = −1 (peroxide linkage).", "topic": "Chemistry – Redox Reactions"}, {"q": "The value of ∫₋₁^₁ |x| dx is:", "options": ["0", "1", "2", "0.5"], "answer": 1, "explanation": "|x| is even, so the integral equals 2∫₀¹ x dx = 2 × 1/2 = 1.", "topic": "Maths – Definite Integrals"}, {"q": "If z = 1 − i, then z² equals:", "options": ["2i", "−2i", "2", "0"], "answer": 1, "explanation": "z² = (1 − i)² = 1 − 2i + i² = −2i.", "topic": "Maths – Complex Numbers"}, {"q": "A body moves with constant speed along a circular path. Its velocity:", "options": ["is constant", "changes continuously in direction", "is zero", "changes in magnitude only"], "answer": 1, "explanation": "Speed is constant but direction changes, so velocity changes.", "topic": "Physics – Kinematics"}, {"q": "The functional group –CONH2 is called:", "options": ["nitrile", "amide", "imide", "amine"], "answer": 1, "explanation": "–CONH2 is the amide functional group.", "topic": "Chemistry – Organic Chemistry"}, {"q": "For a third-order reaction, the unit of the rate constant k is:", "options": ["s⁻¹", "L·mol⁻¹·s⁻¹", "mol·L⁻¹·s⁻¹", "L²·mol⁻²·s⁻¹"], "answer": 3, "explanation": "k = rate/[A]³ gives (mol·L⁻¹·s⁻¹)/(mol³·L⁻³) = L²·mol⁻²·s⁻¹.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "For a refrigerator, the coefficient of performance is defined as:", "options": ["W/Q₂", "Q₂/W", "Q₁/Q₂", "W/Q₁"], "answer": 1, "explanation": "COP = heat extracted from the cold reservoir / work input = Q₂/W.", "topic": "Physics – Thermodynamics"}, {"q": "If y = e^(2x), then dy/dx equals:", "options": ["e^(2x)", "2e^(2x)", "2xe^(2x)", "e^x"], "answer": 1, "explanation": "Chain rule: dy/dx = 2e^(2x).", "topic": "Maths – Differentiation"}, {"q": "Which oxide is most basic?", "options": ["Na₂O", "SiO₂", "Al₂O₃", "MgO"], "answer": 0, "explanation": "Basic character of oxides decreases across a period; Na₂O is the most basic.", "topic": "Chemistry – Periodic Table"}, {"q": "Two fair coins are tossed together. The probability of getting at least one head is:", "options": ["1/2", "1/4", "3/4", "1"], "answer": 2, "explanation": "Favourable outcomes HH, HT, TH out of 4, so P = 3/4.", "topic": "Maths – Probability"}, {"q": "The circles x² + y² = 4 and (x − 3)² + y² = 4 intersect each other:", "options": ["externally at one point", "internally at one point", "at two points", "not at all"], "answer": 2, "explanation": "Centres are 3 apart; radii 2 and 2 satisfy |2 − 2| < 3 < 2 + 2, so they meet at two points.", "topic": "Maths – Circles"}, {"q": "The probability of getting a head when a fair coin is tossed twice (at least one head) is:", "options": ["1/2", "1", "3/4", "1/4"], "answer": 2, "explanation": "Outcomes: HH, HT, TH, TT — 3 of 4 have at least one head.", "topic": "Maths – Probability"}, {"q": "For A = [[2, 0], [0, 3]], the (2, 2)-entry of A⁻¹ is:", "options": ["3", "1/2", "1/3", "−1/3"], "answer": 2, "explanation": "The inverse of a diagonal matrix inverts each diagonal entry: (A⁻¹)₂₂ = 1/3.", "topic": "Maths – Matrices & Determinants (numerical)"}, {"q": "The radius of gyration of a thin circular ring of radius R about its central axis perpendicular to its plane is:", "options": ["R", "R/√2", "2R", "R/2"], "answer": 0, "explanation": "I = MR² = Mk² gives k = R.", "topic": "Physics – Rotational Motion"}, {"q": "A card is drawn at random from a well-shuffled deck of 52 cards. The probability that it is a king is:", "options": ["1/13", "1/4", "4/13", "1/52"], "answer": 0, "explanation": "4 kings out of 52 cards: P = 4/52 = 1/13.", "topic": "Maths – Probability"}, {"q": "The Balmer series of hydrogen corresponds to electronic transitions ending at n equal to:", "options": ["1", "2", "3", "4"], "answer": 1, "explanation": "Balmer lines (visible) end at the n = 2 level.", "topic": "Chemistry – Atomic Structure"}, {"q": "∫ dx/x equals:", "options": ["ln|x| + C", "1/x² + C", "x + C", "−1/x² + C"], "answer": 0, "explanation": "The antiderivative of 1/x is ln|x| + C.", "topic": "Maths – Indefinite Integrals"}, {"q": "The oxidation number of N in NH4NO3 (ammonium N) is:", "options": ["−3", "+3", "+5", "0"], "answer": 0, "explanation": "In NH4⁺: x + 4(+1) = +1 ⇒ x = −3 (the nitrate N is +5).", "topic": "Chemistry – Redox Reactions"}, {"q": "In a galvanic (voltaic) cell, oxidation takes place at the:", "options": ["cathode", "anode", "salt bridge", "electrolyte"], "answer": 1, "explanation": "Oxidation always occurs at the anode (an ox).", "topic": "Chemistry – Electrochemistry"}, {"q": "Electron affinity is highest for:", "options": ["F", "I", "Br", "Cl"], "answer": 3, "explanation": "Chlorine has the highest electron affinity (F's small size causes electron–electron repulsion).", "topic": "Chemistry – Periodic Table"}, {"q": "The van't Hoff factor for the complete dissociation of NaCl in water is:", "options": ["1", "2", "3", "0.5"], "answer": 1, "explanation": "NaCl → Na⁺ + Cl⁻ gives 2 particles per formula unit, so i = 2.", "topic": "Chemistry – Solutions"}, {"q": "The ratio of rates of effusion of H2 to O2 is:", "options": ["0.25", "16", "4", "2"], "answer": 2, "explanation": "Graham's law: r₁/r₂ = √(M₂/M₁) = √(32/2) = 4.", "topic": "Chemistry – Gaseous State"}, {"q": "The impedance of a series LCR circuit is minimum at:", "options": ["zero frequency", "resonance", "infinite frequency", "half the resonant frequency"], "answer": 1, "explanation": "At resonance X_L = X_C, so Z = R is minimum.", "topic": "Physics – EMI & AC"}, {"q": "In the expansion of (2 + x)^4, the constant term is:", "options": ["16", "8", "4", "32"], "answer": 0, "explanation": "The constant term is C(4, 0)·2⁴ = 16.", "topic": "Maths – Binomial Theorem"}, {"q": "For the equilibrium N₂ + 3H₂ ⇌ 2NH₃, increasing the total pressure shifts the equilibrium:", "options": ["towards the reactants", "towards the products", "in neither direction", "equally both ways"], "answer": 1, "explanation": "Higher pressure favours the side with fewer gas moles (2 < 4): towards NH₃.", "topic": "Chemistry – Equilibrium"}, {"q": "The equation x² + y² + 2gx + 2fy + c = 0 represents a real circle only if:", "options": ["g² + f² − c > 0", "g² + f² − c = 0", "g² + f² − c < 0", "c > 0"], "answer": 0, "explanation": "Radius = √(g² + f² − c) must be real and non-zero, so g² + f² − c > 0.", "topic": "Maths – Circles"}, {"q": "A pendulum clock runs slow on hot summer days mainly because:", "options": ["its length decreases", "its length increases", "g increases", "its amplitude increases"], "answer": 1, "explanation": "Thermal expansion increases the pendulum length, and T = 2π√(l/g) increases.", "topic": "Physics – Oscillations"}, {"q": "A unit vector makes equal angles with the positive x, y and z axes. Each such angle is:", "options": ["cos⁻¹(1/√3)", "45°", "60°", "cos⁻¹(1/3)"], "answer": 0, "explanation": "Direction cosines satisfy 3cos²α = 1, so cos α = 1/√3.", "topic": "Physics – Vectors"}, {"q": "A function f is continuous at x = a if which condition holds?", "options": ["lim(x→a) f(x) = f(a)", "f(a) = 0", "lim(x→a) f(x) = 0", "f is differentiable at a"], "answer": 0, "explanation": "Continuity at a means the limit equals the function value.", "topic": "Maths – Limits"}, {"q": "The number of moles in 588 g of K2Cr2O7 (molar mass 294 g/mol) is:", "options": ["4 mol", "2 mol", "172872 mol", "1 mol"], "answer": 1, "explanation": "n = mass/molar mass = 588/294 = 2 mol.", "topic": "Chemistry – Mole Concept"}, {"q": "The order of the differential equation (d²y/dx²)³ + dy/dx = 0 is:", "options": ["6", "2", "3", "1"], "answer": 1, "explanation": "Order = highest derivative present = d²y/dx² → order 2 (power 3 is the degree).", "topic": "Maths – Differential Equations"}, {"q": "Charles's law relates which two variables (others held constant)?", "options": ["pressure and volume", "volume and temperature", "pressure and temperature", "moles and volume"], "answer": 1, "explanation": "Charles's law: V ∝ T at constant pressure.", "topic": "Chemistry – Gaseous State"}, {"q": "Which statement about electric field lines is correct?", "options": ["They form closed loops", "They never intersect each other", "They start on negative charges", "They are always circular"], "answer": 1, "explanation": "Field lines never cross; at an intersection the field would have two directions.", "topic": "Physics – Electrostatics"}, {"q": "A disc rolls without slipping with its centre moving at speed v. The speed of its topmost point relative to the ground is:", "options": ["v", "2v", "0", "v/2"], "answer": 1, "explanation": "Top point: v_centre + v_rotation = v + v = 2v.", "topic": "Physics – Rotational Motion"}, {"q": "The pOH of a 0.01 M NaOH solution is:", "options": ["2", "12", "10", "1"], "answer": 0, "explanation": "[OH⁻] = 10⁻² M, so pOH = 2.", "topic": "Chemistry – Equilibrium"}, {"q": "One electron-volt (1 eV) is equal to:", "options": ["1.6×10⁻¹⁹ J", "1.6×10¹⁹ J", "9.1×10⁻³¹ J", "3×10⁸ J"], "answer": 0, "explanation": "1 eV = charge of electron × 1 V = 1.6×10⁻¹⁹ J.", "topic": "Physics – Electrostatics"}, {"q": "For a zero-order reaction, the half-life is proportional to:", "options": ["1/[A]₀", "[A]₀", "1/[A]₀²", "nothing; it is constant"], "answer": 1, "explanation": "t½ = [A]₀/2k for zero order, so t½ ∝ [A]₀.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "A rectangular current loop placed in a uniform magnetic field experiences:", "options": ["zero net force but a torque", "a net force", "neither force nor torque", "only a net force"], "answer": 0, "explanation": "Forces on opposite sides cancel (net F = 0) but form a couple giving torque NIAB sin θ.", "topic": "Physics – Magnetism"}, {"q": "An electron with n = 4, l = 1, m = −1 is in which orbital?", "options": ["3p", "4s", "4d", "4p"], "answer": 3, "explanation": "l = 1 denotes a p orbital with n = 4.", "topic": "Chemistry – Atomic Structure"}, {"q": "If ∫₀¹ f(x) dx = 3 and ∫₀² f(x) dx = 8, then ∫₁² f(x) dx equals:", "options": ["11", "5", "3", "8/3"], "answer": 1, "explanation": "∫₀² = ∫₀¹ + ∫₁², so ∫₁² f(x) dx = 8 − 3 = 5.", "topic": "Maths – Definite Integrals"}, {"q": "The values of λ for which det [[λ, 2], [3, λ]] = 0 must satisfy:", "options": ["λ² = 6", "λ² = −6", "λ = 3", "λ² + 6 = 0"], "answer": 0, "explanation": "det = λ² − 6 = 0, so λ² = 6.", "topic": "Maths – Matrices & Determinants"}, {"q": "Which of the following is the dimensional formula of force is?", "options": ["[MLT⁻¹]", "[MLT⁻²]", "[ML⁻¹T⁻²]", "[ML²T⁻²]"], "answer": 1, "explanation": "F = ma gives [M][LT⁻²] = [MLT⁻²].", "topic": "Physics – Units & Dimensions"}, {"q": "∫ (3x² + 2x) dx equals:", "options": ["x³ + x² + C", "6x + 2 + C", "x³ + 2x² + C", "3x³ + x² + C"], "answer": 0, "explanation": "Integrate termwise: 3x³/3 + 2x²/2 + C = x³ + x² + C.", "topic": "Maths – Indefinite Integrals"}, {"q": "The bond order of N2 is:", "options": ["3.5", "3", "4", "2.5"], "answer": 1, "explanation": "Bond order = (bonding − antibonding electrons)/2; for N2 this equals 3.", "topic": "Chemistry – Chemical Bonding"}, {"q": "X-rays are produced when:", "options": ["fast-moving electrons strike a metal target", "a gas is heated gently", "a magnet is moved near a coil", "light reflects off a mirror"], "answer": 0, "explanation": "Bombarding a metal target with energetic electrons produces X-rays.", "topic": "Physics – Modern Physics"}, {"q": "A voltmeter is connected in a circuit:", "options": ["in series and has low resistance", "in parallel and has high resistance", "in series and has high resistance", "in parallel and has low resistance"], "answer": 1, "explanation": "Parallel connection measures p.d.; high resistance avoids drawing current.", "topic": "Physics – Current Electricity"}, {"q": "The escape velocity from Earth's surface (R = 6400 km, g = 10 m/s²) is approximately:", "options": ["8 km/s", "16 km/s", "7.9 km/s", "11.3 km/s"], "answer": 3, "explanation": "v_e = √(2gR) = √(2×10×6.4×10⁶) ≈ 11.3 km/s.", "topic": "Physics – Gravitation"}, {"q": "The resistivity of a metallic wire depends on:", "options": ["its length", "its cross-sectional area", "the material and the temperature", "the current through it"], "answer": 2, "explanation": "Resistivity is a material property varying with temperature, not geometry.", "topic": "Physics – Current Electricity"}, {"q": "Water flows through a pipe of cross-section 4 cm² at 2 m/s into a section of 1 cm². The speed there is:", "options": ["2 m/s", "8 m/s", "0.5 m/s", "16 m/s"], "answer": 1, "explanation": "Continuity: A₁v₁ = A₂v₂ ⇒ v₂ = 4×2/1 = 8.0 m/s.", "topic": "Physics – Fluid Mechanics"}, {"q": "∫ √x dx equals:", "options": ["(2/3)x^{3/2} + C", "2x^{3/2} + C", "(3/2)x^{3/2} + C", "x^{3/2}/2 + C"], "answer": 0, "explanation": "∫x^{1/2}dx = x^{3/2}/(3/2) + C = (2/3)x^{3/2} + C.", "topic": "Maths – Indefinite Integrals"}, {"q": "Ozonolysis of 2-butene followed by Zn/H2O gives:", "options": ["2 molecules of formaldehyde", "1 molecule of butanedione", "acetic acid", "2 molecules of acetaldehyde"], "answer": 3, "explanation": "Each =CHCH3 fragment becomes CH3CHO; two fragments → 2 acetaldehyde.", "topic": "Chemistry – Organic Chemistry"}, {"q": "If cos x = 4/5, then cos 2x equals:", "options": ["7/25", "9/25", "16/25", "24/25"], "answer": 0, "explanation": "cos 2x = 2cos²x − 1 = 2(16/25) − 1 = 7/25.", "topic": "Maths – Trigonometry"}, {"q": "The oxidation number of Cr in K2Cr2O7 is:", "options": ["+6", "+7", "+3", "+4"], "answer": 0, "explanation": "2(+1) + 2x + 7(−2) = 0 ⇒ x = +6.", "topic": "Chemistry – Redox Reactions"}, {"q": "If the third term in the expansion of (1 + x)^n is 6x², then n equals:", "options": ["4", "3", "6", "5"], "answer": 0, "explanation": "T₃ = C(n, 2)x² = 6x² gives n(n−1)/2 = 6, so n = 4.", "topic": "Maths – Binomial Theorem"}, {"q": "Two non-vertical lines in a plane are parallel if and only if their slopes are:", "options": ["equal", "negative reciprocals of each other", "both zero", "both infinite"], "answer": 0, "explanation": "Parallel lines have equal slopes.", "topic": "Maths – Straight Lines"}, {"q": "A constant force of 10 N displaces a body by 5 m at an angle of 60° to the force. The work done is:", "options": ["25 J", "50 J", "43.3 J", "0 J"], "answer": 0, "explanation": "W = Fd cos θ = 10 × 5 × 0.5 = 25 J.", "topic": "Physics – Work, Energy & Power"}, {"q": "If the molecular diameter of a gas is doubled while the number density stays the same, the mean free path becomes:", "options": ["One-fourth of the original", "Half of the original", "Twice the original", "Four times the original"], "answer": 0, "explanation": "Mean free path is inversely proportional to the square of the molecular diameter, so doubling the diameter cuts it to one-fourth.", "topic": "Physics – Kinetic Theory"}, {"q": "At constant temperature, if the pressure of an ideal gas is doubled, the mean free path of its molecules:", "options": ["Doubles", "Halves", "Remains unchanged", "Becomes zero"], "answer": 1, "explanation": "Mean free path λ = kT/(√2 π d² P), so at constant temperature λ is inversely proportional to pressure P; doubling P halves λ.", "topic": "Physics – Kinetic Theory"}, {"q": "The average translational kinetic energy of one mole of a monatomic ideal gas at 300 K is about: (R = 8.314 J/mol·K)", "options": ["2.49 kJ", "7.48 kJ", "3.74 kJ", "1.25 kJ"], "answer": 2, "explanation": "Average kinetic energy per mole equals (3/2)RT = 1.5 × 8.314 × 300 ≈ 3741 J, about 3.74 kJ.", "topic": "Physics – Kinetic Theory"}, {"q": "The ratio of the rms speeds of H2 molecules to O2 molecules at the same temperature is:", "options": ["1:16", "16:1", "1:4", "4:1"], "answer": 3, "explanation": "rms speed is inversely proportional to the square root of molar mass, so the ratio is √(32/2) = 4:1 in favour of H2.", "topic": "Physics – Kinetic Theory"}, {"q": "The ratio of the most probable speed to the rms speed of gas molecules is:", "options": ["0.816", "0.921", "1.128", "1.414"], "answer": 0, "explanation": "Most probable speed is √(2RT/M) and rms speed is √(3RT/M), so their ratio is √(2/3) ≈ 0.816.", "topic": "Physics – Kinetic Theory"}, {"q": "The pressure of an ideal gas in a rigid container is doubled. Its rms molecular speed:", "options": ["Remains unchanged", "Increases by a factor of √2", "Doubles", "Increases by a factor of 2√2"], "answer": 1, "explanation": "At constant volume, doubling the pressure doubles the absolute temperature, and rms speed scales as √T, so it rises by √2.", "topic": "Physics – Kinetic Theory"}, {"q": "The average translational kinetic energy of 1 g of helium (M = 4 g/mol) at 300 K is about:", "options": ["467 J", "1.87 kJ", "935 J", "3.74 kJ"], "answer": 2, "explanation": "1 g of He is 0.25 mol; kinetic energy = 0.25 × (3/2)RT = 0.25 × 3741 J ≈ 935 J.", "topic": "Physics – Kinetic Theory"}, {"q": "Two moles of a monatomic ideal gas are heated at constant volume through 50 K. The heat absorbed is about:", "options": ["623 J", "2.49 kJ", "831 J", "1.25 kJ"], "answer": 3, "explanation": "At constant volume Q = nCvΔT = 2 × (3R/2) × 50 = 150R ≈ 1247 J, about 1.25 kJ.", "topic": "Physics – Kinetic Theory"}, {"q": "Ammonia (M = 17) effuses through a pinhole roughly how many times faster than hydrogen chloride (M = 36.5)?", "options": ["1.47", "0.68", "2.15", "1.21"], "answer": 0, "explanation": "By Graham's law the effusion rate is inversely proportional to √M, so the ratio is √(36.5/17) ≈ 1.47.", "topic": "Physics – Kinetic Theory"}, {"q": "How many degrees of freedom does a nonlinear triatomic gas molecule have (ignoring vibrations)?", "options": ["3", "6", "5", "9"], "answer": 1, "explanation": "A nonlinear molecule has 3 translational and 3 rotational degrees of freedom: 6 in all.", "topic": "Physics – Kinetic Theory"}, {"q": "The molar heat capacity at constant volume of a diatomic gas at room temperature is about:", "options": ["12.5 J/mol·K", "16.6 J/mol·K", "20.8 J/mol·K", "24.9 J/mol·K"], "answer": 2, "explanation": "With 5 degrees of freedom, Cv = (5/2)R = 2.5 × 8.314 ≈ 20.8 J/mol·K.", "topic": "Physics – Kinetic Theory"}, {"q": "A gas at 27 °C has rms speed v. The temperature in °C at which its rms speed becomes 2v is:", "options": ["54 °C", "600 °C", "1200 °C", "927 °C"], "answer": 3, "explanation": "rms speed scales as √T, so T must quadruple: 300 K → 1200 K, which is 927 °C.", "topic": "Physics – Kinetic Theory"}, {"q": "In the van der Waals equation, the constant b for one mole of gas equals:", "options": ["Four times the actual molecular volume", "Half the actual molecular volume", "The actual molecular volume", "Twice the container volume"], "answer": 0, "explanation": "The excluded volume b is four times the actual volume occupied by the molecules themselves.", "topic": "Physics – Kinetic Theory"}, {"q": "The pressure exerted by an ideal gas equals:", "options": ["One-third of the translational kinetic energy per unit volume", "Two-thirds of the translational kinetic energy per unit volume", "The translational kinetic energy per unit volume", "Twice the translational kinetic energy per unit volume"], "answer": 1, "explanation": "Kinetic theory gives P = (2/3)E where E is the translational kinetic energy density.", "topic": "Physics – Kinetic Theory"}, {"q": "A mixture of 2 mol He and 3 mol O2 is at temperature T. Its total internal energy is:", "options": ["8RT", "9.5RT", "10.5RT", "12RT"], "answer": 2, "explanation": "He contributes (3/2)(2)RT = 3RT and O2 contributes (5/2)(3)RT = 7.5RT, for a total of 10.5RT.", "topic": "Physics – Kinetic Theory"}, {"q": "The rms speed of nitrogen molecules (M = 28 g/mol) at 300 K is approximately:", "options": ["422 m/s", "476 m/s", "596 m/s", "517 m/s"], "answer": 3, "explanation": "v_rms = √(3RT/M) = √(3 × 8.314 × 300 / 0.028) ≈ 517 m/s.", "topic": "Physics – Kinetic Theory"}, {"q": "A particle walks 10 m due east and then returns to the starting point along the same line, taking 4 s in all. Its average velocity is:", "options": ["0", "2.5 m/s east", "5 m/s west", "2.5 m/s west"], "answer": 0, "explanation": "Average velocity is total displacement over total time; the particle returns to its start, so displacement is zero.", "topic": "Physics – Kinematics"}, {"q": "A velocity–time graph is a symmetric triangle with peak 20 m/s and total base 10 s. The displacement is:", "options": ["50 m", "100 m", "200 m", "20 m"], "answer": 1, "explanation": "Displacement is the area under the v–t graph: (1/2) × 10 × 20 = 100 m.", "topic": "Physics – Kinematics"}, {"q": "Two trains move towards each other at 40 m/s and 60 m/s. The speed of one as seen from the other is:", "options": ["20 m/s", "50 m/s", "100 m/s", "140 m/s"], "answer": 2, "explanation": "For motion in opposite directions the relative speed is the sum: 40 + 60 = 100 m/s.", "topic": "Physics – Kinematics"}, {"q": "A particle's velocity is v = 3t² − 2t (SI units). Its acceleration at t = 2 s is:", "options": ["6 m/s²", "8 m/s²", "12 m/s²", "10 m/s²"], "answer": 3, "explanation": "Acceleration is dv/dt = 6t − 2; at t = 2 s this is 12 − 2 = 10 m/s².", "topic": "Physics – Kinematics"}, {"q": "A particle's position is x = 4t³ − 6t (SI units). Its velocity at t = 1 s is:", "options": ["6 m/s", "2 m/s", "−2 m/s", "18 m/s"], "answer": 0, "explanation": "Velocity is dx/dt = 12t² − 6; at t = 1 s this is 12 − 6 = 6 m/s.", "topic": "Physics – Kinematics"}, {"q": "A body falls freely from rest (g = 10 m/s²). The distance it covers during the 3rd second of fall is:", "options": ["15 m", "25 m", "35 m", "45 m"], "answer": 1, "explanation": "Distance in the nth second is (g/2)(2n − 1); for n = 3 this is 5 × 5 = 25 m.", "topic": "Physics – Kinematics"}, {"q": "A car brakes to rest with constant deceleration. If its initial speed is doubled, the stopping distance becomes:", "options": ["Doubled", "Halved", "Quadrupled", "Unchanged"], "answer": 2, "explanation": "From v² = 2as, the stopping distance is proportional to v², so doubling v quadruples the distance.", "topic": "Physics – Kinematics"}, {"q": "Two stones are dropped from the same height 1 s apart. When the first has been falling for 3 s (g = 10 m/s²), their separation is:", "options": ["5 m", "15 m", "10 m", "25 m"], "answer": 3, "explanation": "Positions: (1/2)g(3²) and (1/2)g(2²); the separation is 5 × (9 − 4) = 25 m.", "topic": "Physics – Kinematics"}, {"q": "Vectors a and b have magnitudes 3 and 4 units with 30° between them. The magnitude of a × b is:", "options": ["6", "12", "6√3", "3"], "answer": 0, "explanation": "|a × b| = |a||b|sin θ = 3 × 4 × sin 30° = 12 × 0.5 = 6.", "topic": "Physics – Vectors"}, {"q": "A unit vector in the direction of 6i − 8j is:", "options": ["0.8i + 0.6j", "0.6i − 0.8j", "6i − 8j", "(i − j)/√2"], "answer": 1, "explanation": "The magnitude of 6i − 8j is 10, so the unit vector is (6i − 8j)/10 = 0.6i − 0.8j.", "topic": "Physics – Vectors"}, {"q": "For a = 2i − j and b = 3i + 4j, the dot product a · b equals:", "options": ["10", "−2", "2", "14"], "answer": 2, "explanation": "a · b = (2)(3) + (−1)(4) = 6 − 4 = 2.", "topic": "Physics – Vectors"}, {"q": "The scalar triple product [a b c] = a · (b × c) represents, geometrically:", "options": ["The area of the triangle formed by vectors a, b and c", "The volume of the parallelepiped formed by vectors a, b and c", "The surface area of the parallelepiped formed by vectors a, b and c", "The length of the diagonal of the parallelepiped formed by a, b and c"], "answer": 1, "explanation": "a · (b × c) equals the volume of the parallelepiped with coterminous edges a, b and c; it vanishes when the three vectors are coplanar.", "topic": "Physics – Vectors"}, {"q": "Two equal forces F act at 60° to each other. The magnitude of their resultant is:", "options": ["F√3", "F√2", "2F", "F"], "answer": 0, "explanation": "Resultant² = F² + F² + 2F²cos 60° = 3F², so the resultant is F√3.", "topic": "Physics – Vectors"}, {"q": "A vector makes angles α, β and γ with the positive x, y and z axes respectively. The value of cos²α + cos²β + cos²γ is:", "options": ["0", "1", "2", "3"], "answer": 1, "explanation": "The direction cosines of a vector r are cos α = r_x/|r|, cos β = r_y/|r|, cos γ = r_z/|r|; squaring and adding gives (r_x² + r_y² + r_z²)/|r|² = 1.", "topic": "Physics – Vectors"}, {"q": "If l, m, n are the direction cosines of a line, then l² + m² + n² equals:", "options": ["0", "3", "1", "2"], "answer": 2, "explanation": "Direction cosines are the components of a unit vector, so their squares sum to 1.", "topic": "Physics – Vectors"}, {"q": "Two vectors of magnitudes 6 and 8 units have 60° between them. The magnitude of their difference is about:", "options": ["10", "14", "2", "7.2"], "answer": 3, "explanation": "|a − b|² = 36 + 64 − 2(6)(8)cos 60° = 100 − 48 = 52, so |a − b| = √52 ≈ 7.2.", "topic": "Physics – Vectors"}, {"q": "If the scalar triple product [a b c] = 0, the three vectors are:", "options": ["Coplanar", "Mutually perpendicular", "Collinear", "Of equal magnitude"], "answer": 0, "explanation": "A zero scalar triple product means zero volume of the parallelepiped, so the vectors lie in one plane.", "topic": "Physics – Vectors"}, {"q": "The acceleration due to gravity at a depth of R/2 below Earth's surface (R = Earth's radius) is:", "options": ["g", "g/2", "g/4", "2g"], "answer": 1, "explanation": "Inside Earth, g varies linearly with distance from the centre: g′ = g(1 − d/R) = g(1 − 1/2) = g/2.", "topic": "Physics – Gravitation"}, {"q": "A planet has twice the radius and twice the density of Earth. The escape velocity from its surface is (Earth's escape velocity = 11.2 km/s):", "options": ["31.7 km/s", "11.2 km/s", "22.4 km/s", "15.8 km/s"], "answer": 0, "explanation": "v_e = √(2GM/R) with M = (4/3)πR³ρ gives v_e proportional to R√ρ. Doubling both R and ρ multiplies v_e by 2√2 ≈ 2.83, so v_e ≈ 11.2 × 2.83 = 31.7 km/s.", "topic": "Physics – Gravitation"}, {"q": "For a satellite at a given height, the ratio of escape velocity to orbital velocity is:", "options": ["1/√2", "2", "1/2", "√2"], "answer": 3, "explanation": "Escape velocity is √(2GM/r) and orbital velocity is √(GM/r), so their ratio is √2.", "topic": "Physics – Gravitation"}, {"q": "A planet orbits its star at twice Earth's orbital radius (same star). Its year is about:", "options": ["2.83T", "2T", "4T", "8T"], "answer": 0, "explanation": "By Kepler's third law T² ∝ r³, so doubling r multiplies T by 2√2 ≈ 2.83.", "topic": "Physics – Gravitation"}, {"q": "A 60 kg astronaut on the Moon (g_moon ≈ 1.67 m/s²) weighs about:", "options": ["600 N", "100 N", "60 N", "10 N"], "answer": 1, "explanation": "Weight = mg = 60 × 1.67 ≈ 100 N, roughly one-sixth of the Earth weight.", "topic": "Physics – Gravitation"}, {"q": "The gravitational potential energy of a satellite of mass m at height R/2 above Earth (R = Earth's radius) is:", "options": ["−GMm/R", "−(3/2)GMm/R", "−(2/3)GMm/R", "−(1/3)GMm/R"], "answer": 2, "explanation": "U = −GMm/r with r = R + R/2 = 3R/2, giving U = −GMm/(3R/2) = −(2/3)GMm/R.", "topic": "Physics – Gravitation"}, {"q": "The acceleration due to gravity is maximum at the:", "options": ["Equator", "45° latitude", "Tropics", "Poles"], "answer": 3, "explanation": "Earth's rotation reduces apparent gravity most at the equator, and the polar radius is smallest, so g peaks at the poles.", "topic": "Physics – Gravitation"}, {"q": "If Earth suddenly stopped rotating, the apparent weight of an object at the equator would:", "options": ["Increase slightly", "Decrease slightly", "Become zero", "Double"], "answer": 0, "explanation": "Rotation currently subtracts a centrifugal term mω²R from apparent weight; stopping rotation removes it, so apparent weight rises.", "topic": "Physics – Gravitation"}, {"q": "Satellite A orbits at radius r and satellite B at radius 4r around the same planet. The ratio of their orbital speeds vA/vB is:", "options": ["4", "2", "1/2", "1/4"], "answer": 1, "explanation": "Orbital speed is √(GM/r), so vA/vB = √(4r/r) = 2.", "topic": "Physics – Gravitation"}, {"q": "A wheel rotates at 300 revolutions per minute. Its angular velocity is:", "options": ["5π rad/s", "20π rad/s", "10π rad/s", "300π rad/s"], "answer": 2, "explanation": "ω = 2π × (revolutions per second) = 2π × 5 = 10π rad/s.", "topic": "Physics – Circular Motion"}, {"q": "A particle completes 120 revolutions in one minute. Its time period is:", "options": ["2 s", "1 s", "120 s", "0.5 s"], "answer": 3, "explanation": "120 revolutions in 60 s means 2 per second, so one revolution takes 0.5 s.", "topic": "Physics – Circular Motion"}, {"q": "A particle moves in a circle of radius 0.5 m with angular speed 4 rad/s. Its centripetal acceleration is:", "options": ["8 m/s²", "16 m/s²", "4 m/s²", "2 m/s²"], "answer": 0, "explanation": "Centripetal acceleration = ω²r = 16 × 0.5 = 8 m/s².", "topic": "Physics – Circular Motion"}, {"q": "A frictionless banked curve of radius 100 m is designed for 20 m/s (g = 10 m/s²). The banking angle satisfies:", "options": ["tan θ = 0.2", "tan θ = 0.4", "tan θ = 2.5", "tan θ = 4.0"], "answer": 1, "explanation": "For a banked turn tan θ = v²/(rg) = 400/1000 = 0.4.", "topic": "Physics – Circular Motion"}, {"q": "The minimum speed at the top of a vertical circular loop of radius R needed to stay on the track is:", "options": ["√(2gR)", "√(gR/2)", "√(gR)", "2√(gR)"], "answer": 2, "explanation": "At the top, mg alone must supply the centripetal force: mg = mv²/R, giving v = √(gR).", "topic": "Physics – Circular Motion"}, {"q": "A particle completes a vertical circle. The tension at the bottom exceeds the tension at the top by:", "options": ["2mg", "4mg", "3mg", "6mg"], "answer": 3, "explanation": "With the minimum speed to complete the circle, v_top² = gR gives T_top = 0; energy conservation gives v_bottom² = 5gR so T_bottom = 6mg, and the difference is 6mg.", "topic": "Physics – Circular Motion"}, {"q": "A conical pendulum has string length 1 m at 60° to the vertical (g = 10 m/s²). Its time period is about:", "options": ["1.4 s", "2.0 s", "2.8 s", "0.7 s"], "answer": 0, "explanation": "T = 2π√(L cos θ/g) = 2π√(0.5/10) ≈ 2π × 0.2236 ≈ 1.4 s.", "topic": "Physics – Circular Motion"}, {"q": "A particle's speed is halved and its orbital radius is doubled. Its centripetal acceleration becomes:", "options": ["a/2", "a/8", "a/4", "2a"], "answer": 1, "explanation": "a = v²/r; the new value is (v/2)²/(2r) = v²/(8r) = a/8.", "topic": "Physics – Circular Motion"}, {"q": "A coin rests on a rotating turntable. In the rotating frame, the coin experiences:", "options": ["A force mω²r toward the centre", "A force mω²r away from the centre", "A tangential force mαr", "No force at all"], "answer": 2, "explanation": "In the rotating frame a centrifugal pseudo-force mω²r acts radially outward on the coin.", "topic": "Physics – Circular Motion"}, {"q": "A projectile is launched at 30° with speed 20 m/s (g = 10 m/s²). Its horizontal range is about:", "options": ["20 m", "40 m", "17.3 m", "34.6 m"], "answer": 3, "explanation": "Range = u² sin 2θ/g = 400 × sin 60°/10 = 40 × 0.866 ≈ 34.6 m.", "topic": "Physics – Projectile Motion"}, {"q": "A projectile is launched at 30° with speed 50 m/s (g = 10 m/s²). Its time of flight is:", "options": ["5 s", "10 s", "2.5 s", "8.66 s"], "answer": 0, "explanation": "Time of flight = 2u sin θ/g = 2 × 50 × 0.5/10 = 5 s.", "topic": "Physics – Projectile Motion"}, {"q": "A projectile launched at 45° with speed 20√2 m/s follows y = x − x²/80 (g = 10 m/s²). The point (40 m, 20 m) is:", "options": ["Above the trajectory", "On the trajectory", "Below the trajectory", "At the vertex"], "answer": 1, "explanation": "Substituting x = 40 gives y = 40 − 1600/80 = 20, exactly the point's height, so it lies on the trajectory.", "topic": "Physics – Projectile Motion"}, {"q": "A projectile is launched at 60° with speed 20 m/s (g = 10 m/s²). Its speed at half the maximum height is about:", "options": ["10 m/s", "12.2 m/s", "15.8 m/s", "17.3 m/s"], "answer": 2, "explanation": "Horizontal speed stays 10 m/s; at half the 15 m max height, vertical speed² = 300 − 150 = 150, so v = √(100 + 150) ≈ 15.8 m/s.", "topic": "Physics – Projectile Motion"}, {"q": "A ball is thrown horizontally at 30 m/s from a 45 m high cliff (g = 10 m/s²). It lands at a horizontal distance of:", "options": ["45 m", "60 m", "30 m", "90 m"], "answer": 3, "explanation": "Fall time = √(2 × 45/10) = 3 s; range = 30 × 3 = 90 m.", "topic": "Physics – Projectile Motion"}, {"q": "A projectile is launched at 30° with speed 30 m/s (g = 10 m/s²). Its maximum height is:", "options": ["11.25 m", "22.5 m", "5.6 m", "45 m"], "answer": 0, "explanation": "H = u² sin²θ/(2g) = 900 × 0.25/20 = 11.25 m.", "topic": "Physics – Projectile Motion"}, {"q": "Two projectiles are launched with the same speed at 30° and 60°. The ratio of their maximum heights is:", "options": ["1:1", "1:3", "1:2", "3:1"], "answer": 1, "explanation": "Max height scales as sin²θ, so the ratio is sin²30°/sin²60° = 0.25/0.75 = 1/3.", "topic": "Physics – Projectile Motion"}, {"q": "A projectile is launched at 60° with speed 40 m/s (g = 10 m/s²). Its speed at the highest point is:", "options": ["0", "40 m/s", "20 m/s", "34.6 m/s"], "answer": 2, "explanation": "At the top the vertical component vanishes, leaving only u cos θ = 40 × 0.5 = 20 m/s.", "topic": "Physics – Projectile Motion"}, {"q": "Two projectiles A (30°) and B (60°) are launched with equal speeds. The ratio of their times of flight TA/TB is:", "options": ["√3", "1/2", "2", "1/√3"], "answer": 3, "explanation": "Time of flight scales as sin θ, so TA/TB = sin 30°/sin 60° = 0.5/0.866 = 1/√3.", "topic": "Physics – Projectile Motion"}, {"q": "For the differential equation (d²y/dx²)² = 1 + (dy/dx)², the order and degree are:", "options": ["Order 2, degree 2", "Order 2, degree 1", "Order 1, degree 2", "Order 3, degree 1"], "answer": 0, "explanation": "The highest derivative is d²y/dx² (order 2) and it appears squared (degree 2).", "topic": "Maths – Differential Equations"}, {"q": "The differential equation of the family of curves y = Aeˣ + Be⁻ˣ is:", "options": ["d²y/dx² + y = 0", "d²y/dx² = y", "dy/dx = y", "d²y/dx² = 2y"], "answer": 1, "explanation": "Differentiating twice returns the same exponentials: y′ = Aeˣ − Be⁻ˣ and y″ = Aeˣ + Be⁻ˣ = y.", "topic": "Maths – Differential Equations"}, {"q": "The solution of dy/dx = (x + 1)/y is:", "options": ["y² = x² + C", "y = x² + 2x + C", "y² = x² + 2x + C", "2y = x² + 2x + C"], "answer": 2, "explanation": "Separating gives y dy = (x + 1)dx, integrating to y²/2 = x²/2 + x + C₁, i.e. y² = x² + 2x + C.", "topic": "Maths – Differential Equations"}, {"q": "The general solution of dy/dx = y/x is:", "options": ["y = Cx²", "y = C/x", "y = C + x", "y = Cx"], "answer": 3, "explanation": "dy/y = dx/x integrates to ln|y| = ln|x| + C₁, giving y = Cx.", "topic": "Maths – Differential Equations"}, {"q": "The solution of dy/dx = (x + y)/x is:", "options": ["y = x ln|x| + Cx", "y = x ln|x|", "y = Cx²", "y = x² + Cx"], "answer": 0, "explanation": "This is homogeneous; setting y = vx gives x dv/dx = 1, so v = ln|x| + C and y = x ln|x| + Cx.", "topic": "Maths – Differential Equations"}, {"q": "The general solution of dy/dx + y = eˣ is:", "options": ["y = eˣ + Ce⁻ˣ", "y = eˣ/2 + Ce⁻ˣ", "y = 2eˣ + Ce⁻ˣ", "y = eˣ/2 + Ceˣ"], "answer": 1, "explanation": "The integrating factor is eˣ, giving y·eˣ = ∫e²ˣdx = e²ˣ/2 + C, so y = eˣ/2 + Ce⁻ˣ.", "topic": "Maths – Differential Equations"}, {"q": "The solution of dy/dx + y tan x = sec x is:", "options": ["y = cos x + C sin x", "y = sin x + C", "y = sin x + C cos x", "y = tan x + C"], "answer": 2, "explanation": "The integrating factor is sec x; then y sec x = ∫sec²x dx = tan x + C, giving y = sin x + C cos x.", "topic": "Maths – Differential Equations"}, {"q": "The particular solution of dy/dx = 3x² with y(1) = 2 is:", "options": ["y = x³", "y = x³ + 2", "y = x³ − 1", "y = x³ + 1"], "answer": 3, "explanation": "Integrating gives y = x³ + C; the condition y(1) = 2 fixes C = 1.", "topic": "Maths – Differential Equations"}, {"q": "The solution of dy/dx = eˣ⁺ʸ is:", "options": ["eˣ + e⁻ʸ = C", "eˣ − e⁻ʸ = C", "eˣ⁺ʸ = C", "eˣ · e⁻ʸ = C"], "answer": 0, "explanation": "Separating: e⁻ʸdy = eˣdx; integrating gives −e⁻ʸ = eˣ + C₁, i.e. eˣ + e⁻ʸ = C.", "topic": "Maths – Differential Equations"}, {"q": "For x(dy/dx)³ + y = d²y/dx², the order and degree are:", "options": ["Order 3, degree 1", "Order 2, degree 1", "Order 2, degree 3", "Order 1, degree 2"], "answer": 1, "explanation": "The highest derivative is d²y/dx² appearing to the first power: order 2, degree 1.", "topic": "Maths – Differential Equations"}, {"q": "The orthogonal trajectories of the family y = kx² are:", "options": ["x² + y² = C", "x² + 4y² = C", "x² + 2y² = C", "2x² + y² = C"], "answer": 2, "explanation": "From y = kx², dy/dx = 2y/x; orthogonal trajectories satisfy dy/dx = −x/(2y), giving x² + 2y² = C.", "topic": "Maths – Differential Equations"}, {"q": "A bacterial culture satisfies dN/dt = 0.02N. Its doubling time is about:", "options": ["50 yr", "25 yr", "20 yr", "34.7 yr"], "answer": 3, "explanation": "N = N₀e^{0.02t}; doubling needs e^{0.02t} = 2, so t = ln 2/0.02 ≈ 34.7 yr.", "topic": "Maths – Differential Equations"}, {"q": "The particular solution of dy/dx = sin x cos x with y(0) = 1 is:", "options": ["y = (sin²x)/2 + 1", "y = (sin²x)/2", "y = −(cos²x)/2 + 1", "y = (sin 2x)/4 + 1"], "answer": 0, "explanation": "∫sin x cos x dx = (sin²x)/2; the condition y(0) = 1 gives the constant 1.", "topic": "Maths – Differential Equations"}, {"q": "The y-intercept of the line 3x − 4y = 12 is:", "options": ["4", "−3", "3", "−4"], "answer": 1, "explanation": "Setting x = 0 gives −4y = 12, so y = −3.", "topic": "Maths – Straight Lines"}, {"q": "The slope of the line joining (2, 5) and (6, 13) is:", "options": ["4", "1/2", "2", "8"], "answer": 2, "explanation": "Slope = (13 − 5)/(6 − 2) = 8/4 = 2.", "topic": "Maths – Straight Lines"}, {"q": "The equation of the line through (1, 2) with slope 3 is:", "options": ["y = 3x + 1", "y = 3x − 5", "y = x + 1", "y = 3x − 1"], "answer": 3, "explanation": "Using y − 2 = 3(x − 1) gives y = 3x − 1.", "topic": "Maths – Straight Lines"}, {"q": "The line through (1, 1) parallel to 2x + 3y = 6 is:", "options": ["2x + 3y = 5", "3x + 2y = 5", "2x + 3y = 6", "x + y = 2"], "answer": 0, "explanation": "A parallel line has the form 2x + 3y = c; through (1,1), c = 5.", "topic": "Maths – Straight Lines"}, {"q": "The line through the origin perpendicular to 3x − 4y = 7 is:", "options": ["3x + 4y = 0", "4x + 3y = 0", "4x − 3y = 0", "3x − 4y = 0"], "answer": 1, "explanation": "The given slope is 3/4, so the perpendicular slope is −4/3; through the origin this is 4x + 3y = 0.", "topic": "Maths – Straight Lines"}, {"q": "The distance of the point (1, 2) from the line 3x + 4y = 10 is:", "options": ["1", "5", "1/5", "1/25"], "answer": 2, "explanation": "Distance = |3 + 8 − 10|/√(9 + 16) = 1/5.", "topic": "Maths – Straight Lines"}, {"q": "The distance between the parallel lines 3x + 4y = 5 and 3x + 4y = 15 is:", "options": ["1", "4", "5", "2"], "answer": 3, "explanation": "Distance = |15 − 5|/√(9 + 16) = 10/5 = 2.", "topic": "Maths – Straight Lines"}, {"q": "The acute angle between lines of slopes 1 and −1 is:", "options": ["90°", "45°", "60°", "0°"], "answer": 0, "explanation": "tan θ = |(1 − (−1))/(1 + (1)(−1))| is infinite, so θ = 90°.", "topic": "Maths – Straight Lines"}, {"q": "The x- and y-intercepts of x + y = 1 are respectively:", "options": ["2 and 2", "1 and 1", "1 and −1", "0 and 1"], "answer": 1, "explanation": "Setting y = 0 gives x = 1 and setting x = 0 gives y = 1.", "topic": "Maths – Straight Lines"}, {"q": "The foot of the perpendicular from the origin to the line x + y = 2 is:", "options": ["(2, 0)", "(0, 2)", "(1, 1)", "(2, 2)"], "answer": 2, "explanation": "By symmetry the closest point on x + y = 2 to the origin is (1, 1).", "topic": "Maths – Straight Lines"}, {"q": "The reflection of the point (2, 3) in the y-axis is:", "options": ["(2, −3)", "(−2, −3)", "(3, 2)", "(−2, 3)"], "answer": 3, "explanation": "Reflection in the y-axis negates the x-coordinate: (−2, 3).", "topic": "Maths – Straight Lines"}, {"q": "The centroid of the triangle with vertices (1, 2), (7, 2) and (1, 8) is:", "options": ["(3, 4)", "(4, 3)", "(3, 3)", "(8/3, 4)"], "answer": 0, "explanation": "The centroid is the average of the vertices: ((1+7+1)/3, (2+2+8)/3) = (3, 4).", "topic": "Maths – Straight Lines"}, {"q": "The slope of the tangent to y = x² at x = 2 is:", "options": ["2", "4", "8", "1"], "answer": 1, "explanation": "dy/dx = 2x; at x = 2 the slope is 4.", "topic": "Maths – Applications of Derivatives"}, {"q": "The equation of the tangent to y = x³ at (1, 1) is:", "options": ["y = x", "y = 3x + 2", "y = 3x − 2", "y = 2x − 1"], "answer": 2, "explanation": "Slope = 3x² = 3 at (1,1); the tangent is y − 1 = 3(x − 1), i.e. y = 3x − 2.", "topic": "Maths – Applications of Derivatives"}, {"q": "The equation of the normal to y = x² at (1, 1) is:", "options": ["2x + y = 3", "x + y = 2", "y = 2 − x", "x + 2y = 3"], "answer": 3, "explanation": "The tangent slope is 2, so the normal slope is −1/2; through (1,1): y − 1 = −(x − 1)/2, i.e. x + 2y = 3.", "topic": "Maths – Applications of Derivatives"}, {"q": "For f(x) = x⁴ − 4x³, the local minimum occurs at x =", "options": ["3", "0", "4", "1"], "answer": 0, "explanation": "f′ = 4x³ − 12x² = 4x²(x − 3); f″ = 12x² − 24x is positive at x = 3, confirming a minimum there.", "topic": "Maths – Applications of Derivatives"}, {"q": "The maximum value of sin x + cos x is:", "options": ["1", "√2", "2", "1/√2"], "answer": 1, "explanation": "sin x + cos x = √2 sin(x + π/4), whose maximum is √2.", "topic": "Maths – Applications of Derivatives"}, {"q": "The function f(x) = eˣ + x is:", "options": ["Decreasing everywhere", "Increasing for x > 0 only", "Increasing everywhere", "Constant"], "answer": 2, "explanation": "f′(x) = eˣ + 1 > 0 for all x, so the function increases everywhere.", "topic": "Maths – Applications of Derivatives"}, {"q": "Two positive numbers sum to 12. Their maximum possible product is:", "options": ["32", "30", "35", "36"], "answer": 3, "explanation": "For fixed sum the product is maximised when the numbers are equal: 6 × 6 = 36.", "topic": "Maths – Applications of Derivatives"}, {"q": "The side of a square increases at 3 cm/s. When the side is 5 cm, its area increases at:", "options": ["30 cm²/s", "15 cm²/s", "45 cm²/s", "60 cm²/s"], "answer": 0, "explanation": "A = s² gives dA/dt = 2s·ds/dt = 2 × 5 × 3 = 30 cm²/s.", "topic": "Maths – Applications of Derivatives"}, {"q": "Using differentials, an approximation of ∛28 is:", "options": ["3.01", "3.037", "3.1", "2.99"], "answer": 1, "explanation": "Near x = 27: Δy ≈ (1/3)x^{−2/3}Δx = (1/27)(1), so ∛28 ≈ 3 + 1/27 ≈ 3.037.", "topic": "Maths – Applications of Derivatives"}, {"q": "The function f(x) = x³ − 6x² + 9x + 1 is strictly decreasing on:", "options": ["(−∞, 1)", "(1, 3)", "(3, ∞)", "(0, 1)"], "answer": 2, "explanation": "f′ = 3x² − 12x + 9 = 3(x − 1)(x − 3) < 0 exactly on (1, 3).", "topic": "Maths – Applications of Derivatives"}, {"q": "Rolle's theorem applied to f(x) = x² − 4x on [0, 4] gives c =", "options": ["1", "3", "4", "2"], "answer": 3, "explanation": "f(0) = f(4) = 0, and f′(x) = 2x − 4 = 0 gives c = 2 in (0, 4).", "topic": "Maths – Applications of Derivatives"}, {"q": "The number of ways to choose 4 people from 12 is:", "options": ["495", "11880", "990", "792"], "answer": 0, "explanation": "C(12, 4) = 12×11×10×9/24 = 495.", "topic": "Maths – Permutations & Combinations"}, {"q": "The number of distinct words that can be formed from the letters of APPLE is:", "options": ["120", "60", "30", "20"], "answer": 1, "explanation": "5 letters with P repeated twice: 5!/2! = 60.", "topic": "Maths – Permutations & Combinations"}, {"q": "The number of distinct arrangements of the letters of MISSISSIPPI is:", "options": ["11880", "69300", "34650", "41580"], "answer": 2, "explanation": "11 letters with repeats 4, 4, 2: 11!/(4!4!2!) = 34650.", "topic": "Maths – Permutations & Combinations"}, {"q": "A team needs 2 men from 5 and 3 women from 4. The number of possible teams is:", "options": ["20", "60", "10", "40"], "answer": 3, "explanation": "C(5, 2) × C(4, 3) = 10 × 4 = 40.", "topic": "Maths – Permutations & Combinations"}, {"q": "The number of ways to seat 6 people around a round table is:", "options": ["120", "720", "60", "36"], "answer": 0, "explanation": "Circular arrangements of n distinct people: (6 − 1)! = 120.", "topic": "Maths – Permutations & Combinations"}, {"q": "From 5 distinct objects, the number of non-empty selections is:", "options": ["32", "31", "25", "10"], "answer": 1, "explanation": "Every object is either in or out (2⁵ ways) minus the empty selection: 32 − 1 = 31.", "topic": "Maths – Permutations & Combinations"}, {"q": "The number of 3-letter codes (no repetition) from 7 distinct letters is:", "options": ["343", "105", "210", "840"], "answer": 2, "explanation": "P(7, 3) = 7 × 6 × 5 = 210.", "topic": "Maths – Permutations & Combinations"}, {"q": "The number of 3-digit numbers with distinct digits chosen from 1–6 is:", "options": ["216", "180", "60", "120"], "answer": 3, "explanation": "6 choices for the first digit, 5 for the second, 4 for the third: 6 × 5 × 4 = 120.", "topic": "Maths – Permutations & Combinations"}, {"q": "The number of ways to distribute 4 identical balls into 3 distinct boxes is:", "options": ["15", "81", "12", "24"], "answer": 0, "explanation": "Stars and bars: C(4 + 3 − 1, 3 − 1) = C(6, 2) = 15.", "topic": "Maths – Permutations & Combinations"}, {"q": "From 7 people, the number of 2-member subcommittees is:", "options": ["14", "21", "42", "49"], "answer": 1, "explanation": "C(7, 2) = 21.", "topic": "Maths – Permutations & Combinations"}, {"q": "The number of shortest paths along grid lines from (0,0) to (3,3) moving only right or up is:", "options": ["9", "36", "20", "12"], "answer": 2, "explanation": "Choose the positions of the 3 right moves among 6 total moves: C(6, 3) = 20.", "topic": "Maths – Permutations & Combinations"}, {"q": "The number of one-one functions from a 3-element set to a 5-element set is:", "options": ["125", "243", "15", "60"], "answer": 3, "explanation": "Choose distinct images in order: P(5, 3) = 5 × 4 × 3 = 60.", "topic": "Maths – Sets & Functions"}, {"q": "The number of onto functions from a 4-element set to a 3-element set is:", "options": ["36", "81", "48", "24"], "answer": 0, "explanation": "Inclusion–exclusion: 3⁴ − 3·2⁴ + 3·1⁴ = 81 − 48 + 3 = 36.", "topic": "Maths – Sets & Functions"}, {"q": "If n(A) = 20, n(B) = 30 and n(A ∩ B) = 12, then n(A ∪ B) equals:", "options": ["50", "38", "62", "8"], "answer": 1, "explanation": "n(A ∪ B) = 20 + 30 − 12 = 38.", "topic": "Maths – Sets & Functions"}, {"q": "The number of bijections from a 5-element set to itself is:", "options": ["25", "32", "120", "243"], "answer": 2, "explanation": "A bijection is a permutation: 5! = 120.", "topic": "Maths – Sets & Functions"}, {"q": "The function f: R → R, f(x) = x², is:", "options": ["One-one but not onto", "Onto but not one-one", "Bijective", "Neither one-one nor onto"], "answer": 3, "explanation": "f(−1) = f(1) so it is not one-one, and negative values have no pre-image so it is not onto.", "topic": "Maths – Sets & Functions"}, {"q": "If f(x) = 2x and g(x) = x + 1, then (f ∘ g)(x) equals:", "options": ["2x + 2", "2x + 1", "x + 3", "4x"], "answer": 0, "explanation": "(f ∘ g)(x) = f(g(x)) = 2(x + 1) = 2x + 2.", "topic": "Maths – Sets & Functions"}, {"q": "The inverse of f(x) = 3x − 2 is:", "options": ["(x − 2)/3", "(x + 2)/3", "3x + 2", "x/3 + 2"], "answer": 1, "explanation": "Set y = 3x − 2 and solve for x: x = (y + 2)/3, so f⁻¹(x) = (x + 2)/3.", "topic": "Maths – Sets & Functions"}, {"q": "The number of symmetric relations on a 4-element set is:", "options": ["256", "512", "1024", "4096"], "answer": 2, "explanation": "Symmetric relations are determined by the 4 diagonal and C(4,2) off-diagonal pairs: 2^{4+6} = 1024.", "topic": "Maths – Sets & Functions"}, {"q": "The number of equivalence relations on the set {1, 2, 3} is:", "options": ["3", "6", "4", "5"], "answer": 3, "explanation": "Equivalence relations correspond to set partitions; {1,2,3} has 5 partitions (Bell number B₃).", "topic": "Maths – Sets & Functions"}, {"q": "The range of f(x) = |x − 1| for x in [0, 2] is:", "options": ["[0, 1]", "[−1, 1]", "[0, 2]", "[1, 2]"], "answer": 0, "explanation": "|x − 1| is 0 at x = 1 and rises to 1 at both endpoints, so the range is [0, 1].", "topic": "Maths – Sets & Functions"}, {"q": "By De Morgan's law, the complement of A ∪ B is:", "options": ["A′ ∪ B′", "A′ ∩ B′", "A ∩ B", "A ∪ B"], "answer": 1, "explanation": "De Morgan's law: (A ∪ B)′ = A′ ∩ B′.", "topic": "Maths – Sets & Functions"}, {"q": "The correct order of ionic radii is:", "options": ["Al³⁺ > Mg²⁺ > Na⁺", "Mg²⁺ > Na⁺ > Al³⁺", "Na⁺ > Mg²⁺ > Al³⁺", "Na⁺ > Al³⁺ > Mg²⁺"], "answer": 2, "explanation": "These ions are isoelectronic; the one with the fewest protons (Na⁺) is largest: Na⁺ > Mg²⁺ > Al³⁺.", "topic": "Chemistry – Periodic Table"}, {"q": "Among Li, Be, B and C, the element with the highest first ionisation energy is:", "options": ["Li", "Be", "B", "C"], "answer": 3, "explanation": "First ionisation energy rises across the period with effective nuclear charge, so C is highest of the four.", "topic": "Chemistry – Periodic Table"}, {"q": "The correct order of electronegativity is:", "options": ["C < N < O < F", "F < O < N < C", "N < C < F < O", "C < O < N < F"], "answer": 0, "explanation": "Electronegativity increases across a period: C < N < O < F, with fluorine the most electronegative element.", "topic": "Chemistry – Periodic Table"}, {"q": "Among Na, K, Rb and Cs, the most metallic element is:", "options": ["Na", "Cs", "K", "Rb"], "answer": 1, "explanation": "Metallic character increases down a group as the outer electron is lost more easily; Cs is the most metallic.", "topic": "Chemistry – Periodic Table"}, {"q": "Which of the following oxides is amphoteric?", "options": ["Na₂O", "MgO", "Al₂O₃", "SiO₂"], "answer": 2, "explanation": "Al₂O₃ reacts with both acids and bases, which is the definition of amphoteric.", "topic": "Chemistry – Periodic Table"}, {"q": "The diagonal relationship in the periodic table exists between:", "options": ["Na and K", "Li and Mg", "Be and B", "Mg and Ca"], "answer": 1, "explanation": "Li and Mg show similar properties (diagonal relationship), as do Be and Al.", "topic": "Chemistry – Periodic Table"}, {"q": "The correct order of oxidising power of the halogens is:", "options": ["F₂ > Cl₂ > Br₂ > I₂", "I₂ > Br₂ > Cl₂ > F₂", "Cl₂ > F₂ > Br₂ > I₂", "F₂ > Br₂ > Cl₂ > I₂"], "answer": 0, "explanation": "Oxidising strength falls down the group as electron affinity and electrode potential decrease.", "topic": "Chemistry – Periodic Table"}, {"q": "Which noble gas readily forms fluorides such as XeF₂ and XeF₄?", "options": ["He", "Xe", "Ne", "Ar"], "answer": 1, "explanation": "Xenon's large size and low ionisation energy let it form XeF₂, XeF₄, XeF₆ and oxides.", "topic": "Chemistry – Periodic Table"}, {"q": "The element with the most exothermic first electron affinity among O, N, S, Se is:", "options": ["O", "N", "S", "Se"], "answer": 2, "explanation": "Sulphur's electron affinity is the most exothermic of these; oxygen's small size causes electron–electron repulsion that reduces its value.", "topic": "Chemistry – Periodic Table"}, {"q": "First ionisation energy is higher for Mg than for Al because:", "options": ["Mg is larger than Al", "Al has a filled 3s subshell", "Al has higher nuclear charge", "Mg has a filled 3s subshell"], "answer": 3, "explanation": "Magnesium's filled 3s² subshell is extra stable, so removing its electron costs more energy than removing Al's lone 3p electron.", "topic": "Chemistry – Periodic Table"}, {"q": "The correct order of ionic size for N³⁻, O²⁻ and F⁻ is:", "options": ["N³⁻ > O²⁻ > F⁻", "F⁻ > O²⁻ > N³⁻", "O²⁻ > F⁻ > N³⁻", "N³⁻ > F⁻ > O²⁻"], "answer": 0, "explanation": "These are isoelectronic; fewer protons means weaker pull, so N³⁻ (7 protons) is largest.", "topic": "Chemistry – Periodic Table"}, {"q": "In period 3, the element with the largest atomic radius is:", "options": ["Cl", "Na", "Mg", "Si"], "answer": 1, "explanation": "Atomic radius decreases across a period, so sodium at the start of period 3 is largest.", "topic": "Chemistry – Periodic Table"}, {"q": "Which element exhibits the +8 oxidation state in its tetroxide?", "options": ["Mn", "Fe", "Os", "Ru"], "answer": 2, "explanation": "Osmium forms OsO₄ with osmium in the +8 state, the highest oxidation state known.", "topic": "Chemistry – Periodic Table"}, {"q": "The lanthanide contraction is caused by:", "options": ["Strong shielding by 4f electrons", "Increasing atomic number", "Poor shielding by 4f electrons", "Relativistic effects only"], "answer": 2, "explanation": "The 4f electrons shield the nuclear charge poorly, so the radius steadily shrinks across the lanthanides.", "topic": "Chemistry – Periodic Table"}, {"q": "Which of the following oxides is strongly acidic?", "options": ["SO₃", "CaO", "Na₂O", "MgO"], "answer": 0, "explanation": "Non-metal oxides like SO₃ form acids in water (H₂SO₄); the others are basic metal oxides.", "topic": "Chemistry – Periodic Table"}, {"q": "Doubling [A] doubles the reaction rate and doubling [B] quadruples it. The overall order of the reaction is:", "options": ["2", "3", "4", "1"], "answer": 1, "explanation": "The rate is first order in A and second order in B, so the overall order is 1 + 2 = 3.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "For a first-order reaction, the fraction of reactant remaining after three half-lives is:", "options": ["1/3", "1/6", "1/8", "1/4"], "answer": 2, "explanation": "Each half-life halves the amount: (1/2)³ = 1/8 remains.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "A first-order reaction is 75% complete in 40 min. Its half-life is:", "options": ["40 min", "10 min", "80 min", "20 min"], "answer": 3, "explanation": "75% completion means two half-lives have passed (1 → 1/2 → 1/4), so t½ = 40/2 = 20 min.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "A reaction with Ea = 60 kJ/mol is warmed from 300 K to 310 K. By what factor does k increase? (R = 8.314 J/mol·K)", "options": ["2.2", "1.5", "3.0", "4.0"], "answer": 0, "explanation": "ln(k₂/k₁) = (60000/8.314)(1/300 − 1/310) ≈ 0.776, so k₂/k₁ = e^{0.776} ≈ 2.2.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "For a mechanism whose slow step is A + B → C, the rate law is:", "options": ["r = k[C]", "r = k[A][B]", "r = k[A]²[B]", "r = k[A][B]²"], "answer": 1, "explanation": "The rate-determining step is the slow one, and its molecularity gives the rate law: r = k[A][B].", "topic": "Chemistry – Chemical Kinetics"}, {"q": "The molecularity of the elementary step 2A → products is:", "options": ["1", "3", "2", "0"], "answer": 2, "explanation": "Molecularity counts the reacting species in the elementary step: two molecules of A, so it is bimolecular (2).", "topic": "Chemistry – Chemical Kinetics"}, {"q": "A zero-order reaction has [A]₀ = 0.8 M and k = 0.02 M/min. Its half-life is:", "options": ["40 min", "10 min", "34.7 min", "20 min"], "answer": 3, "explanation": "For zero order t½ = [A]₀/(2k) = 0.8/0.04 = 20 min.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "A second-order reaction (single reactant) has k = 0.5 L/mol·min and [A]₀ = 0.2 M. Its half-life is:", "options": ["10 min", "20 min", "5 min", "2.5 min"], "answer": 0, "explanation": "For second order t½ = 1/(k[A]₀) = 1/(0.5 × 0.2) = 10 min.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "A catalyst increases the reaction rate by:", "options": ["Raising the average molecular energy", "Providing an alternative path of lower activation energy", "Increasing the equilibrium constant", "Decreasing ΔH of the reaction"], "answer": 1, "explanation": "A catalyst opens a lower-Ea pathway; it changes neither ΔH nor the equilibrium constant.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "For the reaction 2A → B, the rate of disappearance of A and the rate of appearance of B are related by:", "options": ["−d[A]/dt = d[B]/dt", "−(1/2)d[A]/dt = d[B]/dt", "−2d[A]/dt = d[B]/dt", "−d[A]/dt = 2d[B]/dt"], "answer": 2, "explanation": "The unique reaction rate is −(1/2)d[A]/dt = d[B]/dt, dividing by stoichiometric coefficients.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "The concentration of A falls from 0.60 M to 0.20 M in 10 min. The average rate of disappearance of A is:", "options": ["0.02 M/min", "0.06 M/min", "0.08 M/min", "0.04 M/min"], "answer": 3, "explanation": "Average rate = −Δ[A]/Δt = 0.40/10 = 0.04 M/min.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "The unit of the rate constant k for the rate law r = k[A]^{1/2} is:", "options": ["mol^{1/2}·L^{−1/2}·s⁻¹", "mol^{−1/2}·L^{1/2}·s⁻¹", "mol·L⁻¹·s⁻¹", "mol^{1/2}·L^{−1/2}·s"], "answer": 0, "explanation": "Rate (mol·L⁻¹·s⁻¹) = k·(mol·L⁻¹)^{1/2}, so k has units mol^{1/2}·L^{−1/2}·s⁻¹.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "The oxidation number of S in Na₂S₂O₃ is:", "options": ["+6", "+2", "−2", "+4"], "answer": 1, "explanation": "2(+1) + 2x + 3(−2) = 0 gives 2x = 4, so x = +2 (the average over the two sulphur atoms).", "topic": "Chemistry – Redox Reactions"}, {"q": "The oxidation number of I in HIO₃ is:", "options": ["+3", "+1", "+5", "+7"], "answer": 2, "explanation": "(+1) + x + 3(−2) = 0 gives x = +5.", "topic": "Chemistry – Redox Reactions"}, {"q": "In the reaction 2H₂S + SO₂ → 3S + 2H₂O, the reducing agent is:", "options": ["SO₂", "S", "H₂O", "H₂S"], "answer": 3, "explanation": "Sulphur in H₂S goes from −2 to 0 (oxidised), so H₂S is the reducing agent.", "topic": "Chemistry – Redox Reactions"}, {"q": "The reaction of Cl₂ with cold dilute NaOH (Cl₂ + 2OH⁻ → Cl⁻ + ClO⁻ + H₂O) is an example of:", "options": ["Disproportionation", "Comproportionation", "Neutralisation", "Decomposition"], "answer": 0, "explanation": "Chlorine is simultaneously oxidised (to ClO⁻) and reduced (to Cl⁻): disproportionation.", "topic": "Chemistry – Redox Reactions"}, {"q": "The n-factor of KMnO₄ in acidic medium is:", "options": ["3", "5", "2", "7"], "answer": 1, "explanation": "Mn goes from +7 to +2, a gain of 5 electrons per formula unit.", "topic": "Chemistry – Redox Reactions"}, {"q": "The n-factor of K₂Cr₂O₇ in acidic medium is:", "options": ["3", "2", "6", "4"], "answer": 2, "explanation": "Each Cr goes from +6 to +3 (3 electrons), and there are 2 Cr atoms: n-factor 6.", "topic": "Chemistry – Redox Reactions"}, {"q": "The equivalent weight of oxalic acid (molar mass 90, n-factor 2) is:", "options": ["90", "30", "60", "45"], "answer": 3, "explanation": "Equivalent weight = molar mass / n-factor = 90/2 = 45.", "topic": "Chemistry – Redox Reactions"}, {"q": "When MnO₄⁻ oxidises Fe²⁺ in acidic medium, the stoichiometry is:", "options": ["5 Fe²⁺ ions are oxidised per MnO₄⁻ ion", "1 Fe²⁺ ion is oxidised per MnO₄⁻ ion", "2 Fe²⁺ ions are oxidised per MnO₄⁻ ion", "10 Fe²⁺ ions are oxidised per MnO₄⁻ ion"], "answer": 0, "explanation": "MnO₄⁻ gains 5 electrons while each Fe²⁺ loses 1, so 5 Fe²⁺ are oxidised per MnO₄⁻.", "topic": "Chemistry – Redox Reactions"}, {"q": "The oxidation number of C in CH₃OH is:", "options": ["0", "−2", "−4", "+2"], "answer": 1, "explanation": "x + 4(+1) + (−2) = 0 gives x = −2.", "topic": "Chemistry – Redox Reactions"}, {"q": "Which of the following is NOT a redox reaction?", "options": ["Zn + CuSO₄ → ZnSO₄ + Cu", "C + O₂ → CO₂", "NaOH + HCl → NaCl + H₂O", "2H₂ + O₂ → 2H₂O"], "answer": 2, "explanation": "Acid–base neutralisation involves no change in oxidation numbers; the others do.", "topic": "Chemistry – Redox Reactions"}, {"q": "The number of tetrahedral voids per FCC unit cell is:", "options": ["4", "12", "6", "8"], "answer": 3, "explanation": "An FCC cell has 4 atoms and 2 tetrahedral voids per atom, giving 8.", "topic": "Chemistry – Solid State"}, {"q": "In zinc blende (ZnS), the Zn²⁺ ions occupy:", "options": ["Half the tetrahedral voids", "All the octahedral voids", "Half the octahedral voids", "All the tetrahedral voids"], "answer": 0, "explanation": "S²⁻ forms an FCC lattice and Zn²⁺ occupies half of its tetrahedral voids.", "topic": "Chemistry – Solid State"}, {"q": "The radius-ratio range for octahedral voids is:", "options": ["0.155–0.225", "0.414–0.732", "0.732–1.0", "0.225–0.414"], "answer": 1, "explanation": "A cation fits an octahedral void when r⁺/r⁻ lies between 0.414 and 0.732.", "topic": "Chemistry – Solid State"}, {"q": "For the NaCl structure, the edge length a is related to the ionic radii by:", "options": ["a = √2(r⁺ + r⁻)", "a = 4(r⁺ + r⁻)/√3", "a = 2(r⁺ + r⁻)", "a = r⁺ + r⁻"], "answer": 2, "explanation": "Along the edge, Na⁺ and Cl⁻ touch: a = 2(r⁺ + r⁻).", "topic": "Chemistry – Solid State"}, {"q": "Copper is FCC with edge length 361 pm. Its density is about:", "options": ["7.14 g/cm³", "10.5 g/cm³", "2.70 g/cm³", "8.96 g/cm³"], "answer": 3, "explanation": "ρ = ZM/(N_A a³) = 4 × 63.5/(6.022×10²³ × (3.61×10⁻⁸)³) ≈ 8.96 g/cm³.", "topic": "Chemistry – Solid State"}, {"q": "The packing efficiency of an FCC lattice is:", "options": ["74%", "68%", "52%", "100%"], "answer": 0, "explanation": "FCC (and HCP) achieve the maximum 74% space utilisation.", "topic": "Chemistry – Solid State"}, {"q": "A Schottky defect:", "options": ["Leaves the density unchanged", "Decreases the density", "Increases the density", "Converts the lattice to amorphous"], "answer": 1, "explanation": "Equal numbers of cations and anions are missing, so mass is lost and density falls.", "topic": "Chemistry – Solid State"}, {"q": "A Frenkel defect:", "options": ["Decreases density", "Increases density", "Leaves density unchanged", "Creates extra unit cells"], "answer": 2, "explanation": "An ion merely shifts to an interstitial site; no ions leave, so density is unchanged.", "topic": "Chemistry – Solid State"}, {"q": "In a close-packed arrangement, the number of octahedral voids per atom is:", "options": ["2", "4", "8", "1"], "answer": 3, "explanation": "Close packing gives 1 octahedral and 2 tetrahedral voids per atom.", "topic": "Chemistry – Solid State"}, {"q": "In graphite, each carbon atom is:", "options": ["sp² hybridised in hexagonal layers", "sp³ hybridised in a 3D network", "sp hybridised in chains", "Un hybridised"], "answer": 0, "explanation": "Graphite has planar hexagonal layers of sp² carbons with delocalised π electrons.", "topic": "Chemistry – Solid State"}, {"q": "The IUPAC name of [Cr(NH₃)₃(H₂O)₃]Cl₃ is:", "options": ["Triaquatriamminechromium(III) chloride", "Triamminetriaquachromium(III) chloride", "Chromium(III) triammine triaqua chloride", "Hexaamminechromium(III) chloride"], "answer": 1, "explanation": "Ligands are named alphabetically (ammine before aqua), then the metal with its oxidation state: triamminetriaquachromium(III) chloride.", "topic": "Chemistry – Coordination Compounds"}, {"q": "The effective atomic number (EAN) of Fe in [Fe(CO)₅] is:", "options": ["34", "35", "36", "38"], "answer": 2, "explanation": "EAN = 26 − 0 + 2 × 5 = 36, the krypton configuration.", "topic": "Chemistry – Coordination Compounds"}, {"q": "The number of geometrical isomers of [Pt(NH₃)₂Cl₂] is:", "options": ["1", "3", "4", "2"], "answer": 3, "explanation": "Square planar MA₂B₂ shows cis and trans forms: 2 isomers.", "topic": "Chemistry – Coordination Compounds"}, {"q": "Which of the following complexes shows optical isomerism?", "options": ["[Co(en)₃]³⁺", "[Pt(NH₃)₂Cl₂]", "[Ni(CO)₄]", "[Fe(CN)₆]⁴⁻"], "answer": 0, "explanation": "[Co(en)₃]³⁺ is chiral (Δ and Λ forms); the others have planes of symmetry.", "topic": "Chemistry – Coordination Compounds"}, {"q": "The correct increasing field-strength order (spectrochemical series) is:", "options": ["CO < CN⁻ < NH₃ < F⁻", "I⁻ < F⁻ < H₂O < NH₃ < CO", "H₂O < I⁻ < NH₃ < CO", "F⁻ < I⁻ < CO < NH₃"], "answer": 1, "explanation": "Field strength rises I⁻ < Br⁻ < Cl⁻ < F⁻ < H₂O < NH₃ < en < CN⁻ < CO.", "topic": "Chemistry – Coordination Compounds"}, {"q": "In an octahedral crystal field, the d-orbitals split so that:", "options": ["eg is lower than t2g", "t2g is lower than eg", "All five remain degenerate", "dz² alone is lowest"], "answer": 1, "explanation": "The t2g set (dxy, dyz, dzx) points between ligands and lies lower; eg points at ligands and lies higher.", "topic": "Chemistry – Coordination Compounds"}, {"q": "The number of unpaired electrons in [FeF₆]³⁻ is:", "options": ["1", "3", "2", "5"], "answer": 3, "explanation": "F⁻ is a weak-field ligand, so Fe(III) (d⁵) stays high-spin with 5 unpaired electrons.", "topic": "Chemistry – Coordination Compounds"}, {"q": "[Co(NH₃)₅NO₂]²⁺ and [Co(NH₃)₅ONO]²⁺ are:", "options": ["Linkage isomers", "Geometrical isomers", "Ionisation isomers", "Coordination isomers"], "answer": 0, "explanation": "The nitrite ligand binds through N in one and through O in the other: linkage isomerism.", "topic": "Chemistry – Coordination Compounds"}, {"q": "The coordination number of Fe in [Fe(C₂O₄)₃]³⁻ is:", "options": ["3", "6", "4", "8"], "answer": 1, "explanation": "Oxalate is bidentate and there are three of them: 3 × 2 = 6.", "topic": "Chemistry – Coordination Compounds"}, {"q": "The greater stability of [Cu(en)₂]²⁺ over [Cu(NH₃)₄]²⁺ is called the:", "options": ["Trans effect", "Jahn–Teller effect", "Chelate effect", "Nephelauxetic effect"], "answer": 2, "explanation": "Chelating (polydentate) ligands give extra stability — the chelate effect, largely entropy-driven.", "topic": "Chemistry – Coordination Compounds"}, {"q": "A parallel-plate capacitor has plate area 0.02 m² and plate separation 1 mm, filled with a dielectric of dielectric constant 4. When it is charged to 100 V, the energy stored in it is:", "options": ["3.54 μJ", "7.08 μJ", "1.77 μJ", "35.4 μJ"], "answer": 0, "explanation": "C = ε₀KA/d = 8.85×10⁻¹² × 4 × 0.02/0.001 = 7.08×10⁻¹⁰ F. Energy U = ½CV² = 0.5 × 7.08×10⁻¹⁰ × 100² = 3.54×10⁻⁶ J = 3.54 μJ.", "topic": "Physics – Capacitors"}, {"q": "Light of wavelength 400 nm falls on a metal surface whose work function is 2.0 eV. The maximum kinetic energy of the emitted photoelectrons is:", "options": ["1.1 eV", "2.0 eV", "3.1 eV", "5.1 eV"], "answer": 0, "explanation": "Photon energy hν = hc/λ = 1240/400 = 3.1 eV. K_max = hν − φ = 3.1 − 2.0 = 1.1 eV (Einstein's photoelectric equation).", "topic": "Physics – Modern Physics"}, {"q": "A uniform disc of mass 2 kg and radius 0.5 m spins at 60 rpm. A constant tangential force of 1 N is applied at the rim to bring it to rest. The time taken to stop is:", "options": ["3.14 s", "6.28 s", "1.57 s", "12.56 s"], "answer": 0, "explanation": "τ = FR = 0.5 N·m; I = ½MR² = 0.25 kg·m²; α = τ/I = 2 rad/s². ω = 60 rpm = 2π rad/s, so t = ω/α = π ≈ 3.14 s.", "topic": "Physics – Rotational Motion"}, {"q": "The complex ion [Co(CN)₆]³⁻ is low-spin octahedral with a d⁶ configuration. Its crystal field stabilization energy is:", "options": ["−2.4Δ₀", "−0.6Δ₀", "−1.8Δ₀", "−2.4Δ₀ + 2P"], "answer": 0, "explanation": "Low-spin d⁶ = t2g⁶ eg⁰. CFSE = 6(−0.4Δ₀) + 0(0.6Δ₀) = −2.4Δ₀ (CN⁻ is a strong-field ligand, so pairing wins over Δ₀).", "topic": "Chemistry – Coordination Compounds"}, {"q": "A first-order reaction has rate constant 2.303 × 10⁻³ s⁻¹. The time required for 90% completion of the reaction is:", "options": ["1000 s", "500 s", "2000 s", "300 s"], "answer": 0, "explanation": "t = (2.303/k) log([A]₀/[A]) = (2.303/2.303×10⁻³) × log 10 = 1000 s.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "One mole of an ideal gas expands isothermally and reversibly from 2 L to 20 L at 300 K. The entropy change of the gas (R = 8.314 J mol⁻¹ K⁻¹) is:", "options": ["19.15 J/K", "8.314 J/K", "57.44 J/K", "0"], "answer": 0, "explanation": "ΔS = nR ln(V₂/V₁) = 1 × 8.314 × ln 10 = 8.314 × 2.303 ≈ 19.15 J K⁻¹.", "topic": "Chemistry – Thermodynamics"}, {"q": "The value of the definite integral from 0 to π of x/(1 + sin x) dx is:", "options": ["π", "π/2", "2π", "0"], "answer": 0, "explanation": "King property: write the integral for (π − x)/(1 + sin x) and add. 2I = π ∫₀^π dx/(1 + sin x) = 2π (since ∫ dx/(1 + sin x) = tan x − sec x evaluates to 2 over 0 to π), so I = π.", "topic": "Maths – Definite Integrals"}, {"q": "A leap year is chosen at random. The probability that it has 53 Sundays is:", "options": ["2/7", "1/7", "3/7", "1/2"], "answer": 0, "explanation": "A leap year has 366 days = 52 full weeks + 2 extra days. The 2 extra days form 7 equally likely pairs ((Sun,Mon), …, (Sat,Sun)), of which 2 contain a Sunday — so P = 2/7.", "topic": "Maths – Probability"}, {"q": "A particle starts from rest and moves with constant acceleration. If it covers 100 m during the 5th second of its motion, the acceleration is:", "options": ["20 m/s²", "22.2 m/s²", "25 m/s²", "18 m/s²"], "answer": 1, "explanation": "Distance covered in the nth second: s(n) = u + a(2n−1)/2. With u = 0 and n = 5: 100 = a×9/2, so a = 200/9 ≈ 22.2 m/s².", "topic": "Physics – Kinematics"}, {"q": "A wire of resistance 12 Ω is bent into a circle. The equivalent resistance between two diametrically opposite points is:", "options": ["6 Ω", "3 Ω", "12 Ω", "24 Ω"], "answer": 1, "explanation": "Each semicircle has resistance 6 Ω; the two halves are in parallel between the opposite points: R = (6×6)/(6+6) = 3 Ω.", "topic": "Physics – Current Electricity"}, {"q": "The number of molecules present in 4.4 g of carbon dioxide is:", "options": ["6.022×10²³", "6.022×10²²", "3.011×10²³", "1.204×10²³"], "answer": 1, "explanation": "Molar mass of CO₂ = 44 g/mol, so 4.4 g = 0.1 mol = 0.1 × 6.022×10²³ = 6.022×10²² molecules.", "topic": "Chemistry – Mole Concept"}, {"q": "Which of the following ions has the largest ionic radius?", "options": ["Na⁺", "Mg²⁺", "Al³⁺", "O²⁻"], "answer": 3, "explanation": "Na⁺, Mg²⁺, Al³⁺ and O²⁻ are isoelectronic (10 electrons). Ionic size decreases as nuclear charge increases, so the anion O²⁻ — with the smallest nuclear charge — is the largest.", "topic": "Chemistry – Periodic Table"}, {"q": "If α and β are the roots of x² − 5x + 6 = 0, then α² + β² equals:", "options": ["25", "13", "12", "37"], "answer": 1, "explanation": "α + β = 5 and αβ = 6, so α² + β² = (α+β)² − 2αβ = 25 − 12 = 13.", "topic": "Maths – Quadratic Equations"}, {"q": "Two dice are thrown simultaneously. The probability that the sum of the numbers shown is 9 equals:", "options": ["1/9", "1/6", "5/36", "1/12"], "answer": 0, "explanation": "Favourable outcomes are (3,6), (4,5), (5,4) and (6,3) — 4 out of 36 equally likely outcomes, so P = 4/36 = 1/9.", "topic": "Maths – Probability"}, {"q": "As per the NTA examination calendar, JEE Main 2027 Session 1 is scheduled on:", "options": ["15–20 January 2027", "22, 23, 24, 28, 29 and 30 January 2027", "1–6 February 2027", "5–10 April 2027"], "answer": 1, "explanation": "The NTA calendar lists JEE Main 2027 Session 1 on 22, 23, 24, 28, 29 and 30 January 2027 (31 January as buffer); Session 2 follows in early–mid April 2027.", "topic": "Exam Info – Schedule"}, {"q": "JEE Main 2027 Session 1 online registration is expected to begin in:", "options": ["First week of September 2026", "Last week of October 2026", "First week of January 2027", "Last week of February 2027"], "answer": 1, "explanation": "As reported on 28 September 2026, NTA is expected to open the Session 1 application window in the last week of October 2026, with the deadline in late November 2026.", "topic": "Exam Info – Schedule"}, {"q": "As reported on 28 September 2026, NTA has advised JEE Main 2027 aspirants to _____ before the Session 1 registration opens.", "options": ["ensure their Aadhaar details (name, date of birth, photograph) are updated", "obtain a fresh PAN card at an enrolment centre", "register only through the DigiLocker portal", "submit offline application forms at NTA offices"], "answer": 0, "explanation": "NTA's advisory asks aspirants to get Aadhaar details — name, date of birth and photograph — updated/matched well before Session 1 registration, since Aadhaar-based verification is used in the application process.", "topic": "Exam Info – 29 Sep 2026"}, {"q": "According to NTA's tentative 2027 examination calendar (public notice, 16 September 2026), JEE Main 2027 Session 1 is proposed to be held on", "options": ["22–24 and 28–30 January 2027, with 31 January 2027 as buffer", "10–12 April 2027 only", "1–3 February 2027, with no buffer day", "15–17 March 2027 in a single shift"], "answer": 0, "explanation": "The tentative NTA calendar proposes Session 1 on 22–24 and 28–30 January 2027 with 31 January 2027 as buffer; the detailed notification with the final schedule is still awaited.", "topic": "Exam Info – 29 Sep 2026"}, {"q": "In September 2026, astronomers reported the first detection of auroral radio emission from the exoplanet β Pictoris b using the MeerKAT array, inferring a magnetic field of at least 1,250 gauss where the radio waves are produced. For an electron in this field, the cyclotron (gyro) frequency f = eB/(2πm) is closest to", "options": ["3.5 GHz", "35 MHz", "350 kHz", "3.5 THz"], "answer": 0, "explanation": "f = eB/(2πm) = (1.6×10⁻¹⁹ × 0.125)/(2π × 9.1×10⁻³¹) ≈ 3.5×10⁹ Hz = 3.5 GHz (using B = 1250 G = 0.125 T). The 22 September 2026 detection is the first auroral radio signal from an exoplanet.", "topic": "Physics – Magnetism"}, {"q": "The Canadian Hydrogen Intensity Mapping Experiment (CHIME) reported in September 2026 the most detailed map of the 21-cm glow of neutral hydrogen. The 21-cm line arises from", "options": ["the hyperfine spin-flip transition of the hydrogen ground state", "electron capture in helium nuclei", "the Balmer series transition n = 3 → 2", "molecular hydrogen vibrational bands"], "answer": 0, "explanation": "The 21-cm line is the hyperfine spin-flip transition of neutral hydrogen's ground state (parallel to antiparallel electron-proton spins), a key probe of the cosmic dark ages and dark energy via intensity mapping.", "topic": "Physics – Modern Physics"}, {"q": "A JWST study (Nature Astronomy, 24 September 2026) found galaxies enriched with heavy elements far earlier than expected, implying rapid early baryon cycling. In Big Bang nucleosynthesis, the heaviest element produced in significant amounts was", "options": ["helium", "carbon", "oxygen", "iron"], "answer": 0, "explanation": "BBN produced mainly H, He (~25% by mass) and traces of Li/Be — nothing heavier in bulk. Heavy elements need stellar nucleosynthesis, so early enrichment implies fast first-star formation and supernova cycling.", "topic": "Chemistry – Atomic Structure"}, {"q": "A solid sphere of mass 2 kg and radius 0.1 m rolls without slipping down an incline, reaching v = 4 m/s at the bottom. Its total kinetic energy is", "options": ["22.4 J", "16 J", "11.2 J", "32 J"], "answer": 0, "explanation": "KE = ½mv² + ½Iω² = ½mv²(1 + 2/5) = 0.7 × 2 × 16 = 22.4 J, using I = (2/5)mr² and ω = v/r for rolling without slipping.", "topic": "Physics – Rotational Mechanics"}, {"q": "The value of k for which the determinant |1 2 3; 4 5 6; 7 8 k| equals zero is", "options": ["9", "6", "12", "0"], "answer": 0, "explanation": "det = 1(5k−48) − 2(4k−42) + 3(32−35) = 5k − 48 − 8k + 84 − 9 = −3k + 27 = 0 ⇒ k = 9.", "topic": "Maths – Matrices & Determinants"}, {"q": "A Daniell cell Zn(s)|Zn²⁺(0.1 M)||Cu²⁺(0.01 M)|Cu(s) has E° = 1.10 V. Its emf at 298 K is", "options": ["1.13 V", "1.10 V", "1.07 V", "1.04 V"], "answer": 2, "explanation": "E = E° − (0.0591/2)log([Zn²⁺]/[Cu²⁺]) = 1.10 − 0.0296×log(10) = 1.10 − 0.0296 ≈ 1.07 V. Wait: log(0.1/0.01) = log 10 = 1, so E = 1.10 − 0.0296 = 1.070 V. The cell reaction Zn + Cu2+ -> Zn2+ + Cu has n = 2.", "topic": "Chemistry – Electrochemistry"}, {"q": "The number N(t) of atoms of a radioisotope follows dN/dt = −kN with N(0) = N₀. The half-life is 30 min when the initial concentration is 0.4 M. If the experiment is repeated with initial concentration 0.1 M, the half-life will be", "options": ["30 min", "120 min", "7.5 min", "60 min"], "answer": 0, "explanation": "First-order decay: t½ = ln2/k, independent of initial concentration. So the half-life stays 30 min. (The concentration data is a distractor testing whether you confuse this with zero/second-order kinetics.)", "topic": "Chemistry – Chemical Kinetics"}, {"q": "For a reaction, the half-life is 30 minutes when the initial concentration is 0.4 mol L⁻¹ and 60 minutes when it is 0.2 mol L⁻¹. The order of the reaction is", "options": ["2", "1", "0", "3"], "answer": 0, "explanation": "t½ ∝ 1/aⁿ⁻¹. Halving a doubles t½ ⇒ 1/aⁿ⁻¹ doubles ⇒ n−1 = 1 ⇒ n = 2. Second order.", "topic": "Chemistry – Chemical Kinetics"},{"q": "JEE Main 2027 Session 1 will be held on:","options": ["22, 23, 24, 28, 29 and 30 January 2027","2–10 January 2027","15–22 January 2027","1–6 February 2027"],"answer": 0,"explanation": "The reported NTA schedule is 22, 23, 24, 28, 29 and 30 January 2027 with 31 January as a buffer; registration at jeemain.nta.nic.in is expected to begin soon.","topic": "Exam Info – 29 Sep 2026"},{"q": "From the 2026–27 academic year, NTA will allot exam cities for JEE, NEET and CUET on the basis of:","options": ["The address on the candidate's Aadhaar card","The candidate's first preference choice","The distance from the nearest metro","Random computerized allotment"],"answer": 0,"explanation": "NTA announced exam cities will be allotted from the candidate's Aadhaar address, with no choice of cities; only candidates awaiting Aadhaar enrolment may choose.","topic": "Exam Info – 29 Sep 2026"},{"q": "A solid sphere of mass 2 kg and radius 0.1 m rolls without slipping at 5 m/s. Its total kinetic energy is:","options": ["35 J","25 J","45 J","30 J"],"answer": 0,"explanation": "KE = translational + rotational = ½mv² + ½Iω² = ½(2)(25) + ½(2/5·mr²)(v/r)² = 25 + 10 = 35 J.","topic": "Physics – Rotational Motion"},{"q": "Two point charges +4 μC and −1 μC are 30 cm apart. The point where the net electric field is zero lies:","options": ["60 cm from the +4 μC charge, on the side of the −1 μC charge","10 cm from the +4 μC charge, between them","30 cm from the −1 μC charge, on the outer side","20 cm from the +4 μC charge, between them"],"answer": 0,"explanation": "Zero field lies outside, nearer the smaller charge: x/(x+30) = √(1/4) = 1/2 gives x = 30 cm from −1 μC, i.e. 60 cm from +4 μC.","topic": "Physics – Electrostatics"},{"q": "For the reaction N₂ + 3H₂ ⇌ 2NH₃, Kc = 0.5 at 400°C. The value of Kp at the same temperature is approximately:","options": ["1.6 × 10⁻⁴","0.5 × (RT)²","Equal to Kc","0.5 × (RT)"],"answer": 0,"explanation": "Δn = 2 − 4 = −2; Kp = Kc(RT)^Δn = 0.5/(0.0821 × 673)² ≈ 0.5/3052 ≈ 1.64 × 10⁻⁴.","topic": "Chemistry – Chemical Equilibrium"},{"q": "The IUPAC name of K₃[Fe(CN)₆] is:","options": ["Potassium hexacyanoferrate(III)","Potassium hexacyanoferrate(II)","Tripotassium hexacyanoiron(III)","Potassium ferricyanide"],"answer": 0,"explanation": "Fe oxidation state: 3(+1) + x + 6(−1) = 0 ⇒ x = +3; the anionic complex takes the ‘ferrate(III)’ name.","topic": "Chemistry – Coordination Compounds"},{"q": "The value of the definite integral from 0 to 1 of x squared dx is:","options": ["1/3","1/2","1","2/3"],"answer": 0,"explanation": "The antiderivative of x squared is x cubed over 3; evaluated from 0 to 1 it gives 1/3.","topic": "Maths – Definite Integration"},{"q": "If z = 3 + 4i, then the modulus of z equals:","options": ["5","7","25","1"],"answer": 0,"explanation": "|z| = square root of (3 squared + 4 squared) = square root of 25 = 5.","topic": "Maths – Complex Numbers"}, {"q": "In an experiment, the period of a simple pendulum is measured as T = (2.00 ± 0.02) s and the length as l = (1.00 ± 0.01) m. The percentage error in the value of g = 4π²l/T² is approximately:", "options": ["1.0%", "2.0%", "3.0%", "4.0%"], "answer": 2, "explanation": "Percentage error in g = % error in l + 2 × % error in T = 1.0% + 2 × 1.0% = 3.0%.", "topic": "Physics · Errors and Measurement"}, {"q": "A particle moves along the x-axis with velocity v = 3t² - 12t + 9 (SI units). The distance travelled between t = 0 and t = 4 s is:", "options": ["0 m", "8 m", "16 m", "24 m"], "answer": 2, "explanation": "v = 0 at t = 1 s and t = 3 s. Integrating |v| over [0,1], [1,3], [3,4]: 4 + 8 + 4 = 16 m.", "topic": "Physics · Kinematics"}, {"q": "The pH of a 0.001 M solution of acetic acid (Ka = 1.8 × 10⁻⁵) is approximately:", "options": ["3.37", "4.74", "5.37", "6.00"], "answer": 0, "explanation": "[H+] ≈ sqrt(Ka·C) = sqrt(1.8 × 10⁻⁸) ≈ 4.24 × 10⁻⁴, so pH ≈ 3.37.", "topic": "Chemistry · Ionic Equilibrium"}, {"q": "The number of geometrical isomers of [Co(NH3)4Cl2]+ is:", "options": ["1", "2", "3", "4"], "answer": 1, "explanation": "The octahedral complex [Co(NH3)4Cl2]+ shows cis-trans geometrical isomerism: two isomers.", "topic": "Chemistry · Coordination Compounds"}, {"q": "If the lines x + 2y - 3 = 0 and 2x + ky + 5 = 0 are perpendicular, the value of k is:", "options": ["-1", "-4", "1", "4"], "answer": 0, "explanation": "Slopes are m1 = -1/2 and m2 = -2/k. Perpendicular: m1·m2 = -1 ⇒ (-1/2)(−2/k) = 1/k = -1 ⇒ k = -1.", "topic": "Mathematics · Straight Lines"}, {"q": "A coil of 100 turns and area 0.01 m² rotates at 50 rev/s in a uniform magnetic field of 0.5 T. The maximum induced emf is approximately:", "options": ["15.7 V", "31.4 V", "157 V", "314 V"], "answer": 2, "explanation": "emax = NBAω = 100 × 0.5 × 0.01 × (2π × 50) = 50π ≈ 157 V.", "topic": "Physics · Electromagnetic Induction"}, {"q": "In an experiment, the period of a simple pendulum is measured as T = (3.00 ± 0.01) s and the length as l = (2.25 ± 0.02) m. The percentage error in g = 4π²l/T² is approximately:", "options": ["0.9%", "1.6%", "2.3%", "3.2%"], "answer": 1, "explanation": "Percentage error in g = % error in l + 2 × % error in T = (0.02/2.25)×100 + 2×(0.01/3.00)×100 ≈ 0.89% + 0.67% ≈ 1.6%.", "topic": "Physics · Errors and Measurement"}, {"q": "A projectile is launched at 60° with speed 20 m/s (g = 10 m/s²). Its time of flight is:", "options": ["2 s", "2√3 s", "√3 s", "4 s"], "answer": 1, "explanation": "Time of flight = 2u sinθ/g = 2 × 20 × sin60°/10 = 2√3 s.", "topic": "Physics · Projectile Motion"}, {"q": "The number of stereoisomers of [Cr(ox)3]3− (ox = oxalate, bidentate) is:", "options": ["1", "2", "3", "4"], "answer": 1, "explanation": "[Cr(ox)3]3− is a tris-chelate complex with D3 symmetry; it exists as a pair of optical isomers (Δ and Λ): 2 stereoisomers.", "topic": "Chemistry · Coordination Compounds"}, {"q": "For the cell Zn(s)|Zn2+(1 M)||Cu2+(1 M)|Cu(s), E°(Zn2+/Zn) = -0.76 V and E°(Cu2+/Cu) = +0.34 V. The standard emf of the cell is:", "options": ["1.10 V", "-1.10 V", "0.42 V", "-0.42 V"], "answer": 0, "explanation": "E°cell = E°cathode - E°anode = 0.34 - (-0.76) = 1.10 V.", "topic": "Chemistry · Electrochemistry"}, {"q": "The value of the limit lim(x→0) (sin 5x)/(3x) is:", "options": ["0", "5/3", "3/5", "1"], "answer": 1, "explanation": "lim(x→0) (sin 5x)/(3x) = (5/3) × lim(x→0) (sin 5x)/(5x) = 5/3 × 1 = 5/3.", "topic": "Mathematics · Limits"}, {"q": "If |z - (1 + i)| = 2, then the locus of z in the Argand plane is:", "options": ["a straight line", "a circle of radius 2", "a parabola", "a hyperbola"], "answer": 1, "explanation": "|z - (1 + i)| = 2 is the set of points at distance 2 from (1, 1) — a circle of radius 2 centred at (1, 1).", "topic": "Mathematics · Complex Numbers"}, {"q": "A stone is dropped from rest from a height of 80 m (take g = 10 m/s²). The time taken to reach the ground is:", "options": ["2 s", "3 s", "4 s", "8 s"], "answer": 2, "explanation": "t = √(2h/g) = √(160/10) = 4 s.", "topic": "Physics"}, {"q": "A projectile is launched at 60° with speed 20 m/s (g = 10 m/s²). Its time of flight is:", "options": ["1 s", "2 s", "2√3 s", "4 s"], "answer": 2, "explanation": "T = 2u sinθ/g = 2 × 20 × (√3/2)/10 = 2√3 s.", "topic": "Physics"}, {"q": "If the radius of the first Bohr orbit is 0.529 Å, the radius of the third orbit is:", "options": ["0.529 Å", "1.587 Å", "4.761 Å", "1.763 Å"], "answer": 2, "explanation": "r_n = 0.529 n² Å; for n = 3, r = 0.529 × 9 = 4.761 Å.", "topic": "Chemistry"}, {"q": "For the reaction 2A + B → products, rate = k[A]²[B]. If [A] is doubled and [B] is halved, the rate becomes:", "options": ["the same", "double", "four times", "eight times"], "answer": 1, "explanation": "New rate = k(2[A])²([B]/2) = 2k[A]²[B] — twice the original rate.", "topic": "Chemistry"}, {"q": "The IUPAC name of CH₃–CH=CH–CHO is:", "options": ["but-2-enal", "but-3-enal", "but-2-en-1-al", "crotonaldehyde"], "answer": 0, "explanation": "Numbering gives the –CHO carbon as C1: the double bond starts at C2 — but-2-enal.", "topic": "Chemistry"}, {"q": "The value of lim(x→0) (sin 5x)/x is:", "options": ["0", "1", "5", "1/5"], "answer": 2, "explanation": "lim(x→0) sin(ax)/x = a, so the limit equals 5.", "topic": "Maths"}, {"q": "The number of 4-digit numbers that can be formed using the digits 1–7 without repetition is:", "options": ["240", "480", "840", "1680"], "answer": 2, "explanation": "P(7,4) = 7 × 6 × 5 × 4 = 840.", "topic": "Maths"}];
